    [3147] = { "Розрив плоті", "Завдає {1} шкоди ворогу кожні {2} с протягом {3} с.#Inflicts {1} damage#every {2} sec#for {3} sec", "{1} шкоди кожні {2} с.#{1} damage#every {2} sec", en="Rend Flesh" },
