    [3594] = { "Тіньова олія", "При нанесенні на зброю ближнього бою дає {1}% ймовірності застосувати \"Тіньову стрілу ІІІ\" на опонента при ударі. Триває {2} хв.#a {1}% chance#Lasts {2} min", en="Shadow Oil" },
    [3595] = { "Крижана олія", "При нанесенні на зброю ближнього бою дає {1}% ймовірності застосувати \"Крижану стрілу\" на опонента при ударі. Триває {2} хв.#a {1}% chance#Lasts {2} min", en="Frost Oil" },
    [3599] = { "Тотем обпалення", "Викликає тотем обпалення з {1} здоров'я на {2} с. Тотем періодично атакує ворогів у радіусі {3} м, завдаючи від {4} до {5} шкоди вогнем.#with {1} health#for {2} sec#within {3} yards for {4} to {5} Fire", en="Searing Totem" },
    [3600] = { "Земне зв'язування", nil, "Швидкість руху зменшено на {1}%.#by {1}%", en="Earthbind" },
    [3603] = { "Мігрень", "Сповільнює вимову заклять ворогом на {1}% протягом {2} с.#by {1}% for {2} sec", "Вимову заклять сповільнено на {1}%.#by {1}%", en="Distracting Pain" },
    [3604] = { "Розрив сухожиль", "Зменшує швидкість руху ворога на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Tendon Rip" },
    [3609] = { "Паралітична отрута", "Приголомшує ворога, позбавляючи його можливості рухатися та атакувати на {1} с.#for {1} sec", "Приголомшено.", en="Paralyzing Poison" },
    [3627] = { "Омолодження", "Зцілює цілі {1} здоров'я протягом {2} с.#for {1} over {2} sec", "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Rejuvenation" },
    [3635] = { "Кришталевий погляд", ref=3609, en="Crystal Gaze" },
    [3650] = { "Кидок багнюки", "Кидає багнюку в очі ворога, знижуючи його шанс завдання удару на {1}% протягом {2} с.#by {1}% for {2} sec", "Ймовірність завдання удару зменшено на {1}%.#by {1}%", en="Sling Mud" },
    [3661] = { "Зцілення вихованця", "Відновлює вашому вихованцю {1} здоров'я щосекунди поки ви зосереджуєтеся на зціленні. Триває {2} с.#pet {1} health#Lasts {2} sec", "Відновлює {1} здоров'я щосекунди.#Heals {1}", en="Mend Pet" },
    [3662] = { "Зцілення вихованця", "Відновлює вашому вихованцю {1} здоров'я щосекунди поки ви зосереджуєтеся на зціленні. Триває {2} с.#pet {1} health#Lasts {2} sec", "Відновлює {1} здоров'я щосекунди.#Heals {1}", en="Mend Pet" },
    [3671] = { "Кам'яний удар", nil, "Завдану фізичну шкоду зменшено на {1}.#by {1}", en="Cracking Stone" },
    [3674] = { "Чорна стріла", "Випускає в ціль чорну стрілу, що зменшує швидкість руху на {1}%, завдає {2} шкоди від тіні та висмоктує {3} мани протягом {4} с.#speed by {1}%#causing {2} Shadow damage#draining {3} mana over {4} sec", "Швидкість руху зменшено на {1}%. Завдає {2} шкоди від тіні кожні {3} с. Висмоктує {4} мани кожні {5} с.#reduced by {1}%#Causes {2} Shadow damage every {3} sec#Drains {4} mana every {5} sec", en="Black Arrow" },
    [3680] = { "Мала невидимість", "Надає малу невидимість на {1} с.#for {1} sec", "Мала невидимість.", en="Lesser Invisibility" },
    [3698] = { "Канал здоров'я", "Передає прислужникові заклинача {1} здоров'я щосекунди протягом {2} с, поки заклинач підтримує це закляття.#Gives {1}#for {2} sec", "Передає здоров'я.", en="Health Funnel" },
    [3699] = { "Канал здоров'я", "Передає прислужникові заклинача {1} здоров'я щосекунди протягом {2} с, поки заклинач підтримує це закляття.#Gives {1}#for {2} sec", "Передає здоров'я.", en="Health Funnel" },
    [3700] = { "Канал здоров'я", "Передає прислужникові заклинача {1} здоров'я щосекунди протягом {2} с, поки заклинач підтримує це закляття.#Gives {1}#for {2} sec", "Передає здоров'я.", en="Health Funnel" },
    [3714] = { "Темний ритуал", en="Dark Ritual" },
    [3716] = { "Муки", "Провокує істоту, збільшуючи ймовірність того, що вона зосередить свої атаки на пустотнику.", en="Torment" },
    [3747] = { "Слово сили: Щит", "Створює з частинки душі учасника групи щит, що поглинає {1} шкоди. Триває {2} с. Поки щит тримається, отримана шкода не спричинить затримки вимови заклять. Повторно накласти щит на ціль можна тільки через {3} с.#absorbing {1}#Lasts {2} sec#again for {3} sec", "Поглинає шкоду.", en="Power Word: Shield" },
    [3811] = { "Шкірництво", "Дозволяє виготовляти майстерні шкіряні обладунки та розвивати навичку до 225 рівня.", en="Leatherworking" },
    [3815] = { "Отруйна хмара", "Завдає {1} шкоди від природи навколишнім ворогам кожні {2} с протягом {3} с.#Inflicts {1} Nature#every {2} sec#for {3} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Poison Cloud" },
    [3826] = { "Ефект оберега ліні", nil, "Інтервал між атаками збільшено на {1}%.#by {1}%", en="Ward of Laze effect" },
    [3908] = { "Кравецтво", "Дозволяє виготовляти прості тканинні обладунки та розвивати навичку до 75 рівня. Для виготовлення потрібна тканина, яку можна добути з гуманоїдів.", en="Tailoring" },
    [3909] = { "Кравецтво", "Дозволяє виготовляти стильні сорочки і тканинні обладунки та розвивати навичку до 150 рівня.", en="Tailoring" },
    [3910] = { "Кравецтво", "Дозволяє виготовляти надзвичайно стильні сорочки і тканинні обладунки та розвивати навичку до 225 рівня.", en="Tailoring" },
    [3974] = { "Кустарний приціл", "Оснащення лука або вогнепальної зброї прицілом, що збільшує шкоду на {1}.#damage by {1}", en="Crude Scope" },
    [3975] = { "Звичайний приціл", ref=3974, en="Standard Scope" },
    [3976] = { "Точний приціл", ref=3974, en="Accurate Scope" },
    [4036] = { "Інженерія", "Дозволяє створювати базові пристрої та розвивати навичку до 75 рівня. Потребує каміння й металу, які можна знайти за допомогою гірництва.", en="Engineering" },
    [4037] = { "Інженерія", "Дозволяє створювати потужніші пристрої і вибухівку та розвивати навичку до 150 рівня.", en="Engineering" },
    [4038] = { "Інженерія", "Дозволяє створювати дивовижні пристрої і вибухівку та розвивати навичку до 225 рівня.", en="Engineering" },
    [4042] = { "Зілля лікування", "Відновлює [{1}#Restores {1} health.][від {1} до {2}#Restores {1} to {2} health.] здоров'я.", en="Healing Potion" },
