    [4056] = { "Малий сифорієвий заряд", "Підриває прості замки.", en="Small Seaforium Charge" },
    [4057] = { "Опір вогню", "Поглинає {1} шкоди від вогню. Триває {2} хв.#Absorbs {1} fire#Lasts {2} min", "Поглинає {1} шкоди від вогню.#Absorbs {1} fire", en="Fire Resistance" },
    [4060] = { "Заплутаність", "Перетворює ціль на лепрогнома, зменшуючи її шкоду від атак в ближньому бою та заклинань на {1}, а швидкість руху - на {2}% протягом {3} с.#damage by {1} and#by {2}% for {3} sec", "Перетворено на лепрогнома. Шкоду від атак в ближньому бою та заклинань зменшено на {1}, а швидкість руху - на {2}% #by {1} and#by {2}%", en="Discombobulate" },
