    [4962] = { "Павутинна сітка", "Знерухомлює ворога та збільшує інтервал між його атаками на {1}% протягом {2} с.#by {1}% for {2} sec", "Знерухомлено.\nІнтервал між атаками збільшено на {1}%.#by {1}%", en="Encasing Webs" },
    [4974] = { "Дотик зав'ядання", "Зменшує витривалість ворога на {1} та дух на {2} протягом {3} хв.#Stamina by {1} and Spirit by {2} for {3} min", "Витривалість зменшено на {1}.\nДух зменшено на {2}.#Stamina reduced by {1}#Spirit reduced by {2}", en="Wither Touch" },
    [4987] = { "Очищення", "Очищає дружню ціль, усуваючи 1 ефект отруєння, 1 ефект хвороби та 1 магічний ефект.", en="Cleanse" },
    [5004] = { "Їжа", "Відновлює {1} здоров'я протягом {2} секунд. Потрібно залишатися в сидячому положенні під час їжі. Через {3} секунд ви насититесь і ваші витривалість та дух збільшаться на {4} протягом {5} хв.#Restores {1} health over {2} sec#at least {3} sec#gain {4} Stamina and Spirit for {5} min", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [5005] = { "Їжа", "Відновлює {1} здоров'я протягом {2} секунд. Потрібно залишатися в сидячому положенні під час їжі. Через {3} секунд ви насититесь і ваші витривалість та дух збільшаться на {4} протягом {5} хв.#Restores {1} health over {2} sec#at least {3} sec#gain {4} Stamina and Spirit for {5} min", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [5006] = { "Їжа", "Відновлює {1} здоров'я протягом {2} секунд. Потрібно залишатися в сидячому положенні під час їжі. Через {3} секунд ви насититесь і ваші витривалість та дух збільшаться на {4} протягом {5} хв.#Restores {1} health over {2} sec#at least {3} sec#gain {4} Stamina and Spirit for {5} min", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [5007] = { "Їжа", "Відновлює {1} здоров'я протягом {2} секунд. Потрібно залишатися в сидячому положенні під час їжі. Через {3} секунд ви насититесь і ваші витривалість та дух збільшаться на {4} протягом {5} хв.#Restores {1} health over {2} sec#at least {3} sec#gain {4} Stamina and Spirit for {5} min", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [5009] = { "Жезли", en="Wands" },
    [5010] = { "Палючий подих", "Завдає від {1} до {2} шкоди вогнем кожні {3} с ворогам у конусі перед заклиначем протягом {4} с.#Inflicts {1} to {2} Fire#every {3} sec#for {4} sec", "Отримання від {1} до {2} шкоди від вогню кожні {3} с.#{1} to {2} Fire#every {3} sec", en="Scorch Breath" },
