    [6615] = { "Невпинність", "Надає невразливість до приголомшення та ефектів обмеження руху на {1} с. Не знімає вже наявні ефекти.#next {1} sec", "Невпинність.", en="Free Action" },
    [6648] = { "Каштанова кобила", "Викликає та відпускає верхову каштанову кобилу.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Chestnut Mare" },
    [6653] = { "Темний вовк", "Викликає та відпускає верхового темного вовка.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Dire Wolf" },
    [6654] = { "Бурий вовк", "Викликає та відпускає верхового бурого вовка.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Brown Wolf" },
    [6673] = { "Бойовий клич", "Воїн кричить, збільшуючи силу атаки ближнього бою всіх учасників групи в межах {1} м на {2}. Триває {3} хв.#within {1} yards by {2}#Lasts {3} min", "Збільшує силу атаки ближнього бою на {1}.#power by {1}", en="Battle Shout" },
    [6685] = { "Пронизливий постріл", "Стріляє у ворога, завдаючи звичайної шкоди та зменшуючи його броню на {1} протягом {2} с.#by {1} for {2} sec", "Броню зменшено на {1}.#by {1}", en="Piercing Shot" },
    [6713] = { "Роззброєння", "Роззброює ворога, змушуючи його припинити використовувати зброю протягом {1} с.#weapon for {1} sec", "Не тримає в руках зброю.", en="Disarm" },
    [6724] = { "Сяйво Елуни", "Надає невразливість до шкоди та заклять на {1} с.#for {1} sec", "Невразливість до шкоди та заклять.", en="Light of Elune" },
    [6726] = { "Знемовлення", "Знемовлює ворога, унеможливлюючи вимову заклять протягом {1} с.#for {1} sec", "Не може вимовляти закляття.", en="Silence" },
    [6728] = { "Огортання вітрами", "Оточує ворога циклоном на {1} с. Якщо ціль отримає шкоду, вона звільниться з полону вітрів.#up to {1} sec", "Приголомшено.", en="Enveloping Winds" },
    [6744] = { "Їзда на баранах", "Дозволяє їздити на баранах.", en="Ram Riding" },
    [6751] = { "Слабка отрута", "Завдає ворогу {1} шкоди від природи кожні {2} с протягом {3} с.#Inflicts {1} Nature#every {2} sec#for {3} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Weak Poison" },
    [6756] = { "Знак дикої природи", "Збільшує броню дружньої цілі на {1} та всі характеристики на {2} протягом {3} хв.#armor by {1} and all attributes by {2} for {3} min", "Збільшує броню на {1} та всі характеристики на {2}.#armor by {1}#attributes by {2}", en="Mark of the Wild" },
    [6760] = { "Потрошіння", "Завершальний рух, що завдає шкоди залежно від довжини комбінації та сили атаки:\n  1 прийом: {1}-{2} шкоди\n  2 прийоми: {3}-{4} шкоди\n  3 прийоми: {5}-{6} шкоди\n  4 прийоми: {7}-{8} шкоди\n  5 прийомів: {9}-{10} шкоди#1 point  : {1}-{2}#2 points: {3}-{4}#3 points: {5}-{6}#4 points: {7}-{8}#5 points: {9}-{10}", en="Eviscerate" },
    [6761] = { "Потрошіння", "Завершальний рух, що завдає шкоди залежно від довжини комбінації та сили атаки:\n  1 прийом: {1}-{2} шкоди\n  2 прийоми: {3}-{4} шкоди\n  3 прийоми: {5}-{6} шкоди\n  4 прийоми: {7}-{8} шкоди\n  5 прийомів: {9}-{10} шкоди#1 point  : {1}-{2}#2 points: {3}-{4}#3 points: {5}-{6}#4 points: {7}-{8}#5 points: {9}-{10}", en="Eviscerate" },
    [6762] = { "Потрошіння", "Завершальний рух, що завдає шкоди залежно від довжини комбінації та сили атаки:\n  1 прийом: {1}-{2} шкоди\n  2 прийоми: {3}-{4} шкоди\n  3 прийоми: {5}-{6} шкоди\n  4 прийоми: {7}-{8} шкоди\n  5 прийомів: {9}-{10} шкоди#1 point  : {1}-{2}#2 points: {3}-{4}#3 points: {5}-{6}#4 points: {7}-{8}#5 points: {9}-{10}", en="Eviscerate" },
    [6768] = { "Фінт", "Виконує оманливий випад, що не завдає шкоди та зменшує вашу загрозу. Це знизить ймовірність того, що ворог атакуватиме саме вас.", en="Feint" },
    [6770] = { "Оглушення", ref=2070, en="Sap" },
    [6774] = { "М'ясорубка", "Завершальний рух, що збільшує швидкість атаки ближнього бою на {1}%. Тривалість залежить від довжини комбінації:\n  1 прийом: {2} с\n  2 прийоми: {3} с\n  3 прийоми: {4} с\n  4 прийоми: {5} с\n  5 прийомів: {6} с#speed by {1}%#1 point  : {2} sec#2 points: {3} sec#3 points: {4} sec#4 points: {5} sec#5 points: {6} sec", "Швидкість атаки ближнього бою збільшено на {1}%.#by {1}%", en="Slice and Dice" },
    [6777] = { "Сірий баран", "Викликає та відпускає верхового сірого барана.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Gray Ram" },
    [6778] = { "Цілющий дотик", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Touch" },
    [6780] = { "Гнів", "Завдає цілі від {1} до {2} шкоди від природи.#Causes {1} to {2}", en="Wrath" },
    [6783] = { "Зачаїтися", "Дозволяє друїду пересуватися непомітно, але зменшує швидкість руху на {1}%. Триває до скасування.#speed by {1}%", "Непомітність. Рух сповільнено на {1}%.#slowed by {1}%", en="Prowl" },
    [6785] = { "Знищення", "Нищить ціль, завдаючи їй {1}% шкоди плюс {2}. Друїд має зачаїтися і перебувати позаду цілі. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2}#{3} combo", en="Ravage" },
    [6787] = { "Знищення", "Нищить ціль, завдаючи їй {1}% шкоди плюс {2}. Друїд має зачаїтися і перебувати позаду цілі. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2}#{3} combo", en="Ravage" },
