    [6798] = { "Стусан", "Приголомшує ціль на {1} с.#for {1} sec", "Приголомшено.", en="Bash" },
    [6800] = { "Шматування", "Шматує ціль, завдаючи {1}% шкоди плюс {2}. Необхідно бути позаду цілі. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", en="Shred" },
    [6807] = { "Терзання", "Збільшує шкоду від наступної атаки на {1}.#by {1} damage", en="Maul" },
    [6808] = { "Терзання", "Збільшує шкоду від наступної атаки на {1}.#by {1} damage", en="Maul" },
    [6809] = { "Терзання", "Збільшує шкоду від наступної атаки на {1}.#by {1} damage", en="Maul" },
    [6814] = { "Шламовий токсин", "Завдає ворогу {1} шкоди від природи кожні {2} с, збільшуючи інтервал між атаками на {3}% і сповільнюючи його рух на {4}% протягом {5} с.#Inflicts {1} Nature#every {2} sec#attacks by {3}%#movement by {4}% for {5} sec", "{1} шкоди від природи кожні {2} с.\nІнтервал між атаками збільшено на {3}%.\nШвидкість руху зменшено на {4}%.#{1} Nature#every {2} sec#attacks increased by {3}%#speed reduced by {4}%", en="Sludge Toxin" },
