    [6907] = { "Хвороботворний слиз", "Збільшує інтервал між атаками ворога на {1}% та зменшує його швидкість руху на {2}% протягом {3} хв.#attacks by {1}%#movement by {2}% for {3} min", "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Diseased Slime" },
    [6909] = { "Прокляття шипів", "Проклинає ворога на {1} хв, внаслідок чого з ймовірністю {2}% при завданні удару він отримуватиме від {3} до {4} шкоди.#for {1} min#it {2}% chance to take {3} to {4} damage", "З ймовірністю {1}% отримає від {2} до {3} шкоди при атаці.#{1}% chance#take {2} to {3} damage", en="Curse of Thorns" },
    [6917] = { "Плювок отрути", "Плює у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Venom Spit" },
    [6922] = { "Прокляття тінерога", nil, "Отриману фізичну шкоду збільшено на {1}.\nЗавдану фізичну шкоду зменшено на {2}.\nЗавдану магічну шкоду зменшено на {3}.#taken is increased by {1}#Physical damage dealt is reduced by {2}#Magical damage dealt is reduced by {3}", en="Curse of the Shadowhorn" },
    [6940] = { "Благословення жертовності", "Благословляє учасника групи, передаючи {1} отриманої за удар шкоди до заклинача. Триває {2} с. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#transfering {1} damage taken#Lasts {2} sec", "Передає {1} отриманої за удар шкоди до паладина.#{1} damage taken", en="Blessing of Sacrifice" },
    [6942] = { "Нестерпний сморід", ref=6726, en="Overwhelming Stench" },
    [6950] = { "Чарівний вогонь", "Зменшує броню ворога на {1} протягом {2} хв. Під час дії ефекту ціль не може отримати ефект непомітності чи невидимості.#by {1} for {2} min", "Броню зменшено на {1}.\nНе може отримати ефект непомітності чи невидимості.#by {1}", en="Faerie Fire" },
    [6951] = { "Знесилення", "Зменшує силу ворога на {1} протягом {2} хв.#by {1} for {2} min", "Силу зменшено на {1}.#by {1}", en="Decayed Strength" },
    [6982] = { "Порив вітру", ref=6524, en="Gust of Wind" },
    [6991] = { "Годування вихованця", "Нагодувати вашого вихованця вибраним предметом. Годівля вихованця збільшує його щастя. Використання їжі рівня близького до рівня вихованця дасть кращий результат.", en="Feed Pet" },
    [7001] = { "Відновлення колодязя світла", nil, "Відновлює {1} здоров'я кожні {2} с.#{1} health every {2} sec", en="Lightwell Renew" },
