    [7054] = { "Зречення навичок", "Проклинає ворога на {1} хв, періодично зменшуючи одну з навичок на {2}.#for {1} min#by {2}", "Періодичне зменшення навичок.", en="Forsaken Skills" },
    [7057] = { "Одержимі духи", "Проклинає ворога на {1} хв, внаслідок чого його періодично переслідують злісні привиди.#for {1} min", "Вас переслідують духи...", en="Haunting Spirits" },
    [7068] = { "Завіса тіні", "Зменшує ефективність зцілення цілі на {1}% протягом {2} с.#by {1}% for {2} sec", "Ефективність зцілення зменшено на {1}%.#reduced by {1}%", en="Veil of Shadow" },
    [7074] = { "Крики минулого", ref=3589, en="Screams of the Past" },
    [7098] = { "Прокляття загоєння", "Проклинає ворога на {1} хв, внаслідок чого його атаки з ймовірністю {2}% зцілюють цілі {3} здоров'я.#for {1} min#it {2}% chance#by {3} on attack", "З ймовірністю {1}% зцілить ворога при атаці.#{1}% chance", en="Curse of Mending" },
    [7102] = { "Зараження гниллю", "Збільшує інтервал між атаками ворога на {1}% та сповільнює вимову заклять на {2}%. З ймовірністю {3}% при отриманні удару ворог поширить хворобу на союзника. Триває {4} хв.#attacks by {1}%#casting by {2}%#adding {3}% chance#Lasts {4} min", "Інтервал між атаками збільшено на {1}%.\nВимову заклять сповільнено на {2}%.\nЗ ймовірністю {3}% при отриманні удару хвороба пошириться на союзника.#increased by {1}%#reduced by {2}%#{3}% chance", en="Contagion of Rot" },
    [7103] = { "Зараження гниллю", nil, "Інтервал між атаками збільшено на {1}%.\nВимову заклять сповільнено на {2}%.\nЗ ймовірністю {3}% при отриманні удару хвороба пошириться на союзника.#increased by {1}%#reduced by {2}%#{3}% chance", en="Contagion of Rot" },
    [7120] = { "Захист Леді Праудмур", nil, "Броню збільшено на {1}.\nВитривалість збільшено на {2}.#Armor increased by {1}#Stamina increased by {2}", en="Proudmoore's Defense" },
    [7124] = { "Дар Аруґала", "Завдає від {1} до {2} шкоди від тіні кожні {3} с протягом {4} хв.#Inflicts {1} to {2} Shadow#every {3} sec#for {4} min", "Отримання від {1} до {2} шкоди від тіні кожні {3} с.#{1} to {2} Shadow#every {3} sec", en="Arugal's Gift" },
    [7125] = { "Токсична слина", "Завдає ворогу {1} шкоди від природи кожні {2} с. Також висмоктує {3} мани кожні {4} с, передаючи її заклиначу. Триває {5} хв.#Inflicts {1} Nature#enemy every {2} sec#drains {3} mana every {4} sec#Lasts {5} min", "{1} шкоди від природи кожні {2} с.\nВисмоктує {3} мани кожні {4} с.#{1} Nature damage inflicted every {2} sec#{3} mana leeched every {4} sec", en="Toxic Saliva" },
    [7127] = { "Хитка воля", "Збільшує інтервал між атаками ворога на {1}%, сповільнює вимову заклять на {2}% та зменшує швидкість руху на {3}%. Триває {4} хв.#attacks speed by {1}%#casting speed by {2}%#movement by {3}%#Lasts {4} min", "Інтервал між атаками збільшено на {1}%.\nВимову заклять сповільнено на {2}%.\nШвидкість руху зменшено на {3}%.#increased by {1}%#Casting speed reduced by {2}%#Movement speed reduced by {3}%", en="Wavering Will" },
    [7128] = { "Внутрішній вогонь", "Сплеск священної енергії наповнює заклинача, збільшуючи броню на {1}. Кожна атака ближнього чи дальнього бою проти жерця знімає один заряд ефекту. Триває {2} хв або поки не буде використано {3} зарядів.#armor by {1}#Lasts {2} min or until {3} charges", "Збільшує броню на {1}.#by {1}", en="Inner Fire" },
    [7139] = { "Тупіт Скверни", "Завдає звичайної шкоди плюс {1} навколишнім ворогам, приголомшуючи їх на {2} с та збільшуючи отриману ними фізичну шкоду на {3}.#plus {1} to#for {2} sec#take by {3}", "Приголомшено.\nОтриману фізичну шкоду збільшено на {1}.#by {1}", en="Fel Stomp" },
    [7140] = { "Виявлення слабких місць", "Збільшує отриману ворогом фізичну шкоду на {1} протягом {2} с.#by {1} for {2} sec", "Отриману фізичну шкоду збільшено на {1}.#by {1}", en="Expose Weakness" },
    [7145] = { "Пікірування", "Завдає звичайної шкоди плюс {1} ворогу та його союзникам неподалік, вражаючи до {2} цілей.#plus {1} to#up to {2} target", en="Diving Sweep" },
    [7178] = { "Водне дихання", "Дозволяє дихати водою протягом {1} хв.#for {1} min", "Водне дихання.", en="Water Breathing" },
    [7218] = { "Противага для зброї", "Прикріпити до вашого дворучного меча, булави, сокири або держакової зброї противагу, що збільшує її швидкість на {1}%.#it {1}% faster", en="Weapon Counterweight" },
