    [7620] = { "Риболовля", "Візьміть до рук вудку і знайдіть водойму, в якій можна рибалити. Коли почуєте плескіт — клацніть на поплавок правою кнопкою миші, щоб витягнути впійману рибу. Чим вище ваша навичка риболовлі, тим більше шансів упіймати рибу у водоймах зон вищого рівня.", en="Fishing" },
    [7641] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [7645] = { "Підкорення розуму", ref=3442, en="Dominate Mind" },
    [7646] = { "Прокляття слабкості", "Ціль завдає на {1} менше шкоди протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", "Фізичну шкоду зменшено на {1}.#by {1}", en="Curse of Weakness" },
    [7648] = { "Пошесть", "Оскверняє ціль, завдаючи {1} шкоди тінню протягом {2} с.#causing {1} Shadow#over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", en="Corruption" },
    [7651] = { "Висмоктування життя", "Передає {1} здоров'я щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1} health#Lasts {2} sec", "Висмоктує {1} здоров'я щосекунди, передаючи його заклиначеві.#Drains {1} health", en="Drain Life" },
    [7658] = { "Прокляття відчайдушності", "Проклинає ціль відчайдушністю, збільшуючи її силу атаки ближнього бою на {1}, але зменшуючи броню на {2} протягом {3} хв. Прокляті вороги не втікатимуть та ігноруватимуть ефекти страху та жаху. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#power by {1}#armor by {2} for {3} min", "Збільшує силу атаки ближнього бою на {1} і зменшує броню на {2}. Ціль не втікатиме та ігноруватиме ефекти страху та жаху.#power by {1}#armor by {2}", en="Curse of Recklessness" },
    [7659] = { "Прокляття відчайдушності", "Проклинає ціль відчайдушністю, збільшуючи її силу атаки ближнього бою на {1}, але зменшуючи броню на {2} протягом {3} хв. Прокляті вороги не втікатимуть та ігноруватимуть ефекти страху та жаху. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#power by {1}#armor by {2} for {3} min", "Збільшує силу атаки ближнього бою на {1} і зменшує броню на {2}. Ціль не втікатиме та ігноруватиме ефекти страху та жаху.#power by {1}#armor by {2}", en="Curse of Recklessness" },
    [7675] = { "Збільшення зцілення {1}#Increase Healing {1}", "Збільшує зцілення від заклинань і ефектів на {1}.#healing done by spells and effects by up to {1}", en="Increase Healing 2" },
    [7683] = { "Збільшення шкоди від вогню {1}#Increase Fire Dam {1}", "Збільшує шкоду від заклинань і ефектів вогню на {1}.#Fire spells and effects by up to {1}", en="Increase Fire Dam 1" },
    [7690] = { "Збільшення шкоди від природи {1}#Increase Nature Dam {1}", "Збільшує шкоду від заклинань і ефектів природи на {1}.#Nature spells and effects by up to {1}", en="Increase Nature Dam 1" },
    [7697] = { "Збільшення шкоди від криги {1}#Increase Frost Dam {1}", "Збільшує шкоду від заклинань і ефектів криги на {1}.#Frost spells and effects by up to {1}", en="Increase Frost Dam 1" },
    [7704] = { "Збільшення шкоди від тіні {1}#Increase Shadow Dam {1}", "Збільшує шкоду від заклинань і ефектів тіні на {1}.#Shadow spells and effects by up to {1}", en="Increase Shadow Dam 1" },
    [7711] = { "Вогняна шкода зброї {1}#Add Fire Dam - Weap {1}", "Додає {1} шкоди від вогню до ваших атак ближнього бою.#Adds {1} fire", en="Add Fire Dam - Weap 02" },
    [7712] = { "Вогняний удар", "Завдає {1} додаткової шкоди від вогню цілі.#Does {1} additional", en="Fire Strike" },
    [7713] = { "Виття мерця", "Зменшує всі характеристики навколишніх ворогів на {1}% протягом {2} с.#by {1}% for {2} sec", "Всі характеристики зменшено на {1}%.#by {1}%", en="Wailing Dead" },
    [7714] = { "Вогняний удар", "Завдає {1} додаткової шкоди від вогню цілі.#Does {1} additional", en="Fire Strike" },
