    [7731] = { "Риболовля", "Візьміть до рук вудку і знайдіть водойму, в якій можна рибалити. Коли почуєте плескіт — клацніть на поплавок правою кнопкою миші, щоб витягнути впійману рибу. Чим вище ваша навичка риболовлі, тим більше шансів упіймати рибу у водоймах зон вищого рівня.", en="Fishing" },
    [7732] = { "Риболовля", "Візьміть до рук вудку і знайдіть водойму, в якій можна рибалити. Коли почуєте плескіт — клацніть на поплавок правою кнопкою миші, щоб витягнути впійману рибу. Чим вище ваша навичка риболовлі, тим більше шансів упіймати рибу у водоймах зон вищого рівня.", en="Fishing" },
    [7737] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [7744] = { "Воля відречених", "Надає невразливість до ефектів причарування, страху та сну на час дії. Можна використовувати під час дії таких ефектів. Триває {1} с.#Lasts {1} sec", "Невразливість до ефектів причарування, страху та сну.", en="Will of the Forsaken" },
    [7764] = { "Мудрість Аґамаґґана", "Збільшує інтелект на {1}.#by {1}", "Збільшує інтелект на {1}.#by {1}", en="Wisdom of Agamaggan" },
    [7799] = { "Вогняна стріла", "Завдає цілі від {1} до {2} шкоди.#Deals {1} to {2} damage", en="Firebolt" },
