    [7804] = { "Кривава угода", "Збільшує витривалість учасників групи на {1}.#Stamina by {1}", "Збільшує витривалість на {1}.#by {1}", en="Blood Pact" },
    [7805] = { "Кривава угода", "Збільшує витривалість учасників групи на {1}.#Stamina by {1}", "Збільшує витривалість на {1}.#by {1}", en="Blood Pact" },
    [7809] = { "Муки", "Провокує істоту, збільшуючи ймовірність того, що вона зосередить свої атаки на пустотнику. Дієвіше за \"Муки\" (Ранг {1}).#(Rank {1})", en="Torment" },
    [7810] = { "Муки", "Провокує істоту, збільшуючи ймовірність того, що вона зосередить свої атаки на пустотнику. Дієвіше за \"Муки\" (Ранг {1}).#(Rank {1})", en="Torment" },
    [7811] = { "Муки", "Провокує істоту, збільшуючи ймовірність того, що вона зосередить свої атаки на пустотнику. Дієвіше за \"Муки\" (Ранг {1}).#(Rank {1})", en="Torment" },
    [7812] = { "Жертва", "Приносить в жертву пустотника, при цьому захищаючи його володаря щитом, який поглинає {1} шкоди протягом {2} с. Поки щит тримається, отримання шкоди не спричиняє затримки вимови заклять.#absorb {1} damage for {2} sec", "Поглинає всю шкоду.", en="Sacrifice" },
    [7813] = { "Заспокійливий поцілунок", "Заспокоює ціль, збільшуючи ймовірність того, що вона атакуватиме когось іншого. Дієвіше за \"Заспокійливий поцілунок\" (Ранг {1}).#(Rank {1})", en="Soothing Kiss" },
    [7814] = { "Батіг болю", "Миттєва атака, що шмагає ціль, завдаючи {1} шкоди тінню.#causing {1}", en="Lash of Pain" },
    [7815] = { "Батіг болю", "Миттєва атака, що шмагає ціль, завдаючи {1} шкоди тінню.#causing {1}", en="Lash of Pain" },
    [7816] = { "Батіг болю", "Миттєва атака, що шмагає ціль, завдаючи {1} шкоди тінню.#causing {1}", en="Lash of Pain" },
    [7823] = { "Навичка риболовлі +{1}#Fishing Skill +{1}", "Збільшує навичку риболовлі на {1}.#Fishing +{1}", en="Fishing Skill +5" },
    [7840] = { "Швидке плавання", "Збільшує швидкість плавання на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість плавання збільшено на {1}%.#by {1}%", en="Swim Speed" },
    [7844] = { "Вогнеміць", "Збільшує шкоду вогняних заклинань на {1} протягом {2} хв.#by up to {1} for {2} min", "Вогняну шкоду заклинань та здібностей збільшено на {1}.#by up to {1}", en="Fire Power" },
    [7870] = { "Мала невидимість", "Надає вашому викликаному демонові малу невидимість на {1} хв. Закляття можна застосувати лише поза боєм.#for up to {1} min", "Невидимість.", en="Lesser Invisibility" },
    [7887] = { "Здолання", "Миттєво долає ворога, завдаючи шкоди зброєю плюс {1}. Можна використати лише після того, як ціль ухилилась. Здолання не можна блокувати, ухилитися від нього або парирувати.#damage plus {1}", en="Overpower" },
    [7918] = { "Постріл з рушниці", en="Shoot Gun" },
    [7919] = { "Постріл з арбалета", en="Shoot Crossbow" },
    [7922] = { "Приголомшення від ривка", nil, "Приголомшено.", en="Charge Stun" },
    [7924] = { "Перша допомога", "Дозволяє створювати і використовувати бинти та розвивати навичку до 225 рівня. Для виготовлення бинтів потрібна тканина, яку можна добути з гуманоїдів.", en="First Aid" },
    [7926] = { "Перша допомога", "Відновлює {1} здоров'я за {2} с.#Heals {1} damage over {2} sec", "Відновлення {1} здоров'я щосекунди.#Healing {1} damage", en="First Aid" },
    [7927] = { "Перша допомога", "Відновлює {1} здоров'я за {2} с.#Heals {1} damage over {2} sec", "Відновлення {1} здоров'я щосекунди.#Healing {1} damage", en="First Aid" },
    [7932] = { "Протиотрута", "Зцілення цілі від отрут до {1} рівня.#up to level {1}", en="Anti-Venom" },
    [7933] = { "Сильна протиотрута", ref=7932, en="Strong Anti-Venom" },
    [7947] = { "Активний токсин", "Завдає ворогу {1} шкоди від природи кожні {2} с протягом {3} хв.#Inflicts {1} Nature#every {2} sec#for {3} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", ref=3583, en="Localized Toxin" },
    [7964] = { "Димова шашка", "Кидає димову шашку, що приголомшує навколишніх ворогів на {1} с.#for {1} sec", "Приголомшено.", en="Smoke Bomb" },
    [7967] = { "Кошмар Наралекса", "Присипляє ворожу ціль на {1} с. Будь-яка ворожа дія розбудить ціль. Одночасно можна змусити спати лише одну ціль.#up to {1} sec", "Спить.", en="Naralex's Nightmare" },
    [7992] = { "Сповільнююча отрута", "Збільшує інтервал між атаками ворога на {1}% та зменшує його швидкість руху на {2}% протягом {3} с.#attacks by {1}%#movement by {2}% for {3} sec", "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Slowing Poison" },
    [8004] = { "Мала хвиля зцілення", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Lesser Healing Wave" },
