    [8012] = { "Очищення", "Очищує ворожу ціль, знімаючи з неї {1} сприятливі магічні ефекти.#removing {1}", en="Purge" },
    [8014] = { "Правець", "Зменшує витривалість ворога на {1} протягом {2} хв.#by {1} for {2} min", "Витривалість зменшено на {1}.#by {1}", en="Tetanus" },
    [8016] = { "Гниття духу", "Зменшує дух ворога на {1} протягом {2} хв.#by {1} for {2} min", "Дух зменшено на {1}.#by {1}", en="Spirit Decay" },
    [8017] = { "Зброя каменолома", "Підсилює зброю шамана, внаслідок чого сила атаки ближнього бою збільшується на {1}, а атаки ближнього бою цією зброєю спричиняють додаткову загрозу. Триває {2} хв.#power by {1} and#for {2} min", en="Rockbiter Weapon" },
    [8018] = { "Зброя каменолома", "Підсилює зброю шамана, внаслідок чого сила атаки ближнього бою збільшується на {1}, а атаки ближнього бою цією зброєю спричиняють додаткову загрозу. Триває {2} хв.#power by {1} and#for {2} min", en="Rockbiter Weapon" },
    [8019] = { "Зброя каменолома", "Підсилює зброю шамана, внаслідок чого сила атаки ближнього бою збільшується на {1}, а атаки ближнього бою цією зброєю спричиняють додаткову загрозу. Триває {2} хв.#power by {1} and#for {2} min", en="Rockbiter Weapon" },
    [8024] = { "Зброя язика полум'я", "Підсилює зброю шамана вогнем. Кожен удар завдає цілі від {1} до {2} додаткової шкоди вогнем залежно від швидкості зброї. Повільна зброя завдає більшої шкоди за удар. Триває {3} хв.#causes {1} to {2}#Lasts for {3} min", en="Flametongue Weapon" },
    [8027] = { "Зброя язика полум'я", "Підсилює зброю шамана вогнем. Кожен удар завдає цілі від {1} до {2} додаткової шкоди вогнем залежно від швидкості зброї. Повільна зброя завдає більшої шкоди за удар. Триває {3} хв.#causes {1} to {2}#Lasts for {3} min", en="Flametongue Weapon" },
    [8030] = { "Зброя язика полум'я", "Підсилює зброю шамана вогнем. Кожен удар завдає цілі від {1} до {2} додаткової шкоди вогнем залежно від швидкості зброї. Повільна зброя завдає більшої шкоди за удар. Триває {3} хв.#causes {1} to {2}#Lasts for {3} min", en="Flametongue Weapon" },
    [8033] = { "Зброя крижаного тавра", "Підсилює зброю шамана кригою. Кожен удар може завдати цілі додатково {1} шкоди кригою та сповільнити її рух на {2}% протягом {3} с. Триває {4} хв.#causing {1}#by {2}% for {3} sec#Lasts for {4} min", en="Frostbrand Weapon" },
    [8038] = { "Зброя крижаного тавра", "Підсилює зброю шамана кригою. Кожен удар може завдати цілі додатково {1} шкоди кригою та сповільнити її рух на {2}% протягом {3} с. Триває {4} хв.#causing {1}#by {2}% for {3} sec#Lasts for {4} min", en="Frostbrand Weapon" },
    [8040] = { "Друїдська дрімота", ref=7967, en="Druid's Slumber" },
    [8042] = { "Земний шок", "Миттєво вражає ціль ударною хвилею, завдаючи від {1} до {2} шкоди від природи. Також перериває вимову закляття та унеможливлює вимову будь-яких інших заклять тієї ж школи магії протягом {3} с. Спричиняє високий рівень загрози.#causing {1} to {2}#for {3} sec", en="Earth Shock" },
    [8044] = { "Земний шок", "Миттєво вражає ціль ударною хвилею, завдаючи від {1} до {2} шкоди від природи. Також перериває вимову закляття та унеможливлює вимову будь-яких інших заклять тієї ж школи магії протягом {3} с. Спричиняє високий рівень загрози.#causing {1} to {2}#for {3} sec", en="Earth Shock" },
    [8045] = { "Земний шок", "Миттєво вражає ціль ударною хвилею, завдаючи від {1} до {2} шкоди від природи. Також перериває вимову закляття та унеможливлює вимову будь-яких інших заклять тієї ж школи магії протягом {3} с. Спричиняє високий рівень загрози.#causing {1} to {2}#for {3} sec", en="Earth Shock" },
    [8046] = { "Земний шок", "Миттєво вражає ціль ударною хвилею, завдаючи від {1} до {2} шкоди від природи. Також перериває вимову закляття та унеможливлює вимову будь-яких інших заклять тієї ж школи магії протягом {3} с. Спричиняє високий рівень загрози.#causing {1} to {2}#for {3} sec", en="Earth Shock" },
    [8050] = { "Вогняний шок", "Миттєво обпалює ціль вогнем, завдаючи {1} шкоди вогнем одразу та ще {2} шкоди вогнем протягом {3} с.#causing {1}#{2} Fire damage over {3} sec", "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", en="Flame Shock" },
    [8052] = { "Вогняний шок", "Миттєво обпалює ціль вогнем, завдаючи {1} шкоди вогнем одразу та ще {2} шкоди вогнем протягом {3} с.#causing {1}#{2} Fire damage over {3} sec", "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", en="Flame Shock" },
    [8053] = { "Вогняний шок", "Миттєво обпалює ціль вогнем, завдаючи {1} шкоди вогнем одразу та ще {2} шкоди вогнем протягом {3} с.#causing {1}#{2} Fire damage over {3} sec", "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", en="Flame Shock" },
    [8056] = { "Крижаний шок", "Миттєво вражає ціль кригою, завдаючи від {1} до {2} шкоди кригою та сповільнюючи рух на {3}%. Триває {4} с.#causing {1} to {2}#speed by {3}%#Lasts {4} sec", "Рух сповільнено на {1}%.#by {1}%", en="Frost Shock" },
    [8058] = { "Крижаний шок", "Миттєво вражає ціль кригою, завдаючи від {1} до {2} шкоди кригою та сповільнюючи рух на {3}%. Триває {4} с.#causing {1} to {2}#speed by {3}%#Lasts {4} sec", "Рух сповільнено на {1}%.#by {1}%", en="Frost Shock" },
