    [8992] = { "Шматування", "Шматує ціль, завдаючи {1}% шкоди плюс {2}. Необхідно бути позаду цілі. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", en="Shred" },
    [8994] = { "Вигнання", "Виганяє ворога до іншого виміру, перешкоджаючи всім його діям, але при цьому робить його невразливим протягом {1} с. Одночасно лише одна ціль може бути вигнаною.#for up to {1} sec", "Невразливість до всіх атак та заклять, але неможливо виконувати будь-які дії.", en="Banish" },
    [8998] = { "Зіщулювання", "Зіщулитися, не завдаючи шкоди, та трохи зменшити вашу загрозу. Це знизить ймовірність того, що ворог атакуватиме саме вас.", en="Cower" },
    [9000] = { "Зіщулювання", "Зіщулитися, не завдаючи шкоди, та зменшити вашу загрозу. Це знизить ймовірність того, що ворог атакуватиме саме вас.", en="Cower" },
    [9005] = { "Наскок", "Cтрибнути на ціль, приголомшуючи її на {1} с та завдаючи {2} шкоди протягом {3} с. Потрібно зачаїтися та перебувати позаду цілі. Збільшує довжину комбінації на {4} прийом.#for {1} sec#causing {2} damage over {3} sec#{4} combo", "Приголомшено.", en="Pounce" },
    [9007] = { "Кровотеча від наскоку", nil, "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Pounce Bleed" },
    [9034] = { "Жертовний вогонь", "Обпалює ворога, завдаючи шкоди вогнем кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Immolate" },
    [9035] = { "Пристріт слабкості", "Послаблює вибраного ворога, зменшуючи його шкоду на {1} та зменшуючи ефективність будь-якого лікування на {2}%. Триває {3} хв.#caused by {1}#healing by {2}#Lasts {3} min", "Фізичну шкоду зменшено на {1}, а ефективність зцілення зменшено на {2}%.#damage done reduced by {1} and healing effectiveness reduced by {2}", en="Hex of Weakness" },
