    [9176] = { "Священний розкол", "Зменшує броню цілі на {1} протягом {2} хв.#armor of target by {1} for {2} min", "Броню зменшено.", en="Holy Sunder" },
    [9233] = { "Вогняна стріла", "З ймовірністю {1}% ви завдасте [{1}#of dealing {1} Fire damage][від {1} до {2}#of dealing {1} to {2} Fire damage] шкоди вогнем при успішній атаці в ближньому бою.#{1}% chance of dealing", en="Firebolt" },
