    [9490] = { "Деморалізуючий рев", "Друїд реве, зменшуючи силу атаки ближнього бою навколишніх ворогів на {1}. Триває {2} с.#power by {1}#Lasts {2} sec", "Силу атаки ближнього бою зменшено на {1}.#power by {1}", en="Demoralizing Roar" },
    [9492] = { "Розірвання", "Завершальний рух, що завдає шкоди з часом. Шкода збільшується залежно від довжини комбінації та сили атаки:\n  1 прийом: {1} шкоди за {2} cекунд\n  2 прийоми: {3} шкоди за {4} cекунд\n  3 прийоми: {5} шкоди за {6} cекунд\n  4 прийоми: {7} шкоди за {8} cекунд\n  5 прийомів: {9} шкоди за {10} cекунд#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", "Шкода від кровотечі кожні {1} с.#every {1} sec", en="Rip" },
    [9493] = { "Розірвання", "Завершальний рух, що завдає шкоди з часом. Шкода збільшується залежно від довжини комбінації та сили атаки:\n  1 прийом: {1} шкоди за {2} cекунд\n  2 прийоми: {3} шкоди за {4} cекунд\n  3 прийоми: {5} шкоди за {6} cекунд\n  4 прийоми: {7} шкоди за {8} cекунд\n  5 прийомів: {9} шкоди за {10} cекунд#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", "Шкода від кровотечі кожні {1} с.#every {1} sec", en="Rip" },
    [9512] = { "Відновлення енергії", "Миттєво відновлює {1} енергії.#restores {1} energy", en="Restore Energy" },
    [9573] = { "Полум'яне дихання", "Завдає {1} шкоди вогнем ворогам у конусі перед заклиначем.#Inflicts {1} Fire", en="Flame Breath" },
    [9574] = { "Вогняний ляпас", "Завдає цілі від {1} до {2} шкоди вогнем і збільшує отриману нею шкоду від вогню на {3} протягом {4} секунд.#Inflicts {1} to {2} Fire#by {3} for {4} sec", "Отриману шкоду від вогню збільшено на {1}.#by {1}", en="Flame Buffet" },
    [9578] = { "Розтанення", "Розтанути у повітрі, зменшуючи всю вашу загрозу протягом {1} с. Дієвіше за \"Розтанення\" (Ранг {2}).#for {1} sec#rank {2}", "Рівень загрози зменшено.", en="Fade" },
    [9579] = { "Розтанення", "Розтанути у повітрі, зменшуючи всю вашу загрозу протягом {1} с. Дієвіше за \"Розтанення\" (Ранг {2}).#for {1} sec#rank {2}", "Рівень загрози зменшено.", en="Fade" },
    [9592] = { "Розтанення", "Розтанути у повітрі, зменшуючи всю вашу загрозу протягом {1} с. Дієвіше за \"Розтанення\" (Ранг {2}).#for {1} sec#rank {2}", "Рівень загрози зменшено.", en="Fade" },
    [9612] = { "Чорнильні бризки", ref=5514, en="Ink Spray" },
    [9614] = { "Маяк розлому", "Позначає ворога пристроєм стеження. Через 1 хвилину 2 загублених мандрівника розломами знайдуть і атакують ворога. Загублені мандрівники розломами нестабільні, а тому не можуть підтримувати фізичне втілення довше, ніж 1 хвилину.", "Мандрівники розломами знають ваше місцезнаходження. Вони знайдуть вас через 1 хвилину.", en="Rift Beacon" },
    [9632] = { "Буря клинків", "Ви починаєте атакувати всіх ворогів поблизу протягом {1} секунд, завдаючи їм збільшеної на {2} шкоди від зброї кожні {3} секунди.#nearby enemies for {1} sec# additional {2} every {3} sec", "Атакує всіх ворогів поблизу, завдаючи збільшеної на {1} шкоди від зброї.#weapon damage + {1}", en="Bladestorm" },
    [9634] = { "Подоба жахливого ведмедя", "Набути подоби жахливого ведмедя, збільшуючи силу атаки ближнього бою на {1}, броню від предметів на {2}% та здоров'я на {3}. Також захищає заклинача від ефектів поліморфії та дозволяє використання ведмежих здібностей.\n\nЗміна подоби звільняє заклинача від ефектів поліморфії та ефектів обмеження руху.#power by {1}#items by {2}%#health by {3}", "Невразливість до ефектів поліморфії. Збільшує силу атаки ближнього бою на {1}, броню від предметів на {2}% та здоров'я на {3}.#power by {1}#items by {2}%#health by {3}", en="Dire Bear Form" },
    [9658] = { "Вогняний ляпас", "Завдає цілі від {1} до {2} шкоди вогнем і збільшує отриману нею шкоду від вогню на {3} протягом {4} секунд.#Inflicts {1} to {2} Fire#by {3} for {4} sec", "Отриману шкоду від вогню збільшено на {1}.#by {1}", en="Flame Buffet" },
    [9672] = { "Крижана стріла", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frostbolt" },
    [9745] = { "Терзання", "Збільшує шкоду від наступної атаки на {1}.#by {1} damage", en="Maul" },
    [9747] = { "Деморалізуючий рев", "Друїд реве, зменшуючи силу атаки ближнього бою навколишніх ворогів на {1}. Триває {2} с.#power by {1}#Lasts {2} sec", "Силу атаки ближнього бою зменшено на {1}.#power by {1}", en="Demoralizing Roar" },
    [9749] = { "Чарівний вогонь", "Зменшує броню цілі на {1} протягом {2} с. Під час дії ефекту ціль не може отримати ефект непомітності чи невидимості.#by {1} for {2} sec", "Броню зменшено на {1}. Не може отримати ефект непомітності чи невидимості.#armor by {1}", en="Faerie Fire" },
    [9750] = { "Розростання", "Зцілює дружній цілі від {1} до {2} здоров'я і додатково {3} здоров'я протягом {4} c.#for {1} to {2}#{3} over {4} sec", "Зцілення {1} здоров'я кожні {2} с.#{1} every {2} sec", en="Regrowth" },
    [9752] = { "Розірвання", "Завершальний рух, що завдає шкоди з часом. Шкода збільшується залежно від довжини комбінації та сили атаки:\n  1 прийом: {1} шкоди за {2} cекунд\n  2 прийоми: {3} шкоди за {4} cекунд\n  3 прийоми: {5} шкоди за {6} cекунд\n  4 прийоми: {7} шкоди за {8} cекунд\n  5 прийомів: {9} шкоди за {10} cекунд#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", "Шкода від кровотечі кожні {1} с.#every {1} sec", en="Rip" },
    [9754] = { "Розмах", "Вдарити {1} ворогів поблизу, завдаючи {2} шкоди.#Swipe {1} nearby#inflicting {2} damage", en="Swipe" },
    [9756] = { "Шипи", "Шипи проростають із дружньої цілі, завдаючи {1} шкоди від природи нападникам при отриманні удару. Триває {2} хв.#causing {1}#Lasts {2} min", "Завдає {1} шкоди від природи нападникам.#Causes {1}", en="Thorns" },
