    [9774] = { "Невразливість до знерухомлення", "Усуває наявні ефекти знерухомлення та надає невразливість до ефектів знерухомлення протягом {1} с.#Immobilizing effects for {1} sec", "Невразливість до ефектів знерухомлення протягом {1} с.#effects for {1} sec", en="Immune Root" },
    [9775] = { "Опромінення", nil, "Випромінює радіацію.\nЗавдає шкоди від природи кожні {1} с.\nПеріодично завдає шкоди природі учасникам групи неподалік.#every {1} sec", en="Irradiated" },
    [9778] = { "Шанс самозцілення {1}#Proc Self Heal {1}", "З ймовірністю {1}% при отриманні удару в бою ви відновите [{1}#heal you for {1}.][від {1} до {2}#heal you for {1} to {2}.] здоров'я.#has a {1}% chance to", en="Proc Self Heal 22" },
