    [9796] = { "Чума", "Заражає ціль, завдаючи {1} шкоди від природи та додатково {2} шкоди протягом {3} хв.#for {1} Nature#additional {2} damage over {3} min", "Заражено. {1} шкоди від природи кожні {2} с.#{1} nature damage every {2} sec", en="Blight" },
    [9799] = { "Око за око", "Усі критичні удари закляттями по вам завдають {1}% від отриманої вами шкоди заклиначу. Шкода від цього ефекту не може перевищувати {2}% від запасу здоров'я паладина.#cause {1}% of#exceed {2}% of", en="Eye for an Eye" },
