    [9892] = { "Зіщулювання", "Зіщулитися, не завдаючи шкоди, та значно зменшити вашу загрозу. Це знизить ймовірність того, що ворог атакуватиме саме вас.", en="Cower" },
    [9894] = { "Розірвання", "Завершальний рух, що завдає шкоди з часом. Шкода збільшується залежно від довжини комбінації та сили атаки:\n  1 прийом: {1} шкоди за {2} cекунд\n  2 прийоми: {3} шкоди за {4} cекунд\n  3 прийоми: {5} шкоди за {6} cекунд\n  4 прийоми: {7} шкоди за {8} cекунд\n  5 прийомів: {9} шкоди за {10} cекунд#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", "Шкода від кровотечі кожні {1} с.#every {1} sec", en="Rip" },
    [9896] = { "Розірвання", "Завершальний рух, що завдає шкоди з часом. Шкода збільшується залежно від довжини комбінації та сили атаки:\n  1 прийом: {1} шкоди за {2} cекунд\n  2 прийоми: {3} шкоди за {4} cекунд\n  3 прийоми: {5} шкоди за {6} cекунд\n  4 прийоми: {7} шкоди за {8} cекунд\n  5 прийомів: {9} шкоди за {10} cекунд#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", "Шкода від кровотечі кожні {1} с.#every {1} sec", en="Rip" },
    [9898] = { "Деморалізуючий рев", "Друїд реве, зменшуючи силу атаки ближнього бою навколишніх ворогів на {1}. Триває {2} с.#power by {1}#Lasts {2} sec", "Силу атаки ближнього бою зменшено на {1}.#power by {1}", en="Demoralizing Roar" },
    [9900] = { "Заточка леза IV", ref=2828, en="Sharpen Blade IV" },
    [9901] = { "Вгамування звіра", "Вгамовує обраного звіра, зменшуючи відстань, на якій він буде атакувати вас, на {1} м. Діє лише на звірів {2} рівня або нижче. Триває {3} с.#by {1} y#level {2} or lower#Lasts {3} sec", "Зменшено відстань, на якій ціль буде атакувати.", en="Soothe Animal" },
    [9903] = { "Покращення дробильної зброї IV", ref=3112, en="Enhance Blunt Weapon IV" },
    [9904] = { "Роздирання", "Роздирає ціль, завдаючи {1} шкоди та додатково {2} шкоди протягом {3} с. Збільшує довжину комбінації на {4} прийом.#for {1} damage and an additional {2} damage over {3} sec#{4} combo", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rake" },
    [9907] = { "Чарівний вогонь", "Зменшує броню цілі на {1} протягом {2} с. Під час дії ефекту ціль не може отримати ефект непомітності чи невидимості.#by {1} for {2} sec", "Броню зменшено на {1}. Не може отримати ефект непомітності чи невидимості.#armor by {1}", en="Faerie Fire" },
