    [10211] = { "Арканічні снаряди", "Запускає у ворога арканічні снаряди, що завдають {1} шкоди арканою щосекунди протягом {2} с.#causing {1}#for {2} sec", en="Arcane Missiles" },
    [10212] = { "Арканічні снаряди", "Запускає у ворога арканічні снаряди, що завдають {1} шкоди арканою щосекунди протягом {2} с.#causing {1}#for {2} sec", en="Arcane Missiles" },
    [10215] = { "Полум'яний удар", "Викликає вогняний стовп, що палить усіх ворогів у зоні ураження, завдаючи [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем і додатково {1} шкоди вогнем протягом {2} с.#additional {1}#over {2} sec", "{1} шкоди вогнем кожні {2} секунди.#{1} Fire damage every {2} sec", en="Flamestrike" },
    [10216] = { "Полум'яний удар", "Викликає вогняний стовп, що палить усіх ворогів у зоні ураження, завдаючи [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем і додатково {1} шкоди вогнем протягом {2} с.#additional {1}#over {2} sec", "{1} шкоди вогнем кожні {2} секунди.#{1} Fire damage every {2} sec", en="Flamestrike" },
    [10219] = { "Льодяний обладунок", "Збільшує броню на {1} та опір кризі на {2}. Якщо ворог завдає удару по заклиначу, його швидкість руху може сповільнитися на {3}%, а інтервал між атаками збільшитися на {4}% протягом {5} с. Одночасно може бути активним лише один обладунок. Триває {6} хв.#Armor by {1}#resistance by {2}#slowed by {3}%#increased by {4}% for {5} sec#Lasts {6} min", "Збільшує броню на {1}, опір кризі на {2} і може сповільнити нападників.#Armor by {1}#resistance by {2}", en="Ice Armor" },
    [10220] = { "Льодяний обладунок", "Збільшує броню на {1} та опір кризі на {2}. Якщо ворог завдає удару по заклиначу, його швидкість руху може сповільнитися на {3}%, а інтервал між атаками збільшитися на {4}% протягом {5} с. Одночасно може бути активним лише один обладунок. Триває {6} хв.#Armor by {1}#resistance by {2}#slowed by {3}%#increased by {4}% for {5} sec#Lasts {6} min", "Збільшує броню на {1}, опір кризі на {2} і може сповільнити нападників.#Armor by {1}#resistance by {2}", en="Ice Armor" },
    [10223] = { "Вогняний оберіг", "Поглинає {1} шкоди від вогню. Триває {2} с.#Absorbs {1}#Lasts {2} sec", "Поглинає шкоду від вогню.", en="Fire Ward" },
    [10225] = { "Вогняний оберіг", "Поглинає {1} шкоди від вогню. Триває {2} с.#Absorbs {1}#Lasts {2} sec", "Поглинає шкоду від вогню.", en="Fire Ward" },
    [10230] = { "Крижаний спалах", "Вражає ворогів поруч із заклиначем, завдаючи [{1}#for {1} Frost][від {1} до {2}#for {1} to {2} Frost] шкоди кригою, та приморожує їх на місці на {1} с. Подальше завдання шкоди може перервати дію цього ефекту.#up to {1} sec", "Приморожено.", en="Frost Nova" },
    [10248] = { "Гірництво", "Гірництво, як одна з форм мистецтва. Дозволяє розвивати навичку гірництва до 300 рівня.", en="Mining" },
    [10250] = { "Напій", "Відновлює {1} мани протягом {2} с. Потрібно залишатися в сидячому положенні під час пиття.#Restores {1} mana over {2} sec", "Відновлює {1} мани щосекунди.#Restores {1} mana", en="Drink" },
    [10256] = { "Їжа", "Відновлює {1} здоров'я протягом {2} секунд. Потрібно залишатися в сидячому положенні під час їжі. Через {3} секунд ви насититесь і ваші витривалість та дух збільшаться на {4} протягом {5} хв.#Restores {1} health over {2} sec#at least {3} sec#gain {4} Stamina and Spirit for {5} min", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [10257] = { "Їжа", "Відновлює {1} здоров'я протягом {2} секунд. Потрібно залишатися в сидячому положенні під час їжі. Через {3} секунд ви насититесь і ваші витривалість та дух збільшаться на {4} протягом {5} хв.#Restores {1} health over {2} sec#at least {3} sec#gain {4} Stamina and Spirit for {5} min", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [10278] = { "Благословення захисту", "Захищає обраного учасника групи від усіх фізичних атак на {1} с, але протягом цього часу ціль не може атакувати чи використовувати фізичні здібності. Гравці можуть мати лише одне благословення від кожного паладина одночасно. Захищена ціль не зможе отримати невразливість від заклять \"Божественний щит\", \"Божественний захист\" та \"Благословення захисту\" повторно протягом {2} хв.#attacks for {1} sec#again for {2} min", "Невразливість до фізичних атак. Не може атакувати чи використовувати фізичні здібності.", en="Blessing of Protection" },
    [10290] = { "Аура відданості", "Надає {1} додаткової броні учасникам групи в радіусі {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#{1} additional armor#within {2} y", "Збільшує броню на {1}.#by {1}", en="Devotion Aura" },
    [10291] = { "Аура відданості", "Надає {1} додаткової броні учасникам групи в радіусі {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#{1} additional armor#within {2} y", "Збільшує броню на {1}.#by {1}", en="Devotion Aura" },
    [10292] = { "Аура відданості", "Надає {1} додаткової броні учасникам групи в радіусі {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#{1} additional armor#within {2} y", "Збільшує броню на {1}.#by {1}", en="Devotion Aura" },
    [10293] = { "Аура відданості", "Надає {1} додаткової броні учасникам групи в радіусі {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#{1} additional armor#within {2} y", "Збільшує броню на {1}.#by {1}", en="Devotion Aura" },
    [10298] = { "Аура розплати", "Завдає {1} шкоди святістю ворогам, що завдають удару учасникам групи в межах {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#Causes {1} Holy#within {2} y", "Завдає {1} шкоди святістю будь-кому, хто вас ударяє.#Does {1} Holy damage", en="Retribution Aura" },
    [10299] = { "Аура розплати", "Завдає {1} шкоди святістю ворогам, що завдають удару учасникам групи в межах {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#Causes {1} Holy#within {2} y", "Завдає {1} шкоди святістю будь-кому, хто вас ударяє.#Does {1} Holy damage", en="Retribution Aura" },
    [10300] = { "Аура розплати", "Завдає {1} шкоди святістю ворогам, що завдають удару учасникам групи в межах {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#Causes {1} Holy#within {2} y", "Завдає {1} шкоди святістю будь-кому, хто вас ударяє.#Does {1} Holy damage", en="Retribution Aura" },
    [10301] = { "Аура розплати", "Завдає {1} шкоди святістю ворогам, що завдають удару учасникам групи в межах {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#Causes {1} Holy#within {2} y", "Завдає {1} шкоди святістю будь-кому, хто вас ударяє.#Does {1} Holy damage", en="Retribution Aura" },
    [10308] = { "Молот правосуддя", "Приголомшує ціль на {1} с.#for {1} sec", "Приголомшено.", en="Hammer of Justice" },
    [10310] = { "Покладання рук", "Зцілює дружню ціль на значення, що дорівнює максимальному запасу здоров'я паладина, та відновлює їй {1} мани. Витрачає весь залишок мани паладина при використанні.#restores {1} of their", en="Lay on Hands" },
    [10312] = { "Екзорцизм", "Завдає від {1} до {2} шкоди святістю невмерлому чи демону.#Causes {1} to {2} Holy", en="Exorcism" },
    [10313] = { "Екзорцизм", "Завдає від {1} до {2} шкоди святістю невмерлому чи демону.#Causes {1} to {2} Holy", en="Exorcism" },
    [10314] = { "Екзорцизм", "Завдає від {1} до {2} шкоди святістю невмерлому чи демону.#Causes {1} to {2} Holy", en="Exorcism" },
    [10318] = { "Священний гнів", "Посилає стріли священної сили в усіх напрямках, завдаючи від {1} до {2} шкоди святістю усім невмерлим та демонам в межах {3} м.#causing {1} to {2}#within {3} y", en="Holy Wrath" },
    [10322] = { "Спокута", "Повертає мертвого гравця до життя з {1} здоров'я та {2} мани. Не можна використовувати в бою.#{1} health and {2} mana", en="Redemption" },
    [10324] = { "Спокута", "Повертає мертвого гравця до життя з {1} здоров'я та {2} мани. Не можна використовувати в бою.#{1} health and {2} mana", en="Redemption" },
    [10326] = { "Вигнати невмерлого", "Обраний невмерлий ворог буде змушений втікати протягом {1} с. Подальше завдання шкоди може перервати ефект. Одночасно лише одна ціль може бути вигнаною.#for up to {1} sec", "Змушений утікати.", en="Turn Undead" },
    [10328] = { "Священне світло", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Holy Light" },
    [10329] = { "Священне світло", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Holy Light" },
    [10336] = { "Удар лицаря", "Удар, що завдає {1} шкоди та збільшує отриману ціллю шкоду від святості на {2} за кожен \"Удар лицаря\". Ефект може накопичуватись до {3} разів. Триває {4} с.#causes {1} damage#by up to {2} per#applied up to {3} times#Lasts {4} sec", "Збільшує отриману шкоду святістю на {1}.#up to {1}", en="Crusader Strike" },
    [10337] = { "Удар лицаря", "Удар, що завдає {1} шкоди та збільшує отриману ціллю шкоду від святості на {2} за кожен \"Удар лицаря\". Ефект може накопичуватись до {3} разів. Триває {4} с.#causes {1} damage#by up to {2} per#applied up to {3} times#Lasts {4} sec", "Збільшує отриману шкоду святістю на {1}.#up to {1}", en="Crusader Strike" },
    [10351] = { "Шкіра василіска", "Збільшує навичку захисту на {1} протягом {2} с.#Defense +{1} for {2} sec", "Навичку захисту збільшено.", en="Basilisk Skin" },
    [10370] = { "Рвані рани", "Збільшує отриману ціллю фізичну шкоду на {1} протягом {2} хв. Ефект накопичується до {3} разів.#attacks by {1} for {2} min#up to {3} times", "Отриману шкоду в ближньому бою збільшено на {1}.#taken by {1}", en="Lacerations" },
    [10373] = { "Смертельна рана", "Завдає смертельної рани на [{1}#for {1} damage][{1}-{2}#for {1} to {2} damage] шкоди.", en="Fatal Wound" },
    [10391] = { "Блискавка", "Кидає в ціль блискавку, завдаючи від {1} до {2} шкоди від природи.#for {1} to {2}", en="Lightning Bolt" },
    [10392] = { "Блискавка", "Кидає в ціль блискавку, завдаючи від {1} до {2} шкоди від природи.#for {1} to {2}", en="Lightning Bolt" },
    [10395] = { "Хвиля зцілення", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Wave" },
    [10396] = { "Хвиля зцілення", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Wave" },
    [10399] = { "Зброя каменолома", "Підсилює зброю шамана, внаслідок чого сила атаки ближнього бою збільшується на {1}, а атаки ближнього бою цією зброєю спричиняють додаткову загрозу. Триває {2} хв.#power by {1} and#for {2} min", en="Rockbiter Weapon" },
    [10403] = { "Кам'яна шкіра", nil, "Зменшує отриману шкоду в ближньому бою на {1}.#by {1}", en="Stoneskin" },
    [10404] = { "Кам'яна шкіра", nil, "Зменшує отриману шкоду в ближньому бою на {1}.#by {1}", en="Stoneskin" },
    [10405] = { "Кам'яна шкіра", nil, "Зменшує отриману шкоду в ближньому бою на {1}.#by {1}", en="Stoneskin" },
    [10406] = { "Тотем кам'яної шкіри", "Викликає тотем кам'яної шкіри з {1} здоров'я. Тотем захищає учасників групи в межах {2} м, зменшуючи отриману шкоду в ближньому бою на {3}. Триває {4} хв.#with {1} health#within {2} y#taken by {3}#Lasts {4} min", en="Stoneskin Totem" },
    [10407] = { "Тотем кам'яної шкіри", "Викликає тотем кам'яної шкіри з {1} здоров'я. Тотем захищає учасників групи в межах {2} м, зменшуючи отриману шкоду в ближньому бою на {3}. Триває {4} хв.#with {1} health#within {2} y#taken by {3}#Lasts {4} min", en="Stoneskin Totem" },
    [10408] = { "Тотем кам'яної шкіри", "Викликає тотем кам'яної шкіри з {1} здоров'я. Тотем захищає учасників групи в межах {2} м, зменшуючи отриману шкоду в ближньому бою на {3}. Триває {4} хв.#with {1} health#within {2} y#taken by {3}#Lasts {4} min", en="Stoneskin Totem" },
    [10412] = { "Земний шок", "Миттєво вражає ціль ударною хвилею, завдаючи від {1} до {2} шкоди від природи. Також перериває вимову закляття та унеможливлює вимову будь-яких інших заклять тієї ж школи магії протягом {3} с. Спричиняє високий рівень загрози.#causing {1} to {2}#for {3} sec", en="Earth Shock" },
    [10413] = { "Земний шок", "Миттєво вражає ціль ударною хвилею, завдаючи від {1} до {2} шкоди від природи. Також перериває вимову закляття та унеможливлює вимову будь-яких інших заклять тієї ж школи магії протягом {3} с. Спричиняє високий рівень загрози.#causing {1} to {2}#for {3} sec", en="Earth Shock" },
    [10414] = { "Земний шок", "Миттєво вражає ціль ударною хвилею, завдаючи від {1} до {2} шкоди від природи. Також перериває вимову закляття та унеможливлює вимову будь-яких інших заклять тієї ж школи магії протягом {3} с. Спричиняє високий рівень загрози.#causing {1} to {2}#for {3} sec", en="Earth Shock" },
    [10427] = { "Тотем кам'яного пазура", "Викликає тотем кам'яного пазура з {1} здоров'я на {2} с. Тотем провокує істот в межах {3} м атакувати його.#with {1} health#for {2} sec#within {3} y", en="Stoneclaw Totem" },
    [10428] = { "Тотем кам'яного пазура", "Викликає тотем кам'яного пазура з {1} здоров'я на {2} с. Тотем провокує істот в межах {3} м атакувати його.#with {1} health#for {2} sec#within {3} y", en="Stoneclaw Totem" },
    [10431] = { "Блискавковий щит", "Оточує заклинача {1} кульовими блискавками. Коли будь-яке закляття, атака ближнього чи дальнього бою влучає у заклинача, нападнику завдається {2} шкоди від природи. При цьому витрачається одна кульова блискавка. Кульові блискавки можуть активуватися лише раз на кілька секунд. Триває {3} хв.#by {1} balls#struck for {2} Nature#Lasts {3} min", "Завдає {1} шкоди від природи нападникам при отриманні удару.#Causes {1} Nature", en="Lightning Shield" },
    [10432] = { "Блискавковий щит", "Оточує заклинача {1} кульовими блискавками. Коли будь-яке закляття, атака ближнього чи дальнього бою влучає у заклинача, нападнику завдається {2} шкоди від природи. При цьому витрачається одна кульова блискавка. Кульові блискавки можуть активуватися лише раз на кілька секунд. Триває {3} хв.#by {1} balls#struck for {2} Nature#Lasts {3} min", "Завдає {1} шкоди від природи нападникам при отриманні удару.#Causes {1} Nature", en="Lightning Shield" },
    [10437] = { "Тотем обпалення", "Викликає тотем обпалення з {1} здоров'я на {2} с. Тотем періодично атакує ворогів у радіусі {3} м, завдаючи від {4} до {5} шкоди вогнем.#with {1} health#for {2} sec#within {3} yards for {4} to {5} Fire", en="Searing Totem" },
    [10438] = { "Тотем обпалення", "Викликає тотем обпалення з {1} здоров'я на {2} с. Тотем періодично атакує ворогів у радіусі {3} м, завдаючи від {4} до {5} шкоди вогнем.#with {1} health#for {2} sec#within {3} yards for {4} to {5} Fire", en="Searing Totem" },
