    [10874] = { "Спалення мани", "Спалює цілі від {1} до {2} мани. Кожна одиниця спаленої таким чином мани завдає цілі {3} шкоди тінню.#{1} to {2} mana#takes {3} Shadow", en="Mana Burn" },
