    [10890] = { "Психічний крик", "Заклинач вивільнює психічний крик, що змушує {1} ворогів у межах {2} м тікати геть протягом {3} с. Завдана шкода може перервати цей ефект.#causing {1} enemies within {2} y#for {3} sec", "Тікає зі страху.", en="Psychic Scream" },
