    [10951] = { "Внутрішній вогонь", "Сплеск священної енергії наповнює заклинача, збільшуючи броню на {1}. Кожна атака ближнього чи дальнього бою проти жерця знімає один заряд ефекту. Триває {2} хв або поки не буде використано {3} зарядів.#armor by {1}#Lasts {2} min or until {3} charges", "Збільшує броню на {1}.#by {1}", en="Inner Fire" },
    [10952] = { "Внутрішній вогонь", "Сплеск священної енергії наповнює заклинача, збільшуючи броню на {1}. Кожна атака ближнього чи дальнього бою проти жерця знімає один заряд ефекту. Триває {2} хв або поки не буде використано {3} зарядів.#armor by {1}#Lasts {2} min or until {3} charges", "Збільшує броню на {1}.#by {1}", en="Inner Fire" },
    [10953] = { "Заспокоєння розуму", "Заспокоює ціль, зменшуючи відстань, на якій вона атакуватиме вас, на {1} м. Діє лише на гуманоїдів рівня {2} або нижче. Триває {3} с.#by {1} y#level {2} or lower#Lasts {3} sec", "Зменшено відстань, з якої ціль атакуватиме.", en="Mind Soothe" },
