    [11426] = { "Льодяний бар'єр", "Миттєво захищає вас щитом, що поглинає {1} шкоди. Триває {2} хв. Поки щит тримається, вашу вимову заклять не можна перервати.#absorbing {1}#Lasts {2} min", "Поглинає шкоду.", en="Ice Barrier" },
    [11427] = { "Розсічення", "Завдає звичайної шкоди плюс {1} ворогу та його союзникам неподалік, вражаючи до {2} цілей.#plus {1} to#up to {2} target", en="Cleave" },
    [11428] = { "Збиття з ніг", "Завдає ворогу від {1} до {2} шкоди, приголомшуючи його на {3} с.#Inflicts {1} to {2} damage#for {3} sec", "Приголомшено.", en="Knockdown" },
    [11436] = { "Сповільнення", "Збільшує інтервал між атаками ворога на {1}% та зменшує його швидкість руху на {2}% протягом {3} с.#attacks by {1}%#movement by {2}% for {3} sec", "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Slow" },
    [11443] = { "Каліцтво", "Збільшує інтервал між атаками ворога на {1}%, зменшує його швидкість руху на {2}% та силу на {3}%. Триває {4} с.#attacks by {1}%#movement by {2}%#Strength by {3}%#Lasts {4} sec", "Швидкість руху зменшено на {1}%.\nІнтервал між атаками збільшено на {2}%.\nСилу зменшено на {3}%.#speed reduced by {1}%#increased by {2}%#Strength reduced by {3}%", en="Cripple" },
    [11445] = { "Кістяна броня", "Оточує заклинача кістяною броню, що поглинає від {1} до {2} шкоди протягом {3} хв. Під захистом кістяної броні отримана фізична шкода не спричиняє затримки вимови заклять.#absorbing {1} to {2} damage for {3} min", "Шкода поглинається кістяною бронею.", en="Bone Armor" },
    [11474] = { "Сила тіні", "Збільшує шкоду заклинань тіні на {1} протягом {2} хв.#to {1} for {2} min", "Шкоду від заклять та здібностей тіні збільшено на {1}.#by up to {1}", en="Shadow Power" },
    [11479] = { "Трансмутація: Залізо у золото", "Перетворює злиток заліза на злиток золота.", en="Transmute: Iron to Gold" },
