    [11675] = { "Висмоктування душі", "Висмоктує душу з цілі, завдаючи {1} шкоди тінню протягом {2} с. Якщо ціль під час цього помирає та приносить досвід або честь, заклинач отримує уламок душі. Уламки душі потрібні для інших заклять.#causing {1}#over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2}", en="Drain Soul" },
    [11677] = { "Вогняний дощ", "Викликає вогняний дощ, що обпалює ворогів у зоні ураження, завдаючи {1} шкоди вогнем протягом {2} с.#{1} Fire damage over {2} sec", "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", en="Rain of Fire" },
    [11678] = { "Вогняний дощ", "Викликає вогняний дощ, що обпалює ворогів у зоні ураження, завдаючи {1} шкоди вогнем протягом {2} с.#{1} Fire damage over {2} sec", "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", en="Rain of Fire" },
    [11683] = { "Пекельний вогонь", "Підпалює землю навколо заклинача, щосекунди завдаючи {1} шкоди вогнем йому та {2} шкоди вогнем усім ворогам поблизу. Триває {3} с.#causing {1}#and {2}#Lasts {3} sec", "Завдає шкоди собі та всім навколишнім ворогам.", en="Hellfire" },
    [11684] = { "Пекельний вогонь", "Підпалює землю навколо заклинача, щосекунди завдаючи {1} шкоди вогнем йому та {2} шкоди вогнем усім ворогам поблизу. Триває {3} с.#causing {1}#and {2}#Lasts {3} sec", "Завдає шкоди собі та всім навколишнім ворогам.", en="Hellfire" },
