    [11784] = { "Заспокійливий поцілунок", "Заспокоює ціль, збільшуючи ймовірність того, що вона атакуватиме когось іншого. Дієвіше за \"Заспокійливий поцілунок\" (Ранг {1}).#(Rank {1})", en="Soothing Kiss" },
    [11785] = { "Заспокійливий поцілунок", "Заспокоює ціль, збільшуючи ймовірність того, що вона атакуватиме когось іншого. Дієвіше за \"Заспокійливий поцілунок\" (Ранг {1}).#(Rank {1})", en="Soothing Kiss" },
