    [11839] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [11876] = { "Бойовий тупіт", "Завдає звичайної шкоди плюс {1} навколишнім ворогам, відкидаючи їх та приголомшуючи на {2} с.#plus {1} to#for {2} sec", "Приголомшено.", en="War Stomp" },
