    [11988] = { "Залп вогняних куль", "Завдає шкоди від вогню навколишнім ворогам.", en="Fireball Volley" },
    [11989] = { "Залп вогняних куль", "Завдає шкоди від вогню навколишнім ворогам.", en="Fireball Volley" },
    [12020] = { "Поклик могили", "Завдає {1} шкоди від тіні навколишнім ворогам через {2} с.#Inflicts {1} Shadow#after {2} sec", "{1} шкоди від тіні через {2} с.#{1} Shadow#after {2} sec", ref=5137, en="Call of the Grave" },
    [12021] = { "Зосередження", "Змушує ворога зосередитись на заклиначі та збільшує швидкість атаки заклинача на {1}% протягом {2} с. Поки ціль зосереджена на заклиначі, її увагу важко привернути.#by {1}% for {2} sec", en="Fixate" },
    [12022] = { "Капелюх адмірала", "Збільшує витривалість учасників групи в межах {2} м на {1}.#Gives {1} additional#within {2} yard", "Витривалість збільшено на {1}.#increased by {1}", en="Admiral's Hat" },
    [12024] = { "Сітка", ref=3542, en="Net" },
    [12042] = { "Арканічна могутність", "При активації збільшує шкоду ваших заклять на {1}%, але збільшує витрати мани на їх вимову на {2}%. Триває {3} с.#deal {1}% more#costing {2}% more#lasts {3} sec", "Збільшено шкоду та витрати мани ваших заклять.", en="Arcane Power" },
    [12043] = { "Блиск розуму", "При активації ваше наступне закляття з тривалістю вимови менше {1} с буде миттєвим.#less than {1} sec", "Ваше наступне закляття з тривалістю вимови менше {1} с буде миттєвим.#less than {1} sec", en="Presence of Mind" },
    [12051] = { "Прикликання", "Під час промовляння цього закляття ви відновлюєте ману зі швидкістю {1}% від звичайної. Триває {2} с.#increased by {1}#Lasts {2} sec", "Відновлення мани збільшено на {1}%.#increased by {1}%", en="Evocation" },
    [12054] = { "Розрив", "Завдає ворогу фізичної шкоди кожні {1} с протягом {2} с.#for {1} sec#for {2} sec", "Завдає фізичної шкоди кожні {1} с.#every {1} sec", en="Rend" },
    [12096] = { "Страх", "Вселяє страх у ворога, змушуючи його тікати зі страху протягом {1} с. Одночасно лише одна ціль може бути наляканою.#for up to {1} sec", "Втікає зі страху.", en="Fear" },
    [12097] = { "Пробиття броні", "Зменшує броню ворога на {1}% протягом {2} с.#by {1}% for {2} sec", "Броню зменшено на {1}%.#by {1}%", en="Pierce Armor" },
    [12098] = { "Сон", "Змушує ворожу ціль спати протягом {1} с. Будь-яка шкода розбудить ціль. Одночасно можна змусити спати лише одну ціль.#up to {1} sec", "Спить.", en="Sleep" },
    [12162] = { "Глибокі рани", en="Deep Wounds" },
    [12163] = { "Спеціалізація на дворучній зброї", "Збільшує шкоду дворучної зброї ближнього бою на {1}%.#weapons by {1}%", en="Two-Handed Weapon Specialization" },
    [12166] = { "Розрив м'язів", "Калічить ворога, завдаючи звичайної шкоди плюс {1} та зменшуючи його силу на {2} протягом {3} с.#plus {1} and#by {2} for {3} sec", "Силу зменшено на {1}.#by {1}", en="Muscle Tear" },
    [12174] = { "Спритність", "Збільшує спритність цілі на {1} протягом {2} хв.#by {1} for {2} min", "Спритність збільшено на {1}.#by {1}", en="Agility" },
    [12175] = { "Броня", "Збільшує броню цілі на {1} протягом {2} хв.#by {1} for {2} min", "Броню збільшено на {1}.#by {1}", en="Armor" },
    [12176] = { "Інтелект", "Збільшує інтелект цілі на {1} протягом {2} хв.#by {1} for {2} min", "Інтелект збільшено на {1}.#by {1}", en="Intellect" },
    [12177] = { "Дух", "Збільшує дух цілі на {1} протягом {2} хв.#by {1} for {2} min", "Дух збільшено на {1}.#by {1}", en="Spirit" },
    [12178] = { "Витривалість", "Збільшує витривалість цілі на {1} протягом {2} хв.#by {1} for {2} min", "Витривалість збільшено на {1}.#by {1}", en="Stamina" },
    [12179] = { "Сила", "Збільшує силу цілі на {1} протягом {2} хв.#by {1} for {2} min", "Силу збільшено на {1}.#by {1}", en="Strength" },
    [12180] = { "Кравецтво", "Дозволяє виготовляти надзвичайно стильні сорочки і тканинні обладунки та розвивати навичку до 300 рівня.", en="Tailoring" },
    [12187] = { "Хвороботворна хмара", en="Disease Cloud" },
    [12243] = { "Виклик механічного курчати", "Клацніть правою кнопкою миші, щоб викликати і відпустити курча.", en="Summon Mechanical Chicken" },
    [12245] = { "Заразливий шип", nil, "Отриману фізичну шкоду збільшено на {1}.#by {1}", en="Infected Spine" },
    [12246] = { "Заразливий шип", en="Infected Spine" },
    [12248] = { "Збільшення шкоди", "Збільшує будь-яку отриману ворогом шкоду на {1}% протягом {2} с.#by {1}% for {2} sec", "Отриману фізичну та магічну шкоду збільшено на {1}%.#by {1}%", en="Amplify Damage" },
    [12251] = { "Смертоносна отрута", nil, "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Virulent Poison" },
    [12252] = { "Викид павутини", "Знерухомлює ворогів у конусі перед заклиначем на {1} с.#for {1} sec", "Знерухомлено.", en="Web Spray" },
    [12255] = { "Прокляття Тутен'каша", "Зменшує швидкість вимови заклять навколишніх ворогів на {1}% та збільшує інтервал між їхніми атаками на {2}%. Триває {3} хв.#enemies by {1}%#attacks by {2}%#Lasts {3} min", "Швидкість вимови заклять зменшено на {1}%.\nІнтервал між атаками збільшено на {2}%.#reduced by {1}%#increased by {2}%", en="Curse of Tuten'kash" },
    [12257] = { "Вогняне дихання", "Завдає {1} шкоди вогнем щосекунди протягом {2} секунд усім ворогам перед вами. А також добряче п'янить!#Deals {1} Fire#for {2} sec", en="Breath of Fire" },
    [12279] = { "Прокляття крові", "Збільшує отриману ворогом фізичну шкоду на {1} протягом {2} хв.#by {1} for {2} min", "Отриману фізичну шкоду збільшено на {1}.#by {1}", en="Curse of Blood" },
    [12280] = { "Кислота Гаккара", "Завдає ворогу шкоди від природи кожні {1} с протягом {2} хв.#every {1} sec#for {2} min", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Acid of Hakkar" },
    [12282] = { "Покращений героїчний удар", "Зменшує витрати люті здібності \"Героїчний удар\" на {1}.#by {1} rage", en="Improved Heroic Strike" },
    [12285] = { "Покращений ривок", "Збільшує кількість отриманої люті від здібності \"Ривок\" на {1}.#ability by {1}", en="Improved Charge" },
    [12286] = { "Покращений розрив", "Збільшує шкоду від кровотечі, заподіяної здібністю \"Розрив\", на {1}%.#ability by {1}%", en="Improved Rend" },
    [12287] = { "Покращений громовий удар", "Зменшує витрати люті здібності \"Громовий удар\" на {1}.#by {1} rage", en="Improved Thunder Clap" },
    [12289] = { "Покращене нівечення", "Ваша здібність \"Нівечення\" з ймовірністю {1}% знерухомлює ціль на {2} с.#a {1}% chance#for {2} sec", en="Improved Hamstring" },
    [12290] = { "Покращене здолання", "Збільшує ймовірність завдання критичного удару здібнісю \"Здолання\" на {1}%.#ability by {1}%", en="Improved Overpower" },
    [12292] = { "Розлогі удари", "Наступні {1} атак ближнього бою вражають ще одного ворога неподалік.#next {1} melee", "Наступні {1} атак ближнього бою вражають ще одного ворога неподалік.#next {1} melee", en="Sweeping Strikes" },
    [12294] = { "Смертельний удар", "Жорстокий удар, що завдає шкоди від зброї плюс {1} і ранить ціль, зменшуючи ефективність будь-якого зцілення на {2}% протягом {3} с.#damage plus {1}#healing by {2}% for {3} sec", "Ефективність зцілення зменшено на {1}%.#reduced by {1}%", en="Mortal Strike" },
    [12296] = { "Контроль гніву", "Збільшує час, необхідний для згасання люті поза боєм, на {1}%.#combat by {1}%", en="Anger Management" },
    [12297] = { "Передчуття", "Збільшує вашу навичку захисту на {1}.#by {1}", en="Anticipation" },
    [12298] = { "Спеціалізація на щитах", "Збільшує ймовірність блокуваня атак щитом на {1}% і з ймовірністю {2}% додає {3} люті при блокуванні.#shield by {1}% and has a {2}% chance to generate {3} rage", en="Shield Specialization" },
    [12299] = { "Міць", "Збільшує вашу броню від предметів на {1}%.#items by {1}%", en="Toughness" },
    [12301] = { "Покращена кривава лють", "Збільшує обсяг люті, що надається при активації \"Кривавої люті\" на {1}.#ability by {1}", en="Improved Bloodrage" },
    [12302] = { "Покращена провокація", "Зменшує час відновлення здібності \"Провокація\" на {1} с.#ability by {1} sec", en="Improved Taunt" },
    [12307] = { "Покращений блок щитом", "Дозволяє здібності \"Блок щитом\" блокувати ще одну атаку та збільшує тривалість на {1} с.#by {1} sec", en="Improved Shield Block" },
    [12308] = { "Покращений розкол броні", "Зменшує витрати люті здібності \"Розкол броні\" на {1}.#by {1} rage", en="Improved Sunder Armor" },
    [12311] = { "Покращений удар щитом", "Надає вашій здібності \"Удар щитом\" {1}% імовірності знемовити ціль на {2} с.#{1}% chance#for {2} sec", en="Improved Shield Bash" },
    [12312] = { "Покращена стіна щитів", "Збільшує тривалість ефекту вашої здібності \"Стіна щитів\" на {1} с.#ability by {1} sec", en="Improved Shield Wall" },
    [12313] = { "Покращене роззброєння", "Збільшує тривалість вашої здібності \"Роззброєння\" на {1} с.#ability by {1} sec", en="Improved Disarm" },
    [12317] = { "Несамовитість", "Збільшує шкоду в ближньому бою на {1}% протягом {2} с, але не більше, ніж на {3} ударів після отримання критичного удару.#{1}% melee damage#for {2} sec#{3} swings", en="Enrage" },
    [12318] = { "Покращений бойовий клич", "Збільшує додаткову силу атаки ближнього бою від вашого \"Бойового кличу\" на {1}%.#Shout by {1}%", en="Improved Battle Shout" },
    [12319] = { "Шквал", "Збільшує вашу швидкість атаки на {1}% для наступних {2} ударів після того, як ви завдали критичного удару в ближньому бою.#speed by {1}#next {2} swings", en="Flurry" },
    [12320] = { "Жорстокість", "Збільшує ймовірність завдати критичного удару зброєю ближнього бою на {1}%.#weapons by {1}", en="Cruelty" },
    [12321] = { "Гулкий голос", "[Збільшує область дії та тривалість \"Бойового кличу\" та \"Деморалізуючого кличу\" на {1}%.#area of effect and duration of your Battle Shout and Demoralizing Shout by {1}%][Збільшує область дії \"Бойового кличу\" та \"Деморалізуючого кличу\" на {1}%, збільшує тривалість \"Бойового кличу\" на {2}%, а \"Деморалізуючого кличу\" на {3}% та зменшує витрати люті на \"Бойовий клич\" на {4}%.#Demoralizing Shout by {1}%, increases the duration of Battle Shout by {2}% and Demoralizing Shout by {3}%, and reduces the Rage cost of Battle Shout by {4}%]", en="Booming Voice" },
    [12322] = { "Нестримний гнів", "З ймовірністю {1}% ви отримаєте додаткову одиницю люті при завданні шкоди зброєю ближнього бою.#a {1}% chance", en="Unbridled Wrath" },
    [12323] = { "Пронизливе виття", "Паморочить всіх ворогів навколо, зменшуючи їхню швидкість руху на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість руху зменшено на {1}%.#reduced by {1}%", en="Piercing Howl" },
    [12324] = { "Покращений деморалізуючий клич", "Посилює зниження сили атаки ближнього бою від вашої здібності \"Деморалізуючий клич\" на {1}%.#Shout by {1}%", en="Improved Demoralizing Shout" },
    [12325] = { "Покращена внутрішня лють", "Зменшує час відновлення здіюності \"Внутрішня лють\" на {1} с.#by {1} sec", en="Improved Inner Rage" },
    [12328] = { "Жага смерті", "При активації збільшує фізичну шкоду на {1}% і надає невразливість до ефектів страху, але знижує броню та всі види опору на {2}%. Триває {3} с.#damage by {1}#resistances by {2}#Lasts {3} sec", "Збільшує фізичну шкоду на {1}%. Знижує броню та всі види опору на {2}%. Невразливість до ефектів страху.#damage by {1}#resistances by {2}", en="Death Wish" },
    [12329] = { "Покращене розсічення", "Збільшує додаткову шкоду від здібності \"Розсічення\" на {1}%.#ability by {1}%", en="Improved Cleave" },
