    [12877] = { "Покращений деморалізуючий клич", "Посилює зниження сили атаки ближнього бою від вашої здібності \"Деморалізуючий клич\" на {1}%.#Shout by {1}%", en="Improved Demoralizing Shout" },
    [12878] = { "Покращений деморалізуючий клич", "Посилює зниження сили атаки ближнього бою від вашої здібності \"Деморалізуючий клич\" на {1}%.#Shout by {1}%", en="Improved Demoralizing Shout" },
    [12879] = { "Покращений деморалізуючий клич", "Посилює зниження сили атаки ближнього бою від вашої здібності \"Деморалізуючий клич\" на {1}%.#Shout by {1}%", en="Improved Demoralizing Shout" },
    [12880] = { "Несамовитість", nil, "Шкоду в ближньому бою збільшено на {1}%.#increased by {1}%", en="Enrage" },
