    [12884] = { "Кислотний подих", "Завдає {1} шкоди від природи та додатково {2} шкоди кожні {3} с ворогам у конусі перед заклиначем. Триває {4} с.#Inflicts {1} Nature#additional {2} damage every {3} sec#Lasts {4} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Acid Breath" },
    [12888] = { "Зведення з розуму", "Тимчасово зводить ворожу ціль з розуму, прискорюючи її атаку на {1}% та рух на {2}%, а також змушує її атакувати своїх союзників протягом {3} с.#attacks by {1}%#movement by {2}%#for {3} sec", "Причаровано.\nШвидкість атаки збільшено на {1}%.\nШвидкість руху збільшено на {2}%.#Attack speed increased by {1}%#Movement speed increased by {2}%", en="Cause Insanity" },
    [12889] = { "Прокляття мови", "Примушує навколишніх ворогів говорити мовою демонів, сповільнюючи час вимови всіх заклять на {1}% протягом {2} с. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1}% for {2} sec", "Вимову заклять сповільнено на {1}%.#by {1}%", en="Curse of Tongues" },
    [12891] = { "Кислотний подих", "Завдає {1} шкоди від природи та додатково {2} шкоди кожні {3} с ворогам у конусі перед заклиначем. Триває {4} с.#Inflicts {1} Nature#additional {2} damage every {3} sec#Lasts {4} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Acid Breath" },
    [12944] = { "Покращений блок щитом", "Дозволяє здібності \"Блок щитом\" блокувати ще одну атаку та збільшує тривалість на {1} с.#by {1} sec", en="Improved Shield Block" },
    [12945] = { "Покращений блок щитом", "Дозволяє здібності \"Блок щитом\" блокувати ще одну атаку та збільшує тривалість на {1} с.#by {1} sec", en="Improved Shield Block" },
    [12956] = { "Демонічний обладунок", "Збільшує навичку захисту на {1}, опір тіні на {2} та регенерацію здоров'я на {3}.#Defense by {1}#resistance by {2} and#regeneration by {3}", en="Demon Armor" },
    [12962] = { "Залізна воля", "Збільшує ймовірність протистояти ефектам приголомшення та причарування на {1}%.#by an additional {1}%", en="Iron Will" },
    [12963] = { "Покращене здолання", "Збільшує ймовірність завдання критичного удару здібнісю \"Здолання\" на {1}%.#ability by {1}%", en="Improved Overpower" },
    [12966] = { "Шквал", nil, "Швидкість атаки збільшено на {1}%.#increased by {1}%", en="Flurry" },
    [12975] = { "Бій на смерть", "При активації тимчасово збільшує ваш максимальний запас здоров'я на {1}% протягом {2} с. Після закінчення ефекту додане здоров'я втрачається.#grants you {1}#for {2} sec", en="Last Stand" },
    [12976] = { "Бій на смерть", nil, "Максимальний запас здоров'я збільшено на {1}%.#increased by {1}%", en="Last Stand" },
    [12981] = { "Вбивця невмерлих {1}#Undead Slayer {1}", "Збільшує силу атаки на {1} в бою з невмерлими.#+{1} Attack Power when fighting Undead", en="Undead Slayer 39" },
    [13003] = { "Промінь зменшення", nil, "Силу атаки зменшено на {1}.#reduced by {1}", en="Shrink Ray" },
    [13004] = { "Ріст", nil, "Розмір та силу атаки збільшено.", en="Grow" },
    [13005] = { "Молот правосуддя", "Приголомшує ворога, позбавляючи його можливості рухатися та атакувати на {1} с.#for {1} sec", "Приголомшено.", en="Hammer of Justice" },
    [13006] = { "Промінь зменшення", "Зменшує ціль, знижуючи її силу атаки на {1}. Принаймні, зазвичай він спрацьовує саме так...#power by {1}", en="Shrink Ray" },
    [13013] = { "Розчинення броні", ref=6016, en="Dissolve Armor" },
    [13018] = { "Вибухова хвиля", "Заклинач збурює навколо себе полум'яну хвилю, яка завдає від {1} до {2} шкоди вогнем усім ворогам у радіусі дії, а також паморочить їх на {3} с.#blast for {1} to {2}#dazing them for {3} sec", "Запаморочення.", en="Blast Wave" },
    [13019] = { "Вибухова хвиля", "Заклинач збурює навколо себе полум'яну хвилю, яка завдає від {1} до {2} шкоди вогнем усім ворогам у радіусі дії, а також паморочить їх на {3} с.#blast for {1} to {2}#dazing them for {3} sec", "Запаморочення.", en="Blast Wave" },
    [13020] = { "Вибухова хвиля", "Заклинач збурює навколо себе полум'яну хвилю, яка завдає від {1} до {2} шкоди вогнем усім ворогам у радіусі дії, а також паморочить їх на {3} с.#blast for {1} to {2}#dazing them for {3} sec", "Запаморочення.", en="Blast Wave" },
    [13021] = { "Вибухова хвиля", "Заклинач збурює навколо себе полум'яну хвилю, яка завдає від {1} до {2} шкоди вогнем усім ворогам у радіусі дії, а також паморочить їх на {3} с.#blast for {1} to {2}#dazing them for {3} sec", "Запаморочення.", en="Blast Wave" },
    [13022] = { "Відбивання вогню та аркани", "Відбиває закляття вогню та аркани в заклиначів", "Відбиває закляття вогню та аркани в заклиначів", en="Fire and Arcane Reflect" },
    [13031] = { "Льодяний бар'єр", "Миттєво захищає вас щитом, що поглинає {1} шкоди. Триває {2} хв. Поки щит тримається, вашу вимову заклять не можна перервати.#absorbing {1}#Lasts {2} min", "Поглинає шкоду.", en="Ice Barrier" },
    [13032] = { "Льодяний бар'єр", "Миттєво захищає вас щитом, що поглинає {1} шкоди. Триває {2} хв. Поки щит тримається, вашу вимову заклять не можна перервати.#absorbing {1}#Lasts {2} min", "Поглинає шкоду.", en="Ice Barrier" },
    [13033] = { "Льодяний бар'єр", "Миттєво захищає вас щитом, що поглинає {1} шкоди. Триває {2} хв. Поки щит тримається, вашу вимову заклять не можна перервати.#absorbing {1}#Lasts {2} min", "Поглинає шкоду.", en="Ice Barrier" },
    [13099] = { "Сіткокид", nil, "Не може рухатися.", en="Net-o-Matic" },
    [13120] = { "Сіткокид", "Захоплює ціль у сітку на {1} с. Сітка має багато гачків й іноді зачіпається за одяг власника під час пострілу..#net for {1} sec", en="Net-o-Matic" },
    [13138] = { "Сіткокид", nil, "Сіткокид дав осічку!\nЗнерухомлено.", en="Net-o-Matic" },
    [13140] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [13141] = { "Гномські реактивні черевики", "Ці черевики значно збільшують швидкість руху на 20 секунд. УВАГА: Блок живлення та гіроскопи черевиків не завжди функціонують належним чином.", "Збільшення швидкості бігу. Гіростабілізатори не завжди функціонують належним чином, що призводить до періодичних хибних рухів.", en="Gnomish Rocket Boots" },
    [13158] = { "Несправність реактивних черевиків", nil, "Неконтрольованість!", en="Rocket Boots Malfunction" },
    [13159] = { "Аспект зграї", "Мисливець і учасники групи в межах {1} м переймають аспекти зграї гепардів, збільшуючи швидкість руху на {2}%. Отримана шкода викличе в учасника зграї запаморочення на {3} с. Одночасно може бути активним лише один аспект.#within {1} y#speed by {2}%#for {3} sec", "Швидкість руху збільшено на {1}%. Запаморочення при отриманні шкоди.#{1}% increased", en="Aspect of the Pack" },
    [13161] = { "Аспект звіра", "Мисливець переймає аспекти звіра, внаслідок чого його стає неможливо відстежити. Одночасно може бути активним лише один аспект.", "Неможливо відстежити.", en="Aspect of the Beast" },
    [13163] = { "Аспект мавпи", "Мисливець переймає аспекти мавпи, збільшуючи ймовірність ухилення на {1}%. Одночасно може бути активним лише один аспект.#by {1}", "Збільшує ймовірність ухилення на {1}%.#by {1}", en="Aspect of the Monkey" },
    [13165] = { "Аспект яструба", "Мисливець переймає аспекти яструба, збільшуючи силу атаки дальнього бою на {1}. Одночасно може бути активним лише один аспект.#by {1}", "Збільшує силу атаки дальнього бою на {1}.#by {1}", en="Aspect of the Hawk" },
    [13180] = { "Гномська шапка контролю розуму", "Вступити в ментальний бій з ціллю-гуманоїдом, щоб спробувати захопити контроль над її розумом. Якщо все пройде вдало, ви контролюватимете розум цілі протягом {1} секунд...#for {1} sec", en="Gnomish Mind Control Cap" },
    [13181] = { "Гномська шапка контролю розуму", nil, "Причаровано.", en="Gnomish Mind Control Cap" },
    [13183] = { "Гоблінська гармата-дракон", "Завдає [{1}#Deals {1} fire][від {1} до {2}#Deals {1} to {2} fire] шкоди вогнем протягом {1} с всім ворогам в конусі перед інженером. Це якщо вона не вибухне...#damage for {1} sec to all", "Завдає [{1}#Dealing {1} fire][від {1} до {2}#Dealing {1} to {2} fire] шкоди вогнем щосекунди.", en="Goblin Dragon Gun" },
    [13218] = { "Агонічна отрута", nil, "Всі ефекти зцілення зменшено на {1}.#reduced by {1}", en="Wound Poison" },
    [13219] = { "Агонічна отрута", "Покриває зброю отрутою на {1} хв.\nКожен удар з ймовірністю {2}% отруює ворога, зменшуючи ефективність будь-якого зцілення на {3} протягом {4} с. Ефект накопичується до {5} разів на одній цілі. {6} зарядів.#lasts for {1} min#a {2}% chance#them by {3} for {4} sec#up to {5} times#{6} charges", en="Wound Poison" },
    [13220] = { "Агонічна отрута", "Покриває зброю отрутою на {1} хв. Кожен удар з ймовірністю {2}% отруює ворога, зменшуючи ефективність будь-якого зцілення на {3} протягом {4} с.#lasts for {1} min#{2}% chance#them by {3} for {4} sec", en="Wound Poison" },
    [13222] = { "Агонічна отрута", nil, "Всі ефекти зцілення зменшено на {1}.#reduced by {1}", en="Wound Poison" },
    [13223] = { "Агонічна отрута", nil, "Всі ефекти зцілення зменшено на {1}.#reduced by {1}", en="Wound Poison" },
