    [13390] = { "Збільшення навички захисту", "Збільшує навичку захисту на {1}.#Defense +{1}", en="Increased Defense" },
    [13438] = { "Вогняна куля", "Кидає вогняну кулю, що завдає {1} шкоди від вогню і додатково {2} шкоди протягом {3} с.#causes {1} Fire#additional {2} damage over {3} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire damage every {2} sec", en="Fireball" },
    [13439] = { "Крижана стріла", "Запускає у ворога крижану стрілу, що завдає від {1} до {2} шкоди кригою та зменшує швидкість руху на {3}% протягом {4} с.#causing {1} to {2}#by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Frostbolt" },
    [13440] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [13441] = { "Вогняна стріла", "Завдає цілі від {1} до {2} шкоди вогнем.#for {1} to {2} Fire", en="Firebolt" },
    [13442] = { "Вогняна стріла", "Завдає цілі {1} шкоди вогнем.#for {1} Fire", en="Firebolt" },
    [13443] = { "Розрив", "Завдає ворогу фізичної шкоди кожні {1} с протягом {2} с.#for {1} sec#for {2} sec", "Завдає фізичної шкоди кожні {1} с.#every {1} sec", en="Rend" },
    [13444] = { "Розкол броні", "Розколює броню ворога, зменшуючи її на {1} за кожен ефект \"Розколу броні\". Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено.", en="Sunder Armor" },
    [13445] = { "Розрив", "Завдає ворогу фізичної шкоди кожні {1} с протягом {2} с.#for {1} sec#for {2} sec", "Завдає фізичної шкоди кожні {1} с.#every {1} sec", en="Rend" },
    [13480] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [13482] = { "Блискавка", "Завдає цілі [{1}#for {1} Nature][від {1} до {2}#for {1} to {2} Nature] шкоди від природи.", en="Lightning Bolt" },
    [13486] = { "Рана", "Ранить ціль, завдаючи [{1}#for {1} damage][від {1} до {2}#for {1} to {2} damage] шкоди.", en="Wound" },
    [13490] = { "Виючий клинок", "Зменшує силу атаки цілі на {1} протягом {2} с.#power by {1} for {2} sec", "Силу атаки зменшено на {1}.#power by {1}", en="Howling Blade" },
    [13492] = { "Вбивця звірів", "Збільшує силу атаки на {1} в бою зі звірами.#+{1} Attack Power when fighting Beasts", en="Beast Slaying 63" },
    [13494] = { "Прискорення", "Збільшує вашу швидкість атаки на {1}% протягом {2} с.#speed by {1}% for {2} sec", "Швидкість атаки збільшено.", en="Haste" },
    [13496] = { "Запаморочення", "Сповільнює рух цілі на {1}% протягом {2} с.#movement by {1}% for {2} sec", "Швидкість руху зменшено.", en="Dazed" },
    [13500] = { "Збільшення навички одноручних сокир", "Збільшує навичку володіння сокирами на {1}.#Axes +{1}", en="Increased 1H Axe" },
    [13518] = { "Отрута", "Отруює ціль, завдаючи {1} шкоди від природи кожні {2} с протягом {3} с.#for {1} Nature damage every {2} sec for {3} sec", "{1} шкоди від природи кожні {2} с.#{1} Nature damage#every {2} sec", en="Poison" },
    [13519] = { "Священна кара", "Карає ворога, завдаючи {1} шкоди святістю.#enemy for {1} Holy", en="Holy Smite" },
    [13524] = { "Прокляття Сталвана", "Зменшує всі характеристики цілі на {1} протягом {2} хв.#of target by {1} for {2} min", "Всі характеристики зменшено на {1}.#by {1}", en="Curse of Stalvan" },
    [13526] = { "Їдка отрута", "Їдка кислота завдає цілі {1} шкоди від природи кожні {2} секунди і зменшує її броню на {3} протягом {4} с.#deals {1} Nature#every {2} sec#armor by {3} for {4} sec", "Броню зменшено. Періодична шкода від природи.", en="Corrosive Poison" },
    [13527] = { "Блискавка", "Завдає цілі [{1}#for {1} Nature][від {1} до {2}#for {1} to {2} Nature] шкоди від природи.", en="Lightning Bolt" },
    [13530] = { "Пошесть", "Оскверняє ціль, завдаючи {1} шкоди протягом {2} секунд.#causing {1} damage over {2} sec", "{1} шкоди від тіні кожні {2} с.#Inflicts {1} Shadow#every {2} sec", en="Corruption" },
    [13532] = { "Громовий удар", "Вражає ворогів неподалік, збільшуючи інтервал між їхніми атаками на {1}% на {2} с та завдаючи їм {3} шкоди від природи. Подіє не більше ніж на {4} цілі.#attacks by {1}% for {2} sec and doing {3} Nature damage#up to {4} targets", "Інтервал між атаками збільшено на {1}%.#increased by {1}%", ref=6343, en="Thunder Clap" },
    [13533] = { "Прискорення", "Збільшує вашу швидкість атаки на {1}% протягом {2} с.#speed by {1}% for {2} sec", "Швидкість атаки збільшено.", en="Haste" },
    [13534] = { "Роззброєння", "Роззброєння цілі на {1} с.#for {1} sec", "Роззброєно.", en="Disarm" },
    [13542] = { "Зцілення вихованця", "Відновлює вашому вихованцю {1} здоров'я щосекунди поки ви зосереджуєтеся на зціленні. Триває {2} с.#pet {1} health#Lasts {2} sec", "Відновлює {1} здоров'я щосекунди.#Heals {1}", en="Mend Pet" },
    [13543] = { "Зцілення вихованця", "Відновлює вашому вихованцю {1} здоров'я щосекунди поки ви зосереджуєтеся на зціленні. Триває {2} с.#pet {1} health#Lasts {2} sec", "Відновлює {1} здоров'я щосекунди.#Heals {1}", en="Mend Pet" },
    [13544] = { "Зцілення вихованця", "Відновлює вашому вихованцю {1} здоров'я щосекунди поки ви зосереджуєтеся на зціленні. Триває {2} с.#pet {1} health#Lasts {2} sec", "Відновлює {1} здоров'я щосекунди.#Heals {1}", en="Mend Pet" },
    [13549] = { "Жало змії", "Жалить ціль, завдаючи {1} шкоди від природи протягом {2} с. Лише один ефект жала від кожного мисливця може бути активним на одній цілі.#{1} Nature damage over {2} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature damage every {2} sec", en="Serpent Sting" },
    [13550] = { "Жало змії", "Жалить ціль, завдаючи {1} шкоди від природи протягом {2} с. Лише один ефект жала від кожного мисливця може бути активним на одній цілі.#{1} Nature damage over {2} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature damage every {2} sec", en="Serpent Sting" },
    [13551] = { "Жало змії", "Жалить ціль, завдаючи {1} шкоди від природи протягом {2} с. Лише один ефект жала від кожного мисливця може бути активним на одній цілі.#{1} Nature damage over {2} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature damage every {2} sec", en="Serpent Sting" },
    [13552] = { "Жало змії", "Жалить ціль, завдаючи {1} шкоди від природи протягом {2} с. Лише один ефект жала від кожного мисливця може бути активним на одній цілі.#{1} Nature damage over {2} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature damage every {2} sec", en="Serpent Sting" },
    [13553] = { "Жало змії", "Жалить ціль, завдаючи {1} шкоди від природи протягом {2} с. Лише один ефект жала від кожного мисливця може бути активним на одній цілі.#{1} Nature damage over {2} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature damage every {2} sec", en="Serpent Sting" },
    [13554] = { "Жало змії", "Жалить ціль, завдаючи {1} шкоди від природи протягом {2} с. Лише один ефект жала від кожного мисливця може бути активним на одній цілі.#{1} Nature damage over {2} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature damage every {2} sec", en="Serpent Sting" },
    [13555] = { "Жало змії", "Жалить ціль, завдаючи {1} шкоди від природи протягом {2} с. Лише один ефект жала від кожного мисливця може бути активним на одній цілі.#{1} Nature damage over {2} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature damage every {2} sec", en="Serpent Sting" },
    [13579] = { "Ошелешення", "Завдає ворогу {1} шкоди та приголомшує його на {2} с. Ви автоматично перестанете атакувати. Ціль має бути повернута до вас. Будь-яка шкода перериває дію ефекту на цілі.#Inflicts {1} damage#for up to {2} sec", "Недієздатність.", en="Gouge" },
    [13582] = { "Смертельна отрута", "Завдає {1} шкоди від природи навколишнім ворогам кожні {2} с протягом {3} хв.#Inflicts {1} Nature#every {2} sec#for {3} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Deadly Poison" },
    [13583] = { "Прокляття Мертволісих", "Зменшує ефективність зцілення ворога на {1}% протягом {2} хв.#by {1}% for {2} min", "Ефективність зцілення зменшено на {1}%.#reduced by {1}%", en="Curse of the Deadwood" },
    [13590] = { "Збільшення шкоди від аркани {1}#Arcane Dam {1}", "Збільшує шкоду від заклинань і ефектів аркани на {1}.#Arcane spells and effects by up to {1}", en="Increase Arcane Dam 1" },
    [13608] = { "Сітка з гачками", "Знерухомлює ворога на {1} с та завдає фізичної шкоди.#for {1} sec", "Знерухомлено.", en="Hooked Net" },
    [13665] = { "Парирування {1}#Increased Parry {1}", "Збільшує шанс парирування атаки на {1}%.#parry an attack by {1}%", en="Increased Parry 1" },
    [13669] = { "Ухилення {1}#Increased Dodge {1}", "Збільшує шанс ухилення від атаки на {1}%.#dodge an attack by {1}%", en="Increased Dodge 1" },
    [13674] = { "Блокування {1}#Increased Block {1}", "Збільшує шанс блокування атак щитом на {1}%.#block attacks with a shield by {1}%", en="Increased Block 1" },
    [13692] = { "Страшне гарчання", "Зменшує силу ворога на {1}, а спритність на {2} протягом {3} с.#Strength by {1}#Agility by {2} for {3} sec", "Силу зменшено на {1}.\nСпритність зменшено на {2}.#Strength reduced by {1}#Agility reduced by {2}", en="Dire Growl" },
    [13704] = { "Психічний крик", "Вивільнює психічний крик, що змушує до {1} навколишніх ворогів тікати геть протягом {2} с.#up to {1} nearby#for {2} sec", "Втікає зі страху.", en="Psychic Scream" },
    [13705] = { "Точність", "Збільшує ймовірність завдати удару зброєю ближнього бою на {1}%.#by {1}%", en="Precision" },
    [13707] = { "Спеціалізація на кулачній зброї", "Збільшує ймовірність завдати критичного удару кулачною зброєю на {1}%.#by {1}%", en="Fist Weapon Specialization" },
    [13712] = { "Блискавичні рефлекси", "Збільшує вашу ймовірність ухилення на {1}%.#by {1}%", en="Lightning Reflexes" },
    [13713] = { "Відбиття", "Збільшує вашу ймовірність парирування на {1}%.#by {1}%", en="Deflection" },
    [13715] = { "Спеціалізація на бою з двох рук", "Збільшує шкоду від зброї в лівій руці на {1}%.#weapon by {1}%", en="Dual Wield Specialization" },
    [13729] = { "Вогняний шок", "Обпалює ворога, завдаючи шкоди вогнем кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Flame Shock" },
    [13730] = { "Деморалізуючий клич", "Зменшує силу атаки ближнього бою ворогів поблизу на {1} протягом {2} с.#enemies by {1} for {2} sec", "Силу атаки ближнього бою зменшено на {1}.#by {1}", en="Demoralizing Shout" },
    [13732] = { "Покращений підступний удар", "Зменшує витрати енергії здібності \"Підступний удар\" на {1}.#by {1}", en="Improved Sinister Strike" },
    [13736] = { "Вихор", "Атакує навколишніх ворогів сталевим вихром протягом {1} с, завдаючи звичайної шкоди плюс {2}.#lasts {1} sec#plus {2}", "Атакує навколишніх ворогів, завдаючи звичайної шкоди плюс {1}.#plus {1}", en="Whirlwind" },
    [13737] = { "Смертельний удар", "Завдає {1}% шкоди від зброї та ранить ціль, зменшуючи ефективність будь-якого зцілення на {2}% протягом {3} с.#Inflicts {1}% weapon#healing by {2}% for {3} sec", "Ефективність зцілення зменшено на {1}%.#reduced by {1}%", en="Mortal Strike" },
    [13738] = { "Розрив", "Завдає ворогу фізичної шкоди кожні {1} с протягом {2} с.#for {1} sec#for {2} sec", "Завдає фізичної шкоди кожні {1} с.#every {1} sec", en="Rend" },
    [13741] = { "Покращене ошелешення", "Збільшує тривалість ефекту здібності \"Ошелешення\" на {1} с.#by {1} sec", en="Improved Gouge" },
    [13742] = { "Витримка", "Зменшує час відновлення ваших здібностей \"Спринт\" та \"Уникнення\" на {1} с.#by {1} sec", en="Endurance" },
    [13743] = { "Покращений спринт", "Ви з ймовірністю {1}% знімете всі ефекти обмеження руху при активації здібності \"Спринт\".#a {1}% chance", en="Improved Sprint" },
    [13744] = { "Палаюча емблема", "Збільшує опір вогню на {1} і зменшує всю отриману шкоду від вогню на {2} протягом {3} с.#resistance by {1} and#taken by up to {2} for {3} sec", "Збільшено опір вогню та зменшено отриману шкоду від вогню. ", en="Blazing Emblem" },
    [13747] = { "Сповільнення", "Збільшує інтервал між атаками навколишніх ворогів на {1}% та зменшує їх швидкість руху на {2}% протягом {3} с.#attacks by {1}%#movement by {2}% for {3} sec", "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Slow" },
    [13750] = { "Викид адреналіну", "Збільшує швидкість відновлення енергії на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість відновлення енергії збільшено на {1}%.#by {1}%", en="Adrenaline Rush" },
    [13752] = { "Чарівний вогонь", "Зменшує броню цілі на {1} протягом {2} с. Під час дії ефекту ціль не може отримати ефект непомітності чи невидимості.#by {1} for {2} sec", "Броню зменшено на {1}. Не може отримати ефект непомітності чи невидимості.#armor by {1}", en="Faerie Fire" },
    [13754] = { "Покращений копняк", "Здібність \"Копняк\" з ймовірністю {1}% знемовлює ціль на {2} с.#a {1}% chance#for {2} sec", en="Improved Kick" },
    [13795] = { "Обпалююча пастка", "Встановити вогняну пастку, яка підпалить першого ворога при наближенні й завдасть {1} шкоди вогнем протягом {2} с. Пастка існуватиме {3} хв. Пастки можна встановлювати лише поза боєм. Одночасно може бути активною лише одна пастка.#for {1} Fire damage over {2} sec#exist for {3} min", en="Immolation Trap" },
    [13797] = { "Ефект обпалюючої пастки", nil, "{1} шкоди вогнем кожні {2} c.#{1} Fire damage every {2} sec", en="Immolation Trap Effect" },
    [13808] = { "Ручна осколкова граната M73", ref=4064, en="M73 Frag Grenade" },
    [13809] = { "Крижана пастка", "Встановити крижану пастку, яка вкриває льодом місцевість навколо на {1} с при наближенні першого ворога. Всі вороги в радіусі {2} м будуть сповільнені на {3}% допоки перебувають в зоні ефекту. Пастка існуватиме {4} хв. Пастки можна встановлювати лише поза боєм. Одночасно може бути активною лише одна пастка.#around itself for {1} sec#within {2} y#slowed by {3}#exist for {4} min", en="Frost Trap" },
    [13810] = { "Аура крижаної пастки", nil, "Швидкість руху зменшено на {1}%.#by {1}%", en="Frost Trap Aura" },
    [13812] = { "Ефект вибухової пастки", nil, "{1} шкоди вогнем кожні {2} c.#{1} Fire damage every {2} sec", en="Explosive Trap Effect" },
    [13813] = { "Вибухова пастка", "Встановити вогняну пастку, яка вибухне при наближенні ворога, завдаючи від {1} до {2} шкоди вогнем і додатково {3} шкоди вогнем протягом {4} с усім ворогам у радіусі {5} м. Пастка існуватиме {6} хв. Пастки можна встановлювати лише поза боєм. Одночасно може бути активною лише одна пастка.#causing {1} to {2}#{3} additional Fire damage over {4} sec#within {5} y#exist for {6} min", en="Explosive Trap" },
    [13819] = { "Виклик бойового коня", "Викликає бойового коня для верхової їзди. Збільшує швидкість руху на {1}%.#by {1}%", "Швидкість руху збільшено на {1}%.#by {1}%", en="Summon Warhorse" },
    [13847] = { "Навіженість", nil, "Невразливість до ефектів страху.\nВсі атаки завдають критичної шкоди.\nБроню зменшено на {1}%.#by {1}%", en="Recklessness" },
    [13864] = { "Слово сили: Стійкість", "Збільшує витривалість союзника на {1} протягом {2} хв.#by {1} for {2} min", "Витривалість збільшено на {1}.#by {1}", en="Power Word: Fortitude" },
    [13877] = { "Шквал клинків", "Збільшує вашу швидкість атаки на {1}%. Ваші атаки також завдають удару ще одному ворогу неподалік. Триває {2} с.#by {1}%#Lasts {2} sec", "Швидкість атаки збільшено на {1}%. Атаки зброєю завдають удару ще одному ворогу неподалік.#by {1}%", en="Blade Flurry" },
    [13880] = { "Сплеск магми", nil, "{1} шкоди вогнем кожні {2} с.\nБроню зменшено на {3}.#{1} Fire#every {2} sec#reduced by {3}", en="Magma Splash" },
    [13884] = { "Отрута зав'ядання", nil, "Завдає шкоди від природи кожні {1} с.\nСилу та спритність зменшено.#every {1} sec", en="Withering Poison" },
    [13896] = { "Відгомін", "Жерця оточує антимагічна енергія. Будь-яке успішне закляття проти нього спалить {1} мани нападника та завдасть {2} шкоди тінню за кожну одиницю спаленої мани. Триває {3} с.#burn {1}#causing {2}#Lasts {3} sec", "Антимагічна енергія спалить {1} мани нападника та завдасть {2} шкоди тінню за кожну одиницю спаленої мани.#burn {1}#causing {2}", en="Feedback" },
    [13902] = { "Кулак Раґнароса", ref=3609, en="Fist of Ragnaros" },
    [13908] = { "Відчайдушна молитва", "Миттєво зцілює заклиначеві від {1} до {2} здоров'я.#for {1} to {2}", en="Desperate Prayer" },
    [13920] = { "Накладання чарів", "Дозволяє накладати майстерні чари на зброю і обладунки та розвивати навичку до 300 рівня.", en="Enchanting" },
    [13958] = { "Майстер омани", "Зменшує ймовірність того, що вороги помітять вас під час дії непомітності.", en="Master of Deception" },
    [13959] = { "Електростатичний заряд", "З ймовірністю {1}% при отриманні удару в бою ви завдасте нападнику [{1}#inflicting {1} Nature][від {1} до {2}#inflicting {1} to {2} Nature] шкоди від природи.#a {1}% chance", en="Electrostatic Charge" },
    [13966] = { "Спеціалізація на кулачній зброї", "Збільшує ймовірність завдати критичного удару кулачною зброєю на {1}%.#by {1}%", en="Fist Weapon Specialization" },
    [13967] = { "Спеціалізація на кулачній зброї", "Збільшує ймовірність завдати критичного удару кулачною зброєю на {1}%.#by {1}%", en="Fist Weapon Specialization" },
    [13968] = { "Спеціалізація на кулачній зброї", "Збільшує ймовірність завдати критичного удару кулачною зброєю на {1}%.#by {1}%", en="Fist Weapon Specialization" },
    [13969] = { "Спеціалізація на кулачній зброї", "Збільшує ймовірність завдати критичного удару кулачною зброєю на {1}%.#by {1}%", en="Fist Weapon Specialization" },
    [13975] = { "Камуфляж", "Збільшує вашу швидкість руху в стані непомітності на {1}% та зменшує час відновлення вашої здібності \"Непомітність\" на {2} с.#by {1}%#by {2} sec", en="Camouflage" },
    [13976] = { "Ініціатива", "Надає вам {1}% ймовірності збільшити довжину комбінації на додатковий прийом при використанні здібності \"Засідка\", \"Гарота\" або \"Брудний прийом\".#a {1}% chance", en="Initiative" },
    [13981] = { "Невловимість", "Зменшує час відновлення ваших здібностей \"Зникнення\" та \"Засліплення\" на {1} с.#by {1} sec", en="Elusiveness" },
    [13983] = { "Налаштованість", "Надає вам {1}% імовірності збільшити довжину комбінації по цілі на один прийом після ухилення від атаки чи повного опору закляттю.#{1}% chance", en="Setup" },
    [14030] = { "Сітка з гачками", "Знерухомлює ворога на {1} с та завдає фізичної шкоди.#for {1} sec", "Знерухомлено.", en="Hooked Net" },
