    [14304] = { "Обпалююча пастка", "Встановити вогняну пастку, яка підпалить першого ворога при наближенні й завдасть {1} шкоди вогнем протягом {2} с. Пастка існуватиме {3} хв. Пастки можна встановлювати лише поза боєм. Одночасно може бути активною лише одна пастка.#for {1} Fire damage over {2} sec#exist for {3} min", en="Immolation Trap" },
    [14305] = { "Обпалююча пастка", "Встановити вогняну пастку, яка підпалить першого ворога при наближенні й завдасть {1} шкоди вогнем протягом {2} с. Пастка існуватиме {3} хв. Пастки можна встановлювати лише поза боєм. Одночасно може бути активною лише одна пастка.#for {1} Fire damage over {2} sec#exist for {3} min", en="Immolation Trap" },
    [14308] = { "Ефект заморожувальної пастки", nil, "Заморожено.", en="Freezing Trap Effect" },
    [14309] = { "Ефект заморожувальної пастки", nil, "Заморожено.", en="Freezing Trap Effect" },
    [14310] = { "Заморожувальна пастка", "Встановити крижану пастку, яка заморозить першого ворога при наближенні та унеможливить всі його дії впродовж {1} с. Будь-яка шкода розіб'є лід. Пастка існуватиме {2} хв. Пастки можна встановлювати лише поза боєм. Одночасно може бути активною лише одна пастка.#action for up to {1} sec#exist for {2} min", en="Freezing Trap" },
    [14311] = { "Заморожувальна пастка", "Встановити крижану пастку, яка заморозить першого ворога при наближенні та унеможливить всі його дії впродовж {1} с. Будь-яка шкода розіб'є лід. Пастка існуватиме {2} хв. Пастки можна встановлювати лише поза боєм. Одночасно може бути активною лише одна пастка.#action for up to {1} sec#exist for {2} min", en="Freezing Trap" },
    [14314] = { "Ефект вибухової пастки", nil, "{1} шкоди вогнем кожні {2} c.#{1} Fire damage every {2} sec", en="Explosive Trap Effect" },
    [14315] = { "Ефект вибухової пастки", nil, "{1} шкоди вогнем кожні {2} c.#{1} Fire damage every {2} sec", en="Explosive Trap Effect" },
    [14316] = { "Вибухова пастка", "Встановити вогняну пастку, яка вибухне при наближенні ворога, завдаючи від {1} до {2} шкоди вогнем і додатково {3} шкоди вогнем протягом {4} с усім ворогам у радіусі {5} м. Пастка існуватиме {6} хв. Пастки можна встановлювати лише поза боєм. Одночасно може бути активною лише одна пастка.#causing {1} to {2}#{3} additional Fire damage over {4} sec#within {5} y#exist for {6} min", en="Explosive Trap" },
    [14317] = { "Вибухова пастка", "Встановити вогняну пастку, яка вибухне при наближенні ворога, завдаючи від {1} до {2} шкоди вогнем і додатково {3} шкоди вогнем протягом {4} с усім ворогам у радіусі {5} м. Пастка існуватиме {6} хв. Пастки можна встановлювати лише поза боєм. Одночасно може бути активною лише одна пастка.#causing {1} to {2}#{3} additional Fire damage over {4} sec#within {5} y#exist for {6} min", en="Explosive Trap" },
    [14318] = { "Аспект яструба", "Мисливець переймає аспекти яструба, збільшуючи силу атаки дальнього бою на {1}. Одночасно може бути активним лише один аспект.#by {1}", "Збільшує силу атаки дальнього бою на {1}.#by {1}", en="Aspect of the Hawk" },
    [14319] = { "Аспект яструба", "Мисливець переймає аспекти яструба, збільшуючи силу атаки дальнього бою на {1}. Одночасно може бути активним лише один аспект.#by {1}", "Збільшує силу атаки дальнього бою на {1}.#by {1}", en="Aspect of the Hawk" },
    [14320] = { "Аспект яструба", "Мисливець переймає аспекти яструба, збільшуючи силу атаки дальнього бою на {1}. Одночасно може бути активним лише один аспект.#by {1}", "Збільшує силу атаки дальнього бою на {1}.#by {1}", en="Aspect of the Hawk" },
    [14321] = { "Аспект яструба", "Мисливець переймає аспекти яструба, збільшуючи силу атаки дальнього бою на {1}. Одночасно може бути активним лише один аспект.#by {1}", "Збільшує силу атаки дальнього бою на {1}.#by {1}", en="Aspect of the Hawk" },
    [14322] = { "Аспект яструба", "Мисливець переймає аспекти яструба, збільшуючи силу атаки дальнього бою на {1}. Одночасно може бути активним лише один аспект.#by {1}", "Збільшує силу атаки дальнього бою на {1}.#by {1}", en="Aspect of the Hawk" },
    [14323] = { "Мітка мисливця", "Відмічає ціль мисливською міткою, збільшуючи силу атаки дальнього бою всіх нападників проти відміченої цілі на {1}. Окрім того мисливець завжди бачить відмічену ціль, навіть якщо та стає непомітною або невидимою. Ціль також відображається на мінімапі. Триває {2} хв.#target by {1}#Lasts for {2} min", "Всі нападники отримують додатково {1} сили атаки дальнього бою проти цієї цілі.#gain {1} Ranged", en="Hunter's Mark" },
    [14324] = { "Мітка мисливця", "Відмічає ціль мисливською міткою, збільшуючи силу атаки дальнього бою всіх нападників проти відміченої цілі на {1}. Окрім того мисливець завжди бачить відмічену ціль, навіть якщо та стає непомітною або невидимою. Ціль також відображається на мінімапі. Триває {2} хв.#target by {1}#Lasts for {2} min", "Всі нападники отримують додатково {1} сили атаки дальнього бою проти цієї цілі.#gain {1} Ranged", en="Hunter's Mark" },
    [14325] = { "Мітка мисливця", "Відмічає ціль мисливською міткою, збільшуючи силу атаки дальнього бою всіх нападників проти відміченої цілі на {1}. Окрім того мисливець завжди бачить відмічену ціль, навіть якщо та стає непомітною або невидимою. Ціль також відображається на мінімапі. Триває {2} хв.#target by {1}#Lasts for {2} min", "Всі нападники отримують додатково {1} сили атаки дальнього бою проти цієї цілі.#gain {1} Ranged", en="Hunter's Mark" },
    [14326] = { "Відлякування звіра", "Відлякує звіра, змушуючи його тікати з переляку протягом {1} с. Завдана шкода може перервати ефект. Одночасно лише один звір може бути наляканим.#for up to {1} sec", "Налякано.", en="Scare Beast" },
    [14327] = { "Відлякування звіра", "Відлякує звіра, змушуючи його тікати з переляку протягом {1} с. Завдана шкода може перервати ефект. Одночасно лише один звір може бути наляканим.#for up to {1} sec", "Налякано.", en="Scare Beast" },
    [14331] = { "Жахливий розрив", ref=11977, en="Vicious Rend" },
    [14515] = { "Підкорення розуму", "Бере під контроль ворога-гуманоїда до {1} рівня на {2} с.#level {1} for {2} sec", "Причаровано.", en="Dominate Mind" },
    [14517] = { "Удар лицаря", "Завдає ворогу {1} шкоди та збільшує отриману ним шкоду від святості на {2} за кожен \"Удар лицаря\". Ефект може накопичуватись до {3} разів. Триває {4} с.#Inflicts {1} damage#takes by {2} per#applied up to {3} times#Lasts {4} sec", "Отриману шкоду святістю збільшено.", en="Crusader Strike" },
    [14518] = { "Удар лицаря", "Завдає ворогу {1} шкоди та збільшує отриману ним шкоду від святості на {2} за кожен \"Удар лицаря\". Ефект може накопичуватись до {3} разів. Триває {4} с.#Inflicts {1} damage#takes by {2} per#applied up to {3} times#Lasts {4} sec", "Отриману шкоду святістю збільшено.", en="Crusader Strike" },
    [14520] = { "Спритність розуму", "Зменшує витрати мани ваших миттєвих заклять на {1}%.#by {1}%", en="Mental Agility" },
    [14521] = { "Медитація", "Дозволяє {1}% відновлення мани продовжуватися під час вимови заклять.#{1}% of your Mana", en="Meditation" },
    [14522] = { "Незламна воля", "Збільшує ваш шанс протистояти приголомшенню, страху та знемовленню на {1}%.#additional {1}%", en="Unbreakable Will" },
    [14523] = { "Мовчазна рішучість", "Зменшує рівень загрози від ваших заклять на {1}%.#by {1}%", en="Silent Resolve" },
    [14524] = { "Спеціалізація на жезлах", "Збільшує шкоду жезлів на {1}%.#by {1}%", en="Wand Specialization" },
    [14530] = { "Швидкість", "Збільшує швидкість бігу на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість бігу збільшено на {1}%.#by {1}%", en="Speed" },
    [14531] = { "Мучеництво", "Після отримання критичного удару в ближньому чи дальньому бою ви з ймовірністю {1}% отримаєте ефект \"Зосередженої вимови\" на {2} с. \"Зосереджена вимова\" оберігає вас від затримки вимови заклять при отриманні шкоди та збільшує опір ефектам переривання на {3}%.#a {1}% chance#for {2} sec#by {3}%", en="Martyrdom" },
    [14533] = { "Розщеплення", "Збільшує отриману навколишніми ворогами шкоду від вогню, криги та аркани на {1}% протягом {2} хв.#by {1}% for {2} min", "Отриману шкоду від вогню, криги та аркани збільшено на {1}%.#by {1}%", en="Disjunction" },
    [14535] = { "Землечерпна хвороба", "Зменшує всі характеристики навколишніх ворогів на {1}% протягом {2} хв.#by {1}% for {2} min", "Всі характеристики зменшено на {1}%.#by {1}%", en="Dredge Sickness" },
    [14538] = { "Акустичний шок", "Сповільнює вимову заклять навколишніх ворогів на {1}% протягом {2} хв.#by {1}% for {2} min", "Вимову заклять сповільнено на {1}%.#by {1}%", en="Aural Shock" },
    [14539] = { "Гнилісний фермент", "Збільшує отриману навколишніми ворогами шкоду від природи на {1}% та збільшує отриману ними шкоду від тіні на {2}%. Триває {3} хв.#enemies by {1}%#take by {2}%#Lasts {3} min", "Отриману шкоду від природи збільшено на {1}%.\nОтриману шкоду від тіні збільшено на {2}%.#Nature damage taken is increased by {1}%#Shadow damage taken is increased by {2}%", en="Putrid Enzyme" },
    [14621] = { "Поліморфія", "Перетворює вас на вівцю, змушуючи вас блукати до {1} с. Вівця не здатна атакувати або вимовляти закляття, а будь-яка шкода поверне вас до нормального стану.#up to {1} sec", "Не може атакувати та вимовляти закляття.", en="Polymorph" },
    [14747] = { "Покращений внутрішній вогонь", "Збільшує додаткову броню від закляття \"Внутрішній вогонь\" на {1}%.#by {1}%", en="Improved Inner Fire" },
    [14748] = { "Покращене слово сили: Щит", "Збільшує обсяг шкоди, яку може поглинути \"Слово сили: Щит\", на {1}%.#by {1}%", en="Improved Power Word: Shield" },
    [14749] = { "Покращене слово сили: Стійкість", "Збільшує ефективність заклять \"Слово сили: Стійкість\" та \"Молитва стійкості\" на {1}%.#by {1}%", en="Improved Power Word: Fortitude" },
    [14750] = { "Покращене спалення мани", "Зменшує час вимови закляття \"Спалення мани\" на {1} с.#by {1} sec", en="Improved Mana Burn" },
    [14751] = { "Внутрішнє зосередження", "При активації зменшує витрати мани вашого наступного закляття на {1}% та збільшує ймовірність його критичного ефекту на {2}%, якщо такий ефект можливий.#spell by {1}%#chance by {2}%", "Витрати мани на ваше наступне закляття зменшено на {1}%.#reduced by {1}%", en="Inner Focus" },
    [14752] = { "Божественний дух", "Свята сила наповнює ціль, збільшуючи її дух на {1} протягом {2} хв.#by {1} for {2} min", "Збільшує дух на {1}.#by {1}", en="Divine Spirit" },
    [14767] = { "Покращене слово сили: Стійкість", "Збільшує ефективність заклять \"Слово сили: Стійкість\" та \"Молитва стійкості\" на {1}%.#by {1}%", en="Improved Power Word: Fortitude" },
    [14817] = { "Збільшення навички дворучних сокир", "Збільшує навичку володіння дворучними сокирами на {1}.#Axes +{1}", en="Increased 2H Axe" },
    [14818] = { "Божественний дух", "Свята сила наповнює ціль, збільшуючи її дух на {1} протягом {2} хв.#by {1} for {2} min", "Збільшує дух на {1}.#by {1}", en="Divine Spirit" },
    [14819] = { "Божественний дух", "Свята сила наповнює ціль, збільшуючи її дух на {1} протягом {2} хв.#by {1} for {2} min", "Збільшує дух на {1}.#by {1}", en="Divine Spirit" },
    [14824] = { "Швидкість дальнього бою", "Збільшує швидкість атак дальнього бою на {1}%.#ranged attack speed by {1}%", en="Haste" },
    [14825] = { "Швидкість дальнього бою", "Збільшує швидкість атак дальнього бою на {1}%.#ranged attack speed by {1}%", en="Haste" },
    [14826] = { "Швидкість дальнього бою", "Збільшує швидкість атак дальнього бою на {1}%.#ranged attack speed by {1}%", en="Haste" },
    [14827] = { "Швидкість дальнього бою", "Збільшує швидкість атак дальнього бою на {1}%.#ranged attack speed by {1}%", en="Haste" },
    [14828] = { "Швидкість дальнього бою", "Збільшує швидкість атак дальнього бою на {1}%.#ranged attack speed by {1}%", en="Haste" },
    [14829] = { "Швидкість дальнього бою", "Збільшує швидкість атак дальнього бою на {1}%.#ranged attack speed by {1}%", en="Haste" },
    [14868] = { "Прокляття агонії", "Проклинає ціль агонією, завдаючи шкоди тінню кожні {1} с протягом {2} с. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#every {1} sec#over {2} sec", "Завдає шкоди від тіні кожні {1} с.#every {1} sec", en="Curse of Agony" },
    [14874] = { "Розрив", ref=11977, en="Rupture" },
    [14875] = { "Прокляття агонії", "Проклинає ціль агонією, завдаючи шкоди тінню кожні {1} с протягом {2} с. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#every {1} sec#over {2} sec", "Завдає шкоди від тіні кожні {1} с.#every {1} sec", en="Curse of Agony" },
    [14889] = { "Спеціалізація на святості", "Збільшує ймовірність критичного ефекту ваших заклять святості на {1}%.#by {1}%", en="Holy Specialization" },
    [14892] = { "Натхнення", "Збільшує броню вашої цілі на {1}% протягом {2} с після критичного ефекту [будь-яких ваших заклять зцілення#any of your heals][ваших заклять \"Швидке зцілення\", \"Зцілення\", \"Велике зцілення\" або \"Молитва зцілення\"#your Flash Heal].#armor by {1}% for {2} sec", en="Inspiration" },
    [14893] = { "Натхнення", nil, "Збільшує броню на {1}%.#by {1}%", en="Inspiration" },
    [14897] = { "Сповільнююча отрута", "Збільшує інтервал між атаками ворога на {1}% та зменшує його швидкість руху на {2}% протягом {3} с.#attacks by {1}%#movement by {2}% for {3} sec", "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Slowing Poison" },
    [14898] = { "Духовне зцілення", "Збільшує обсяг зцілення вашими цілющими закляттями на {1}%.#by {1}%", en="Spiritual Healing" },
    [14901] = { "Духовне покровительство", "Збільшує шкоду та зцілення заклять на {1}% від вашого духу.#by up to {1}% of", en="Spiritual Guidance" },
    [14907] = { "Крижаний спалах", "Вражає ворогів неподалік кригою, знерухомлюючи їх на {1} с.#immobilizing them for up to {1} sec", "Знерухомлено", en="Frost Nova" },
    [14908] = { "Покращене оновлення", "Збільшує зцілення закляттям \"Оновлення\" на {1}%.#by {1}%", en="Improved Renew" },
    [14909] = { "Обпалююче світло", "Збільшує шкоду заклять \"Кара\" та \"Священний вогонь\" на {1}%.#by {1}%", en="Searing Light" },
    [14912] = { "Покращене зцілення", "Знижує витрати мани заклять \"Мале зцілення\", \"Зцілення\" та \"Велике зцілення\" на {1}%.#by {1}%", en="Improved Healing" },
    [14914] = { "Священний вогонь", "Ворога охоплює священне полум'я, що завдає від {1} до {2} шкоди святістю та додатково {3} шкоди святістю протягом {4} с.#cause {1} to {2} Holy#additional {3} Holy damage over {4} sec", "{1} шкоди святістю кожні {2} с.#{1} Holy damage every {2} sec", en="Holy Fire" },
