    [15404] = { "Мале арканічне посилення", "Додати на поножі або головний убір чари, що збільшують інтелект на 8. Не поєднується з іншими чарами на предметі.", en="Lesser Arcane Amalgamation" },
    [15406] = { "Мале арканічне посилення", "Додати на поножі або головний убір чари, що збільшують дух на 8. Не поєднується з іншими чарами на предметі.", en="Lesser Arcane Amalgamation" },
    [15407] = { "Муки розуму", "Вражає розум цілі енергією тіні, завдаючи {1} шкоди від тіні протягом {2} с та сповільнюючи її рух на {3}%.#causing {1} Shadow#over {2} sec#speed by {3}%", "Швидкість руху зменшено на {1}%.#by {1}%", en="Mind Flay" },
    [15430] = { "Священний спалах", "Створює вибух священного світла навколо заклинача, завдаючи від {1} до {2} шкоди святістю ворожим цілям в радіусі {3} м і зцілюючи від {5} до {6} здоров'я учасникам групи в межах {4} м. Ці ефекти не спричиняють загрози.#causing {1} to {2} Holy#targets within {3} y#members within {4} yards for {5} to {6}", en="Holy Nova" },
    [15431] = { "Священний спалах", "Створює вибух священного світла навколо заклинача, завдаючи від {1} до {2} шкоди святістю ворожим цілям в радіусі {3} м і зцілюючи від {5} до {6} здоров'я учасникам групи в межах {4} м. Ці ефекти не спричиняють загрози.#causing {1} to {2} Holy#targets within {3} y#members within {4} yards for {5} to {6}", en="Holy Nova" },
    [15438] = { "Шипи", "При отриманні удару в бою завдає {1} арканічної шкоди нападнику.#inflicts {1} Arcane", en="Thorns" },
    [15470] = { "Прокляття мови", "Примушує навколишніх ворогів говорити мовою демонів, сповільнюючи час вимови всіх заклять на {1}% протягом {2} с. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1}% for {2} sec", "Вимову заклять сповільнено на {1}%.#by {1}%", en="Curse of Tongues" },
    [15471] = { "Огортання павутиною", "Знерухомлює ворога, збільшує інтервал між його атаками на {1}% та запобігає вимові заклять протягом {2} с.#attacks by {1}%#for {2} sec", "Не може рухатись та вимовляти закляття.\nІнтервал між атаками збільшено на {1}%.#by {1}%", en="Enveloping Web" },
    [15473] = { "Тінеобраз", "Прийняти тінеобраз, що збільшує вашу шкоду від тіні на {1}%[, зменшує витрати мани на закляття тіні на {1}%#reducing the mana cost of all Shadow spells by {1}%] та зменшує отриману вами фізичну шкоду на {2}%. Однак у цьому образі ви не можете вимовляти закляття святості.#Shadow damage by {1}%#done to you by {2}%", "Ваша шкода від тіні збільшена на {1}%.[ Витрати мани на закляття тіні зменшено на {1}%.#cost of all Shadow spells reduced by {1}%] Отриману фізичну шкоду зменшено на {2}%. Ви не можете вимовляти закляття святості.#increased by {1}%#take reduced by {2}%", en="Shadowform" },
    [15474] = { "Павутинний вибух", "Знерухомлює ворогів неподалік на {1} с.#for {1} sec", "Знерухомлено.", en="Web Explosion" },
    [15487] = { "Знемовлення", "Знемовлює ціль, запобігаочи вимові заклять протягом {1} с.#for {1} sec", "Знемовлено.", en="Silence" },
    [15494] = { "Лють Файнокова", "Дає 2 додаткові атаки під час наступного замаху.", "Сповнено духом Франклорна Файнокова. Може говорити лише дворфійською мовою.", en="Fury of Forgewright" },
    [15497] = { "Крижана стріла", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frostbolt" },
    [15499] = { "Крижаний шок", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frost Shock" },
    [15502] = { "Розкол броні", "Вражає навколишніх ворогів, зменшуючи їх броню на {1} за кожен ефект \"Розколу броні\". Ефект накопичується до {2} разів. Триває {3} с.#armor by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено.", en="Sunder Armor" },
    [15505] = { "Жертовний вогонь", "Обпалює ворога, завдаючи шкоди вогнем кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Immolate" },
    [15530] = { "Крижана стріла", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frostbolt" },
    [15531] = { "Крижаний спалах", "Вражає ворогів неподалік кригою, знерухомлюючи їх на {1} с.#immobilizing them for up to {1} sec", "Знерухомлено", en="Frost Nova" },
    [15532] = { "Крижаний спалах", "Вражає ворогів неподалік кригою, знерухомлюючи їх на {1} с.#immobilizing them for up to {1} sec", "Знерухомлено", en="Frost Nova" },
    [15534] = { "Поліморфія", "Перетворює ворога на вівцю, змушуючи його блукати до {1} с. Вівця не здатна атакувати та вимовляти закляття, але дуже швидко відновлює здоров'я. Будь-яка шкода поверне ціль до нормального стану. Одночасно лише одна ціль може бути під ефектом \"Поліморфії\". Діє лише на звірів, драконів, велетнів, гуманоїдів і звіряток.#up to {1} sec", "Не може атакувати та вимовляти закляття.\nШвидкість регенерації здоров'я збільшено.", en="Polymorph" },
    [15535] = { "Огортання вітрами", "Оточує ворога циклоном на {1} с. Якщо ціль отримає шкоду, вона звільниться з полону вітрів.#up to {1} sec", "Приголомшено.", en="Enveloping Winds" },
    [15536] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [15548] = { "Громовий удар", "Завдає від {1} до {2} шкоди від природи навколишнім ворогам, збільшуючи інтервал між атаками на {3}% та зменшуючи швидкість руху на {4}% протягом {5} с.#Inflicts {1} to {2} Nature#attacks by {3}%#movement by {4}% for {5} sec", "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Thunderclap" },
    [15550] = { "Тупіт", "Завдає фізичної шкоди навколишнім ворогам.", en="Trample" },
    [15570] = { "Жертовний вогонь", "Обпалює ворога, завдаючи шкоди вогнем кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Immolate" },
    [15571] = { "Запаморочення", nil, "Запаморочення.", en="Dazed" },
    [15572] = { "Розкол броні", "Розколює броню ворога, зменшуючи її на {1} за кожен ефект \"Розколу броні\". Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено.", en="Sunder Armor" },
    [15579] = { "Розсічення", "Завдає звичайної шкоди плюс {1} ворогу та його союзникам неподалік, вражаючи до {2} цілей.#plus {1} to#up to {2} target", en="Cleave" },
    [15583] = { "Розрив", ref=11977, en="Rupture" },
    [15584] = { "Розсічення", "Завдає звичайної шкоди плюс {1} ворогу та його союзникам неподалік, вражаючи до {2} цілей.#plus {1} to#up to {2} target", en="Cleave" },
    [15588] = { "Громовий удар", "Завдає від {1} до {2} шкоди від природи навколишнім ворогам, збільшуючи інтервал між атаками на {3}% та зменшуючи швидкість руху на {4}% протягом {5} с.#Inflicts {1} to {2} Nature#attacks by {3}%#movement by {4}% for {5} sec", "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Thunderclap" },
    [15590] = { "Кулачна зброя", en="Fist Weapons" },
    [15592] = { "Вогняна стріла", "Завдає цілі від {1} до {2} шкоди вогнем.#for {1} to {2} Fire", en="Firebolt" },
    [15593] = { "Бойовий тупіт", "Завдає звичайної шкоди плюс {1} навколишнім ворогам, відкидаючи їх та приголомшуючи на {2} с.#plus {1} to#for {2} sec", "Приголомшено.", en="War Stomp" },
    [15594] = { "Сила волі", "З ймовірністю {1}% після отримання удару ви отримуватиме на {2} менше шкоди в ближньому бою протягом {3} секунд.#a {1}% chance#taken by {2} for {3} sec", en="Force of Will" },
    [15595] = { "Сила волі", nil, "Отриману шкоду в ближньому бою зменшено на {1}.#by {1}", en="Force of Will" },
    [15600] = { "Рука правосуддя", "З ймовірністю 2% ви виконаєте 1 додаткову атаку після завдання удару в ближньому бою.", en="Hand of Justice" },
    [15602] = { "Меч лорда-генерала", "Збільшує силу атаки на {1} протягом {2} с.#power by {1} for {2} sec", "Силу атаки збільшено на {1}.#increased by {1}", en="Lord General's Sword" },
    [15604] = { "Друге дихання", "Відновлює {1} мани щосекунди протягом {2} секунд.#Restores {1} mana#for {2} sec", "Відновлює {1} мани щосекунди.#Restores {1} mana", en="Second Wind" },
    [15609] = { "Сітка з гачками", "Знерухомлює навколишніх ворогів на {1} с та завдає фізичної шкоди.#for {1} sec", "Знерухомлено.", en="Hooked Net" },
    [15616] = { "Вогняний шок", "Обпалює ворога, завдаючи шкоди вогнем кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Flame Shock" },
    [15618] = { "Стрімкий копняк", "Завдає ворогу {1} шкоди та приголомшує його на {2} с.#Inflicts {1} damage#for {2} sec", "Приголомшено.", en="Snap Kick" },
    [15621] = { "Тріщина в черепі", ref=3242, en="Skull Crack" },
    [15629] = { "Відволікаючий постріл", "Відволікає ціль, спричиняє загрозу. Дієвіше за \"Відволікаючий постріл\" (Ранг {1}).#(Rank {1})", en="Distracting Shot" },
    [15630] = { "Відволікаючий постріл", "Відволікає ціль, спричиняє загрозу. Дієвіше за \"Відволікаючий постріл\" (Ранг {1}).#(Rank {1})", en="Distracting Shot" },
    [15631] = { "Відволікаючий постріл", "Відволікає ціль, спричиняє загрозу. Дієвіше за \"Відволікаючий постріл\" (Ранг {1}).#(Rank {1})", en="Distracting Shot" },
    [15632] = { "Відволікаючий постріл", "Відволікає ціль, спричиняє загрозу. Дієвіше за \"Відволікаючий постріл\" (Ранг {1}).#(Rank {1})", en="Distracting Shot" },
    [15646] = { "Шквал знань", "Зменшує витрати мани на всі закляття на {1} протягом {2} с.#of all spells by {1} for {2} sec", "Витрати мани зменшено.", en="Burst of Knowledge" },
    [15654] = { "Слово тіні: Біль", "Вимовляє слово темряви, що завдає ворогу шкоди тінню кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від тіні кожні {1} с.#every {1} sec", en="Shadow Word: Pain" },
    [15655] = { "Трощення щитом", "Завдає ворогу {1} шкоди та приголомшує його на {2} с.#Inflicts {1} damage#for {2} sec", "Приголомшено.", en="Shield Slam" },
    [15656] = { "Отруйний удар", "Завдає ворогу {1} шкоди від природи кожні {2} с, збільшує інтервал між його атаками на {3}% і сповільнює його рух на на {4}% протягом {5} с.#Inflicts {1} Nature#every {2} sec#attacks by {3}%#movement by {4}% for {5} sec", "{1} шкоди від природи кожні {2} с.\nІнтервал між атаками збільшено на {3}%.\nШвидкість руху зменшено на {4}%.#{1} Nature#every {2} sec#attacks increased by {3}%#speed reduced by {4}%", en="Poisonous Stab" },
    [15661] = { "Жертовний вогонь", "Обпалює ворога, завдаючи шкоди вогнем кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Immolate" },
    [15662] = { "Вогняна куля", "Кидає вогняну кулю, що завдає {1} шкоди від вогню і додатково {2} шкоди протягом {3} с.#causes {1} Fire#additional {2} damage over {3} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire damage every {2} sec", en="Fireball" },
    [15664] = { "Плювок отрути", "Плює у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Venom Spit" },
    [15665] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [15694] = { "Збільшення навички одноручних булав", "Збільшує навичку володіння булавами на {1}.#Maces +{1}", en="Increased 1H Mace" },
    [15700] = { "Плід кнутокореня", ref=439, en="Whipper Root Tuber" },
    [15701] = { "Подих нічного дракона", ref=2370, en="Night Dragon's Breath" },
    [15708] = { "Смертельний удар", "Завдає {1}% шкоди від зброї та ранить ціль, зменшуючи ефективність будь-якого зцілення на {2}% протягом {3} с.#Inflicts {1}% weapon#healing by {2}% for {3} sec", "Ефективність зцілення зменшено на {1}%.#reduced by {1}%", en="Mortal Strike" },
    [15712] = { "Бумеранг Лінкена", "Кинути магічний бумеранг, який завдає [{1}#dealing {1} damage][від {1} до {2}#dealing {1} to {2} damage] шкоди і може приголомшити чи роззброїти ціль.", en="Linken's Boomerang" },
    [15716] = { "Несамовитість", "Збільшує швидкість атаки заклинача на {1}% та збільшує фізичну шкоду на {2} протягом {3} хв.#speed by {1}%#deals by {2} for {3} min", "Фізичну шкоду збільшено на {1}.\nШвидкість атаки збільшено на {2}%.#dealt is increased by {1}#speed increased by {2}%", en="Enrage" },
    [15717] = { "Збільшення навички кинджалів", "Збільшує навичку володіння кинджалами на {1}.#Daggers +{1}", en="Increased Dagger" },
    [15727] = { "Деморалізуючий рев", "Зменшує силу атаки ближнього бою навколишніх ворогів на {1} протягом {2} с.#enemies by {1} for {2} sec", "Силу атаки ближнього бою зменшено на {1}.#by {1}", en="Demoralizing Roar" },
    [15728] = { "Чумна хмара", "Зменшує силу на {1}, спритність на {2} та інтелект на {3} всім ворогам в межах дії протягом {4} хв.#Strength by {1}#Agility by {2}#Intellect by {3}#for {4} min", "Силу зменшено на {1}.\nСпритність зменшено на {2}.\nІнтелект зменшено на {3}.#Strength reduced by {1}#Agility reduced by {2}#Strength reduced by {3}", en="Plague Cloud" },
    [15730] = { "Прокляття загоєння", nil, "Може зцілити ворога при атаці.", en="Curse of Mending" },
    [15732] = { "Жертовний вогонь", "Обпалює ворога, завдаючи шкоди вогнем кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Immolate" },
    [15744] = { "Вибухова хвиля", "Вивільняє полум'яну хвилю, яка завдає шкоди вогнем навколишнім ворогам та зменшує їх швидкість руху на {1} с.#speed for {1} sec", "Швидкість руху зменшено.", en="Blast Wave" },
