    [16084] = { "Строкатий червоний раптор", "Викликає та відпускає верхового раптора. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Mottled Red Raptor" },
    [16089] = { "Стихійна лють", "Збільшує додаткову шкоду від критичних ударів тотемів обпалення, магми та вогненного спалаху, а також заклять вогню, криги та природи на {1}%.#by {1}%", en="Elemental Fury" },
    [16094] = { "Крижаний подих", "Завдає шкоди від криги ворогам у конусі перед заклиначем, викрадаючи у них ману і зменшуючи швидкість руху на {1} с.#speed for {1} sec", "Швидкість руху зменшено.", en="Frost Breath" },
    [16095] = { "Жахливий розрив", ref=11977, en="Vicious Rend" },
    [16096] = { "Грізний рев", ref=6524, en="Cowering Roar" },
    [16097] = { "Пристріт", "Перетворює навколишніх ворогів на жаб, позбавляючи їх можливості атакувати та застосовувати заклинання протягом {1} с.#for {1} sec", "Зурочено.", en="Hex" },
    [16098] = { "Прокляття крові", "Збільшує отриману навколишніми ворогами фізичну шкоду на {1} протягом {2} хв.#by {1} for {2} min", "Отриману фізичну шкоду збільшено на {1}.#by {1}", en="Curse of Blood" },
    [16099] = { "Крижаний подих", "Завдає шкоди від криги ворогам у конусі перед заклиначем, викрадаючи у них ману і зменшуючи швидкість руху на {1} с.#speed for {1} sec", "Швидкість руху зменшено.", en="Frost Breath" },
    [16101] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [16104] = { "Кристалізація", ref=5106, en="Crystallize" },
