    [17158] = { "Плювок отрути", "Плює у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Venom Spit" },
    [17165] = { "Муки розуму", "Завдає ворогу шкоди від тіні та зменшує його швидкість руху протягом {1} с.#for {1} sec", "Завдає шкоди від тіні протягом {1} с.\nШвидкість руху зменшено.#over {1} sec", en="Mind Flay" },
    [17172] = { "Пристріт", "Перетворює ворога на жабу, позбавляючи його можливості атакувати та застосовувати заклинання протягом {1} с.#for {1} sec", "Зурочено.", en="Hex" },
    [17173] = { "Висмоктування життя", "Висмоктує {1} здоров'я з ворога протягом {2} с, передаючи його заклиначу.#Drains {1} health#over {2} sec", "Висмоктування {1} здоров'я протягом {2} с.#{1} health#over {2} sec", en="Drain Life" },
    [17174] = { "Запаморочливий постріл", "Паморочить ціль, зменшуючи її швидкість руху на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Concussive Shot" },
    [17183] = { "Отрута", "Отруює ціль, завдаючи {1} шкоди від природи кожні {2} с протягом {3} с.#for {1} Nature damage every {2} sec for {3} sec", "{1} шкоди від природи кожні {2} с.#{1} Nature damage#every {2} sec", en="Poison" },
    [17187] = { "Трансмутація: Арканіт", "Перетворює злиток торію та арканічний кристал на арканіт.", en="Transmute: Arcanite" },
    [17196] = { "Вербовий молот", "Зменшує всі характеристики на {1} і завдає {2} шкоди від природи кожні {3} секунди всім ворогам в радіусі {4} м протягом {5} секунд.#stats by {1} and deals {2} Nature#every {3} sec#an {4} yard radius#for {5} sec", "Всі характеристики зменшено на {1}. Періодична шкода від природи.#by {1} and", en="Seeping Willow" },
    [17197] = { "Слиз черва", "Отруює навколишніх ворогів, завдаючи від {1} до {2} шкоди та додатково від {3} до {4} шкоди від природи кожні {5} с протягом {6} с.#for {1} to {2} damage#additional {3} to {4} Nature#every {5} sec#for {6} sec", "Завдає від {1} до {2} шкоди від природи кожні {3} с.#{1} to {2} Nature#every {3} sec", en="Maggot Goo" },
    [17203] = { "Залп вогняних куль", "Завдає шкоди від вогню навколишнім ворогам.", en="Fireball Volley" },
    [17207] = { "Вихор", "Атакує навколишніх ворогів сталевим вихром протягом {1} с, завдаючи звичайної шкоди плюс {2}.#lasts {1} sec#plus {2}", "Атакує навколишніх ворогів, завдаючи звичайної шкоди плюс {1}.#plus {1}", en="Whirlwind" },
    [17227] = { "Прокляття слабкості", "Зменшує завдану ціллю фізичну шкоду на {1} протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", "Завдану фізичну шкоду зменшено на {1}.#by {1}", en="Curse of Weakness" },
    [17229] = { "Кригозуб Зимоключа", "Викликає та відпускає верхового кригозуба Зимоключа. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Winterspring Frostsaber" },
    [17230] = { "Заражена рана", "Збільшує отриману ворогом фізичну шкоду на {1} протягом {2} хв.#by {1} for {2} min", "Отриману фізичну шкоду збільшено на {1}.#by {1}", en="Infected Wound" },
    [17232] = { "Аура відданості", ref=8258, en="Devotion Aura" },
    [17238] = { "Висмоктування життя", "Висмоктує {1} здоров'я з ворога протягом {2} с, передаючи його заклиначу.#Drains {1} health#over {2} sec", "Висмоктування {1} здоров'я протягом {2} с.#{1} health#over {2} sec", en="Drain Life" },
    [17244] = { "Одержимість", "Бере під контроль ворога-гуманоїда до {1} рівня на {2} хв і збільшує його максимальний запас здоров'я на {3}.#level {1} for {2} min#health by {3}%", "Причаровано.\nМаксимальний запас здоров'я збільшено на {1}.#increased by {1}", en="Possess" },
    [17246] = { "Одержимість", nil, "Причаровано.\nЗавдає на {1}% більше шкоди.#by {1}%", en="Possessed" },
    [17250] = { "Одержимість", en="Possess" },
    [17252] = { "Печатка повелителя драконів", "Вас оточує щит мани, що поглинає {1} шкоди. Поки щит тримається, ви відновлюєте {2} мани кожні {3} с протягом {4} хв.#absorbing {1} damage#regeneration by {2} every {3} sec for {4} min", "Поглинає шкоду та відновлює {1} мани кожні {2} с.#regeneration by {1} every {2} sec", en="Mark of the Dragon Lord" },
