    [17495] = { "Щит відплати", "Завдає [{1}#Deals {1} damage][від {1} до {2}#Deals {1} to {2} damage] шкоди щоразу, коли ви блокуєте атаку.", en="Crest of Retribution" },
    [17496] = { "Щит відплати", en="Crest of Retribution" },
