    [17538] = { "Еліксир мангусти", "Збільшує спритність на {1} та ймовірність завдання критичного удару на {2}% протягом {3} год.#Agility by {1}#by {2}% for {3} h", "Спритність збільшено на {1}, ймовірність завдання критичного удару збільшено на {2}%.#Agility increased by {1}#chance increases by {2}%", en="Elixir of the Mongoose" },
    [17539] = { "Великий арканічний еліксир", "Збільшує шкоду заклинань на {1} протягом {2} год.#by up to {1} for {2} h", "Магічну шкоду заклинань та здібностей збільшено на {1}.#by up to {1}", en="Greater Arcane Elixir" },
