    [17620] = { "Висмоктування життя", "Висмоктує {1} здоров'я з ворога протягом {2} с, передаючи його заклиначу.#Drains {1} health#over {2} sec", "Висмоктування {1} здоров'я протягом {2} с.#{1} health#over {2} sec", en="Drain Life" },
    [17624] = { "Скам'яніння", "Ви перетворюєтеся на камінь, що захищає вас від усіх фізичних атак і заклинань на 1 хв, але протягом цього часу ви не можете атакувати, рухатися або промовляти заклинання. Одночасно ви можете перебувати під дією лише одного настою.", "Невразливість до всіх атак та заклять. Не може атакувати, рухатися та застосовувати закляття.", en="Petrification" },
    [17625] = { "Нечестива аура", "Збільшує швидкість руху та швидкість відновлення здоров'я.", "Швидкість руху та швидкість відновлення здоров'я збільшено.", en="Unholy Aura" },
    [17626] = { "Настій титанів", "Збільшує максимальний запас здоров'я на {1} протягом {2} год. Одночасно ви можете перебувати під дією лише одного настою. Цей ефект зберігається після смерті.#health by {1} for {2} h", "Запас здоров'я збільшено на {1}.#increased by {1}", en="Flask of the Titans" },
    [17627] = { "Дистильована мудрість", "Збільшує максимальний запас мани на {1} протягом {2} год. Одночасно ви можете перебувати під дією лише одного настою. Цей ефект зберігається після смерті.#mana by {1} for {2} h", "Запас мани збільшено на {1}.#increased by {1}", en="Distilled Wisdom" },
    [17628] = { "Велика сила", "Збільшує шкоду магічних заклинань і ефектів на {1} протягом {2} год. Одночасно ви можете перебувати під дією лише одного настою. Ефект зберігається після смерті.#by up to {1} for {2} h", "Шкоду заклять збільшено на {1}.#increased by up to {1}", en="Supreme Power" },
    [17629] = { "Хроматичний опір", "Збільшує опір всім школам магії на {1} протягом {2} год. Одночасно ви можете перебувати під дією лише одного настою. Цей ефект зберігається після смерті та поєднується з усіма іншими заклинаннями і предметами що збільшують опір.#magic by {1} for {2} h", "Опір всім школам магії збільшено на {1}.#increased by {1}", en="Chromatic Resistance" },
    [17639] = { "Плач банші", "Зменшує ймовірність завдання удару ціллю на {1}% протягом {2} с.#chance to hit by {1}% for {2} sec", "Ймовірність завдання удару зменшено на {1}%.#by {1}%", en="Wail of the Banshee" },
    [17668] = { "Блискавичники Рамштайна", "Приборкати силу блискавки, щоб завдати всім навколишнім ворогам {1} шкоди від природи.#around you for {1} Nature", en="Ramstein's Lightning Bolts" },
    [17670] = { "Жетон Сріблястого Світанку", nil, "Дозволяє отримувати камені Скари для Сріблястого Світанку.", en="Argent Dawn Commission" },
    [17685] = { "Розсічення", "Завдає звичайної шкоди плюс {1} ворогу та його союзникам неподалік, вражаючи до {2} цілей.#plus {1} to#up to {2} target", en="Cleave" },
    [17695] = { "Аура осквернення", "Оточує заклинача аурою, що періодично зменшує опір тіні навколишніх ворогів на {1}.#enemies by {1}", "Періодично зменшує опір тіні навколишніх ворогів.", en="Defiling Aura" },
