    [17851] = { "Поглинання тіней", "Пустотник поглинає тіні поблизу, щоб укріпити своє втілення, відновлюючи {1} здоров'я протягом {2} с. Не можна використовувати в бою.#{1} health over {2} sec", "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Consume Shadows" },
    [17852] = { "Поглинання тіней", "Пустотник поглинає тіні поблизу, щоб укріпити своє втілення, відновлюючи {1} здоров'я протягом {2} с. Не можна використовувати в бою.#{1} health over {2} sec", "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Consume Shadows" },
    [17853] = { "Поглинання тіней", "Пустотник поглинає тіні поблизу, щоб укріпити своє втілення, відновлюючи {1} здоров'я протягом {2} с. Не можна використовувати в бою.#{1} health over {2} sec", "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Consume Shadows" },
    [17854] = { "Поглинання тіней", "Пустотник поглинає тіні поблизу, щоб укріпити своє втілення, відновлюючи {1} здоров'я протягом {2} с. Не можна використовувати в бою.#{1} health over {2} sec", "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Consume Shadows" },
    [17877] = { "Тіньовий опік", "Миттєво вражає ціль, завдаючи від {1} до {2} шкоди тінню. Якщо ціль помирає протягом {3} с після \"Тіньового опіку\" та приносить досвід або честь, заклинач отримує уламок душі.#for {1} to {2}#within {3} sec", en="Shadowburn" },
    [17883] = { "Жертовний вогонь", "Обпалює ворога, завдаючи шкоди вогнем кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Immolate" },
    [17917] = { "Досяжність руйнації", "Збільшує дальність дії заклять спеціалізації \"Руйнація\" на {1}%.#by {1}%", en="Destructive Reach" },
    [17919] = { "Палючий біль", "Викликає у ворожої цілі палючий біль, завдаючи від {1} до {2} шкоди вогнем. Спричиняє високий рівень загрози.#causing {1} to {2}", en="Searing Pain" },
    [17920] = { "Палючий біль", "Викликає у ворожої цілі палючий біль, завдаючи від {1} до {2} шкоди вогнем. Спричиняє високий рівень загрози.#causing {1} to {2}", en="Searing Pain" },
    [17921] = { "Палючий біль", "Викликає у ворожої цілі палючий біль, завдаючи від {1} до {2} шкоди вогнем. Спричиняє високий рівень загрози.#causing {1} to {2}", en="Searing Pain" },
    [17922] = { "Палючий біль", "Викликає у ворожої цілі палючий біль, завдаючи від {1} до {2} шкоди вогнем. Спричиняє високий рівень загрози.#causing {1} to {2}", en="Searing Pain" },
    [17923] = { "Палючий біль", "Викликає у ворожої цілі палючий біль, завдаючи від {1} до {2} шкоди вогнем. Спричиняє високий рівень загрози.#causing {1} to {2}", en="Searing Pain" },
    [17924] = { "Випалення душі", "Обпалює душу ворога, завдаючи від {1} до {2} шкоди вогнем.#causing {1} to {2}", en="Soul Fire" },
    [17925] = { "Виток смерті", "Примушує ворожу ціль бігти від жаху протягом {1} с та завдає їй {2} шкоди тінню. Заклинач відновлює здоров'я в обсязі {3}% від завданої шкоди.#for {1} sec#causes {2}#gains {3}", "Нажахано.", en="Death Coil" },
    [17926] = { "Виток смерті", "Примушує ворожу ціль бігти від жаху протягом {1} с та завдає їй {2} шкоди тінню. Заклинач відновлює здоров'я в обсязі {3}% від завданої шкоди.#for {1} sec#causes {2}#gains {3}", "Нажахано.", en="Death Coil" },
    [17928] = { "Виття жаху", "Виття, що змушує {1} ворогів в межах {2} м втікати від жаху протягом {3} с. Шкода може перервати цей ефект.#causing {1} enemies#within {2} y#for {3} sec", "Втікає від жаху.", en="Howl of Terror" },
    [17941] = { "Тінетранс", nil, "Наступна \"Тіньова стріла\" буде миттєвою[, а наступне \"Тіньове розсічення\" завдасть на {1}% більше шкоди#Shadow Cleave deals {1}% increased].", en="Shadow Trance" },
    [17951] = { "Створення каменя вогню", "Створює камінь вогню, який можна взяти в неосновну руку. При цьому він зачаровує зброю в основній руці вогнем, внаслідок чого атаки зброєю можуть завдати від {1} до {2} додаткової шкоди вогнем. Окрім того, при спорядженні камінь вогню збільшує шкоду від заклять вогню на {3}.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {4} хв.#deal {1} to {2}#spells by {3}#than {4} min", en="Create Firestone" },
    [17954] = { "Палюча буря", "Збільшує шкоду ваших заклять вогню на {1}%.#by {1}%", en="Emberstorm" },
    [17959] = { "Руїна", "Збільшує додаткову шкоду від критичних ударів заклять спеціалізації \"Руйнація\" на {1}%.#by {1}%", en="Ruin" },
    [17961] = { "Ілюзія Багряного Походу", "Замасковано під члена Багряного Походу.", "Замасковано під члена Багряного Походу.", en="Scarlet Illusion" },
    [17962] = { "Розпалення", "Розпалює ціль, яка вже перебуває під дією ефекту закляття \"Жертовний вогонь\", та завдає від {1} до {2} шкоди вогнем, поглинаючи ефект \"Жертовного вогню\".#dealing {1} to {2} Fire", en="Conflagrate" },
    [17963] = { "Розсікаючий розкол", "Розсікає броню ворога та його найближчих созників, вражаючи до {1} цілей. Броня цілі зменшується на {2} за кожен ефект. Може накопичуватись до {3} разів. Триває {4} с.#up to {1} targets#reduced by {2} per#up to {3} times#Lasts {4} sec", "Броню зменшено.", en="Sundering Cleave" },
    [18061] = { "Збільшення навички одноручних мечів", "Збільшує навичку володіння мечами на {1}.#Swords +{1}", en="Increased 1H Sword" },
    [18070] = { "Кислота землебура", "Роз'їдає броню ворога, зменшуючи її на {1} за кожен ефект. Може накопичуватись до {2} разів. Триває {3} с.#by {1} per application#up to {2} times#Lasts {3} sec", "Броню зменшено.", en="Earthborer Acid" },
    [18071] = { "Збагачене маною печиво", ref=2639, en="Enriched Manna Biscuit" },
