    [18075] = { "Розрив", "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rend" },
    [18077] = { "Отрута", "Отруює ціль, завдаючи {1} шкоди від природи кожні {2} с протягом {3} с.#for {1} Nature damage every {2} sec for {3} sec", "{1} шкоди від природи кожні {2} с.#{1} Nature damage#every {2} sec", en="Poison" },
    [18078] = { "Розрив", "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rend" },
    [18081] = { "Блискавка", "Завдає цілі [{1}#for {1} Nature][від {1} до {2}#for {1} to {2} Nature] шкоди від природи.", en="Lightning Bolt" },
    [18082] = { "Вогняна куля", "Кидає вогняну кулю, яка завдає від {1} до {2} шкоди від вогню і додатково {3} шкоди від вогню протягом {4} с.#causes {1} to {2} Fire#additional {3} damage over {4} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire#every {2} sec", en="Fireball" },
