    [18218] = { "Похмура досяжність", "Збільшує дальність дії ваших заклять спеціалізації \"Химородь\" на {1}%.#by {1}%", en="Grim Reach" },
    [18223] = { "Прокляття виснаження", "Зменшує швидкість руху цілі на {1}% протягом {2} с. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1}% for {2} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Curse of Exhaustion" },
    [18229] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [18230] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [18231] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [18232] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [18233] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [18234] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [18248] = { "Риболовля", "Візьміть до рук вудку і знайдіть водойму, в якій можна рибалити. Коли почуєте плескіт — клацніть на поплавок правою кнопкою миші, щоб витягнути впійману рибу. Чим вище ваша навичка риболовлі, тим більше шансів упіймати рибу у водоймах зон вищого рівня.", en="Fishing" },
    [18260] = { "Кулінарія", "Дозволяє готувати неймовірні страви та розвивати навичку до {1} рівня.#skill of {1}", en="Cooking" },
    [18264] = { "Тростина магістра", "Збільшує інтелект учасників групи в межах {2} м на {1}.#Gives {1} additional#within {2} yard", "Інтелект збільшено на {1}.#increased by {1}", en="Headmaster's Charge" },
    [18265] = { "Витягування життя", "Передає {1} здоров'я від цілі до заклинача кожні {2} с. Триває {3} с.#{1} health#every {2} sec#Lasts {3} sec", "Висмоктує {1} здоров'я кожні {2} с, передаючи його заклиначеві.#Drains {1} health#every {2} sec", en="Siphon Life" },
    [18266] = { "Прокляття агонії", "Проклинає ціль агонією, завдаючи шкоди тінню кожні {1} с протягом {2} с. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#every {1} sec#over {2} sec", "Завдає шкоди від тіні кожні {1} с.#every {1} sec", en="Curse of Agony" },
    [18267] = { "Прокляття слабкості", "Зменшує завдану ціллю фізичну шкоду на {1} протягом {2} с. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} sec", "Завдану фізичну шкоду зменшено на {1}.#by {1}", en="Curse of Weakness" },
    [18270] = { "Темна чума", "Завдає ворогу {1} шкоди від природи та додатково {2} шкоди кожні {3} с протягом {4} хв.#Inflicts {1} Nature#additional {2} damage#every {3} sec#for {4} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Dark Plague" },
    [18271] = { "Тіньова майстерність", "Збільшує шкоду або обсяг висмоктаного життя вашими закляттями тіні на {1}%.#by {1}%", en="Shadow Mastery" },
    [18276] = { "Крижаний вибух", "Завдає цілі [{1}#for {1} Frost][від {1} до {2}#for {1} to {2} Frost] шкоди від криги.", en="Frost Blast" },
    [18278] = { "Знемовлення", "Знемовлює ворога, запобігаючи вимові заклять на {1} с.#spells for {1} sec", "Не може вимовляти закляття.", en="Silence" },
    [18288] = { "Посилення прокляття", "Посилює ефект наступного \"Прокляття слабкості\" або \"Прокляття агонії\" на {1}%, а \"Прокляття виснаження\" на {2}%. Триває {3} с.#Agony by {1}%#Exhaustion by {2}%#Lasts {3} sec", "Посилює ефект наступного \"Прокляття слабкості\" або \"Прокляття агонії\" на {1}%, а \"Прокляття виснаження\" на {2}%.#Agony by {1}%#Exhaustion by {2}%", en="Amplify Curse" },
    [18289] = { "Повзуча пліснява", "Заражає ціль, завдаючи {1} шкоди від природи кожні {2} с протягом {3} с.#for {1} Nature#every {2} sec for {3} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Creeping Mold" },
    [18310] = { "Покращене прокляття виснаження", "Посилює ефект сповільнення від вашого \"Прокляття виснаження\" на {1}%.#by {1}%", en="Improved Curse of Exhaustion" },
