    [18381] = { "Каліцтво", "Зменшує силу атаки цілі на {1} протягом {2} с.#attack power by {1} for {2} sec", "Силу атаки зменшено.", en="Cripple" },
    [18382] = { "Збільшення шансу критичного закляття", "Збільшує ваш шанс завдання критичного удару заклинаннями на {1}%.#critical strike with spells by {1}%", en="Increased Critical Spell" },
    [18384] = { "Збільшення шансу критичного закляття", "Збільшує ваш шанс завдання критичного удару заклинаннями на {1}%.#critical strike with spells by {1}%", en="Increased Critical Spell" },
    [18385] = { "Поповнення мани", ref=436, en="Replenish Mana" },
    [18386] = { "Зцілення вихованця", "Зцілює вашому прислужнику [{1}#pet for {1}.][від {1} до {2}#pet for {1} to {2}.] здоров'я.", en="Heal Pet" },
    [18388] = { "Швидке Розтанення", "Зменшує час відновлення здібності \"Розтанення\" на {1} с.#Fade ability by {1} sec", en="Quick Fade" },
    [18398] = { "Крижаний вибух", "Завдає цілі [{1}#for {1} Frost][від {1} до {2}#for {1} to {2} Frost] шкоди від криги.", en="Frost Blast" },
    [18400] = { "Флейта запального вогню", "Змушує гравців неподалік танцювати.", "Танцює під музику.", en="Piccolo of the Flaming Fire" },
    [18427] = { "Агресивність", "Збільшує шкоду здібностей \"Підступний удар\" та \"Потрошіння\" на {1}%.#by {1}%", en="Aggression" },
    [18435] = { "Полум'яне дихання", "Завдає від {1} до {2} шкоди вогнем ворогам у конусі перед заклиначем.#Inflicts {1} to {2} Fire", en="Flame Breath" },
    [18462] = { "Арканічна медитація", "Дозволяє {1}% вашого відновлення мани продовжуватися під час вимови заклять.#Allows {1}%", en="Arcane Meditation" },
    [18469] = { "Протизакляття - Знемовлення", nil, "Знемовлено.", en="Counterspell - Silenced" },
    [18499] = { "Лють берсерка", "Впадаючи в лють берсерка, воїн стає невразливим до ефектів страху та недієздатності і генерує додаткову лють при отриманні шкоди. Триває {1} с.#Lasts {1} sec", "Невразливість до ефектів страху та недієздатності. Генерує додаткову лють при отриманні шкоди.", en="Berserker Rage" },
    [18500] = { "Помах крил", "Завдає від {1} до {2} шкоди ворогам в конусі перед заклиначем, відкидаючи їх.#Inflicts {1} to {2} damage", en="Wing Buffet" },
    [18502] = { "Прокляття Гаккара", "Висмоктує у ворога {1} мани на користь заклинача кожні {2} с протягом {3} хв.#Drains {1} mana#every {2} sec#over {3} min", "Висмоктує {1} мани кожні {2} с.#{1} mana#every {2} sec", en="Curse of Hakkar" },
    [18503] = { "Пристріт", "Перетворює ворога на курку, позбавляючи його можливості атакувати та застосовувати заклинання протягом {1} с.#for {1} sec", "Зурочено.", en="Hex" },
    [18530] = { "Божественна лють", "Зменшує час вимови заклять \"Кара\", \"Священний вогонь\", \"Зцілення\" та \"Велике зцілення\" на {1} с.#by {1} sec", en="Divine Fury" },
    [18540] = { "Ритуал приречення", "Починає ритуал, що приносить у жертву випадково обраного учасника з метою виклику вартового приречення. Вартового необхідно одразу поневолити, інакше він атакуватиме учасників ритуалу. Для завершення ритуалу потрібна допомога 4 учасників групи. Щоб узяти участь, гравці повинні натиснути правою кнопкою миші на портал і не рухатися до завершення ритуалу.", en="Ritual of Doom" },
    [18543] = { "Полум'яний батіг", ref=9034, en="Flame Lash" },
    [18544] = { "Сила волі", "Збільшує шкоду ваших заклять на {1}% та ймовірність критичного удару ваших бойових заклять на {2}%.#damage by {1}%#spells by {2}%", en="Force of Will" },
    [18547] = { "Сила волі", "Збільшує шкоду ваших заклять на {1}% та ймовірність критичного удару ваших бойових заклять на {2}%.#damage by {1}%#spells by {2}%", en="Force of Will" },
    [18548] = { "Сила волі", "Збільшує шкоду ваших заклять на {1}% та ймовірність критичного удару ваших бойових заклять на {2}%.#damage by {1}%#spells by {2}%", en="Force of Will" },
    [18549] = { "Сила волі", "Збільшує шкоду ваших заклять на {1}% та ймовірність критичного удару ваших бойових заклять на {2}%.#damage by {1}%#spells by {2}%", en="Force of Will" },
    [18550] = { "Сила волі", "Збільшує шкоду ваших заклять на {1}% та ймовірність критичного удару ваших бойових заклять на {2}%.#damage by {1}%#spells by {2}%", en="Force of Will" },
    [18551] = { "Ментальна сила", "Збільшує ваш максимальний запас мани на {1}%.#by {1}%", en="Mental Strength" },
    [18557] = { "Висмоктування життя", "Висмоктує {1} здоров'я з ворога протягом {2} с, передаючи його заклиначу.#Drains {1} health#over {2} sec", "Висмоктування {1} здоров'я протягом {2} с.#{1} health#over {2} sec", en="Drain Life" },
    [18562] = { "Негайне відновлення", "[Поглинає ефект \"Омолодження\" чи \"Розростання\" з дружньої цілі#Consumes a Rejuvenation or Regrowth effect][Миттєво зцілює ціль, що знаходиться під ефектом \"Омолодження\" чи \"Розростання\"#with an active Rejuvenation or Regrowth effect], відновлюючи здоров'я в обсязі, що дорівнює зціленню від ефекту \"Омолодження\" протягом {1} с або \"Розростання\" протягом {2} с.#equal to {1} sec#or {2} sec", en="Swiftmend" },
    [18608] = { "Перша допомога", "Відновлює {1} здоров'я за {2} с.#Heals {1} damage over {2} sec", "Відновлення {1} здоров'я щосекунди.#Healing {1} damage", en="First Aid" },
    [18610] = { "Перша допомога", "Відновлює {1} здоров'я за {2} с.#Heals {1} damage over {2} sec", "Відновлення {1} здоров'я щосекунди.#Healing {1} damage", en="First Aid" },
    [18633] = { "Знесилююча хвороба", "Завдає {1} шкоди від тіні кожні {2} с протягом {3} с та зменшує силу на час дії хвороби.#Deals {1} Shadow damage every {2} sec for {3} sec", "Хворий і ослаблений.", en="Weakening Disease" },
    [18647] = { "Вигнання", "Виганяє ворожу ціль до іншого виміру, перешкоджаючи всім її діям, але при цьому робить її невразливою протягом {1} с. Одночасно лише одна ціль може бути вигнаною. Діє лише на демонів та елементалів.#for up to {1} sec", "Невразливість, але неможливо виконувати будь-які дії.", en="Banish" },
    [18652] = { "Висмоктування здоров'я", "Завдає {1} шкоди від тіні кожні {2} с протягом {3} с. Вся завдана шкода відновлює здоров'я заклиначу.#Deals {1} Shadow damage every {2} sec for {3} sec", "{1} шкоди від тіні кожні {2} с.#Deals {1} Shadow#every {2} sec", en="Siphon Health" },
    [18656] = { "Пошесть", "Оскверняє ціль, завдаючи {1} шкоди протягом {2} секунд.#causing {1} damage over {2} sec", "{1} шкоди від тіні кожні {2} с.#Inflicts {1} Shadow#every {2} sec", en="Corruption" },
    [18657] = { "Сплячка", "Змушує ворожу ціль спати протягом {1} с. Будь-яка шкода розбудить ціль. Одночасно лише одна ціль може бути змушена впасти в сплячку. Діє лише на звірів і драконів.#up to {1} sec", "Спить.", en="Hibernate" },
    [18658] = { "Сплячка", "Змушує ворожу ціль спати протягом {1} с. Будь-яка шкода розбудить ціль. Одночасно лише одна ціль може бути змушена впасти в сплячку. Діє лише на звірів і драконів.#up to {1} sec", "Спить.", en="Hibernate" },
    [18671] = { "Прокляття агонії", "Проклинає навколишніх ворогів агонією, завдаючи шкоди тінню кожні {1} с протягом {2} с. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#every {1} sec#for {2} sec", "Завдає шкоди від тіні кожні {1} с.#every {1} sec", en="Curse of Agony" },
    [18672] = { "Збільшення всіх опорів {1}#ncreased All Resist {1}", "Збільшує всі опори магії на {1}.#+{1} All Resistances", en="Increased All Resist 01" },
    [18692] = { "Покращений камінь здоров'я", "Збільшує обсяг здоров'я, що відновлюється вашим каменем здоров'я, на {1}%.#by {1}%", en="Improved Healthstone" },
    [18693] = { "Покращений камінь здоров'я", "Збільшує обсяг здоров'я, що відновлюється вашим каменем здоров'я, на {1}%.#by {1}%", en="Improved Healthstone" },
    [18694] = { "Покращений біс", "Посилює ефекти заклять \"Вогняна стріла\", \"Вогняний щит\" і \"Кривава угода\" вашого біса на {1}%.#by {1}%", en="Improved Imp" },
    [18697] = { "Демонічні обійми", "Збільшує вашу витривалість на {1}%, але зменшує ваш дух на {2}%.#Stamina by {1}%#Spirit by {2}%", en="Demonic Embrace" },
    [18702] = { "Прокляття темного магістра", ref=7289, en="Curse of the Darkmaster" },
    [18703] = { "Покращений канал здоров'я", "Збільшує обсяг здоров'я, переданого вашим закляттям \"Канал здоров'я\", на {1}%.#by {1}%", en="Improved Health Funnel" },
    [18705] = { "Покращений пустотник", "Збільшує ефективність заклять \"Муки\", \"Поглинання тіней\", \"Жертва\" та \"Страждання\" вашого пустотника на {1}%.#by {1}%", en="Improved Voidwalker" },
    [18708] = { "Домінування скверни", "Ваше наступне закляття виклику біса, пустотника, сукуба, інкуба або скверногончої вимовиться на {1} с швидше і витратить на {2}% менше мани.#time reduced by {1} sec#cost reduced by {2}%", "Час вимови виклику біса, пустотника, сукуба, інкуба та скверногончої зменшено на {1} с. Витрати мани зменшено на {2}%.#time reduced by {1} sec#cost reduced by {2}%", en="Fel Domination" },
    [18709] = { "Майстер-прикликач", "Зменшує час вимови на {1} с, а витрати мани на {2}% для заклять виклику біса, пустотника, сукуба, інкуба та скверногончої.#by {1} sec#cost by {2}%", en="Master Summoner" },
    [18754] = { "Покращений сайаад", "Посилює ефекти заклять \"Батіг болю\" та \"Заспокійливий поцілунок\" ваших сукуба й інкуба на {1}%, а тривалість їхніх заклять \"Зваблення\" та \"Мала невидимість\" на {2}%.#Kiss spells by {1}%#Invisibility spells by {2}%", en="Improved Sayaad" },
    [18757] = { "Майстер-чаклун", "Зменшує витрати мани та час вимови заклять створення каменів на {1}%.#by {1}%", en="Master Conjuror" },
    [18758] = { "Майстер-чаклун", "Зменшує витрати мани та час вимови заклять створення каменів на {1}%.#by {1}%", en="Master Conjuror" },
    [18763] = { "Заморозка", "Приголомшує ворога та завдає шкоди від криги кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Приголомшено.\nОтримання шкоди від криги кожні {1} с.#every {1} sec", en="Freeze" },
    [18764] = { "Грибне відновлення", "Відновлює {1} здоров'я кожні {2} с.#Restores {1} health every {2} sec", "Відновлює {1} здоров'я кожні {2} с.#Restores {1} health every {2} sec", en="Fungal Regrowth" },
    [18767] = { "Покращений камінь вогню", "Збільшує додаткову шкоду вогнем від каменів вогню та посилює їхній ефект збільшення шкоди від вогню на {1}%.#by {1}%", en="Improved Firestone" },
    [18768] = { "Покращений камінь вогню", "Збільшує додаткову шкоду вогнем від каменів вогню та посилює їхній ефект збільшення шкоди від вогню на {1}%.#by {1}%", en="Improved Firestone" },
    [18769] = { "Нечестива сила", "Збільшує шкоду атак ближнього бою пустотника, сукуба, інкуба та скверногончої на {1}%.#by {1}%", en="Unholy Power" },
    [18774] = { "Покращений камінь чарів", "Збільшує обсяг шкоди, що поглинає ваш камінь чарів, на {1}%.#by {1}%", en="Improved Spellstone" },
    [18775] = { "Покращений камінь чарів", "Збільшує обсяг шкоди, що поглинає ваш камінь чарів, на {1}%.#by {1}%", en="Improved Spellstone" },
    [18787] = { "Небесне благословення", "Збільшує силу атаки на {1} протягом {2} с.#ower by {1} for {2} sec", "Силу атаки збільшено.", en="Heaven's Blessing" },
    [18788] = { "Демонічна жертва", "Приносить у жертву вашого викликаного демона та надає вам ефект, що триває {1} хв. Ефект буде скасовано, якщо ви викличете будь-якого демона.\n\nБіс: Збільшує вашу шкоду вогнем на {2}%.\n\nПустотник: Відновлює {3}% вашого запасу здоров'я кожні {4} с.\n\nСукуб/інкуб: Збільшує вашу шкоду тінню на {5}%.\n\nСкверногонча: Відновлює {6}% вашого запасу мани кожні {7} с.#lasts {1} min#Fire damage by {2}#{3}% of total Health every {4} sec#Shadow damage by {5}#{6}% of total Mana every {7} sec", en="Demonic Sacrifice" },
    [18790] = { "Витривалість скверни", nil, "Відновлює {1}% вашого запасу здоров'я кожні {2} с.#Restores {1}%#every {2} sec", en="Fel Stamina" },
    [18792] = { "Енергія скверни", nil, "Відновлення {1}% мани кожні {2} с.#Restores {1}% of#every {2} sec", en="Fel Energy" },
    [18796] = { "Вогняна куля", "Кидає вогняну кулю, яка завдає від {1} до {2} шкоди від вогню і додатково {3} шкоди від вогню протягом {4} с.#causes {1} to {2} Fire#additional {3} damage over {4} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire#every {2} sec", en="Fireball" },
    [18799] = { "Заморозка", "З ймовірністю {1}% при отриманні удару в бою ви завдасте ворогу {2} шкоди від криги та заморозите його на {3} с.#has a {1}% chance of inflicting {2} Frost#and freezing them for {3} sec", en="Freeze" },
    [18803] = { "Зосередження", "Наступне закляття протягом {1} c буде вимовлено миттєво.#within {1} sec", "Наступне закляття буде вимовлено миттєво.", en="Focus" },
    [18805] = { "Рекомбобуляція", "Розвіює ефекти поліморфії з дружньої цілі. Також відновлює від {1} до {2} здоров'я та мани.#restores {1} to {2} health", en="Recombobulate" },
    [18807] = { "Муки розуму", "Вражає розум цілі енергією тіні, завдаючи {1} шкоди від тіні протягом {2} с та сповільнюючи її рух на {3}%.#causing {1} Shadow#over {2} sec#speed by {3}%", "Швидкість руху зменшено на {1}%.#by {1}%", en="Mind Flay" },
    [18809] = { "Вогняна брила", "Кидає величезний вогняний валун, що завдає від {1} до {2} шкоди вогнем і додатково {3} шкоди вогнем протягом {4} с.#causes {1} to {2}#additional {3}#over {4} sec", "{1} шкоди вогнем кожні {2} секунди.#{1} Fire damage every {2} sec", en="Pyroblast" },
    [18812] = { "Збиття з ніг", "Завдає ворогу від {1} до {2} шкоди, приголомшуючи його на {3} с.#Inflicts {1} to {2} damage#for {3} sec", "Приголомшено.", en="Knockdown" },
    [18815] = { "Висмоктування життя", "З шансом {1}% при отриманні удару в бою ви викрадете у ворога {2} здоров'я.#has a {1}% chance of stealing {2} life", en="Drain Life" },
    [18816] = { "Полум'яний удар", "З шансом {1}% при отриманні удару в бою ви завдасте всім ворогам навколо від {2} до {3} шкоди вогнем.#has a {1}% chance of dealing {2} to {3} Fire", en="Flamestrike" },
    [18817] = { "Висмоктування життя", "Викрадає {1} здоров'я у ворожої цілі.#Steals {1} life", en="Drain Life" },
    [18820] = { "Прозріння", "Зменшує витрати мани на наступне заклинання на {1} мани протягом {2} с.#cast within {1} sec by up to {2} mana", "Витрати мани зменшено.", en="Insight" },
    [18821] = { "Покращене поневолення демона", "Зменшує ефект сповільнення атаки та вимови від вашого закляття \"Поневолення демона\" на {1}% та зменшує ймовірність цілі протистояти йому на {2}%.#spell by {1}%#chance by {2}%", en="Improved Subjugate Demon" },
    [18822] = { "Покращене поневолення демона", "Зменшує ефект сповільнення атаки та вимови від вашого закляття \"Поневолення демона\" на {1}% та зменшує ймовірність цілі протистояти йому на {2}%.#spell by {1}%#chance by {2}%", en="Improved Subjugate Demon" },
    [18823] = { "Покращене поневолення демона", "Зменшує ефект сповільнення атаки та вимови від вашого закляття \"Поневолення демона\" на {1}% та зменшує ймовірність цілі протистояти йому на {2}%.#spell by {1}%#chance by {2}%", en="Improved Subjugate Demon" },
    [18824] = { "Покращене поневолення демона", "Зменшує ефект сповільнення атаки та вимови від вашого закляття \"Поневолення демона\" на {1}% та зменшує ймовірність цілі протистояти йому на {2}%.#spell by {1}%#chance by {2}%", en="Improved Subjugate Demon" },
    [18825] = { "Покращене поневолення демона", "Зменшує ефект сповільнення атаки та вимови від вашого закляття \"Поневолення демона\" на {1}% та зменшує ймовірність цілі протистояти йому на {2}%.#spell by {1}%#chance by {2}%", en="Improved Subjugate Demon" },
    [18826] = { "Жертва спасителя", "Збільшує броню на {1} протягом {2} с.#armor by {1} for {2} sec", "Броню збільшено.", en="Savior's Sacrifice" },
    [18828] = { "Кістяна броня", "З ймовірністю {1}% при отриманні удару в бою ви оточите себе кістяним захистом, що збільшує броню на {2} протягом {3} секунд.#a {1}% chance#armor by {2} for {3} sec", "Броню збільшено.", en="Bone Armor" },
    [18832] = { "Корінь лілії", "Відновлює від {1} до {2} мани та здоров'я.#Restores {1} to {2} mana", en="Lily Root" },
    [18833] = { "Вогняна стріла", "Завдає цілі від {1} до {2} шкоди вогнем.#for {1} to {2} Fire", en="Firebolt" },
    [18848] = { "Парирування", "Дає шанс парирувати ворожі атаки ближнього бою.", en="Parry" },
    [18867] = { "Тіньовий опік", "Миттєво вражає ціль, завдаючи від {1} до {2} шкоди тінню. Якщо ціль помирає протягом {3} с після \"Тіньового опіку\" та приносить досвід або честь, заклинач отримує уламок душі.#for {1} to {2}#within {3} sec", en="Shadowburn" },
    [18868] = { "Тіньовий опік", "Миттєво вражає ціль, завдаючи від {1} до {2} шкоди тінню. Якщо ціль помирає протягом {3} с після \"Тіньового опіку\" та приносить досвід або честь, заклинач отримує уламок душі.#for {1} to {2}#within {3} sec", en="Shadowburn" },
    [18869] = { "Тіньовий опік", "Миттєво вражає ціль, завдаючи від {1} до {2} шкоди тінню. Якщо ціль помирає протягом {3} с після \"Тіньового опіку\" та приносить досвід або честь, заклинач отримує уламок душі.#for {1} to {2}#within {3} sec", en="Shadowburn" },
    [18870] = { "Тіньовий опік", "Миттєво вражає ціль, завдаючи від {1} до {2} шкоди тінню. Якщо ціль помирає протягом {3} с після \"Тіньового опіку\" та приносить досвід або честь, заклинач отримує уламок душі.#for {1} to {2}#within {3} sec", en="Shadowburn" },
    [18871] = { "Тіньовий опік", "Миттєво вражає ціль, завдаючи від {1} до {2} шкоди тінню. Якщо ціль помирає протягом {3} с після \"Тіньового опіку\" та приносить досвід або честь, заклинач отримує уламок душі.#for {1} to {2}#within {3} sec", en="Shadowburn" },
    [18879] = { "Витягування життя", "Передає {1} здоров'я від цілі до заклинача кожні {2} с. Триває {3} с.#{1} health#every {2} sec#Lasts {3} sec", "Висмоктує {1} здоров'я кожні {2} с, передаючи його заклиначеві.#Drains {1} health#every {2} sec", en="Siphon Life" },
    [18880] = { "Витягування життя", "Передає {1} здоров'я від цілі до заклинача кожні {2} с. Триває {3} с.#{1} health#every {2} sec#Lasts {3} sec", "Висмоктує {1} здоров'я кожні {2} с, передаючи його заклиначеві.#Drains {1} health#every {2} sec", en="Siphon Life" },
