    [18958] = { "Полум'яний батіг", "Обпалює ворога, завдаючи від {1} до {2} шкоди та зменшуючи опір вогню на {3} протягом {4} с.#for {1} to {2} damage#by {3} for {4} sec", "Опір вогню зменшено на {1}.#by {1}", en="Flame Lash" },
    [18960] = { "Телепортація: Місячна галявина", "Телепортує заклинача до Місячної галявини.", en="Teleport: Moonglade" },
    [18972] = { "Сповільнення", "Збільшує інтервал між атаками ворога на {1}% та зменшує його швидкість руху на {2}% протягом {3} с.#attacks by {1}%#movement by {2}% for {3} sec", "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Slow" },
