    [19284] = { "Пристріт слабкості", "Послаблює вибраного ворога, зменшуючи його шкоду на {1} та зменшуючи ефективність будь-якого лікування на {2}%. Триває {3} хв.#caused by {1}#healing by {2}#Lasts {3} min", "Фізичну шкоду зменшено на {1}, а ефективність зцілення зменшено на {2}%.#damage done reduced by {1} and healing effectiveness reduced by {2}", en="Hex of Weakness" },
    [19285] = { "Пристріт слабкості", "Послаблює вибраного ворога, зменшуючи його шкоду на {1} та зменшуючи ефективність будь-якого лікування на {2}%. Триває {3} хв.#caused by {1}#healing by {2}#Lasts {3} min", "Фізичну шкоду зменшено на {1}, а ефективність зцілення зменшено на {2}%.#damage done reduced by {1} and healing effectiveness reduced by {2}", en="Hex of Weakness" },
    [19286] = { "Покращене вдавання мертвого", "Зменшує ймовірність опору вашій здібності \"Удавання мертвого\" на {1}%.#by {1}%", en="Improved Feign Death" },
    [19287] = { "Покращене вдавання мертвого", "Зменшує ймовірність опору вашій здібності \"Удавання мертвого\" на {1}%.#by {1}%", en="Improved Feign Death" },
    [19290] = { "Впевнені кроки", "Збільшує ймовірність поцілити на {1}% та ймовірність протидіяти ефектам обмеження руху на додаткові {2}%.#hit chance by {1}%#resisted by an additional {2}%", en="Surefooted" },
    [19295] = { "Відбиття", "Збільшує вашу ймовірність парирування на {1}%.#by {1}%", en="Deflection" },
    [19296] = { "Зорескалки", "Сипле зорескалками на голову вибраного ворога, завдаючи {1} шкоди арканою протягом {2} с.#causing {1}#over {2} sec", "{1} шкоди арканою протягом {2} с.#{1} Arcane damage over {2} sec", en="Starshards" },
    [19299] = { "Зорескалки", "Сипле зорескалками на голову вибраного ворога, завдаючи {1} шкоди арканою протягом {2} с.#causing {1}#over {2} sec", "{1} шкоди арканою протягом {2} с.#{1} Arcane damage over {2} sec", en="Starshards" },
    [19302] = { "Зорескалки", "Сипле зорескалками на голову вибраного ворога, завдаючи {1} шкоди арканою протягом {2} с.#causing {1}#over {2} sec", "{1} шкоди арканою протягом {2} с.#{1} Arcane damage over {2} sec", en="Starshards" },
    [19303] = { "Зорескалки", "Сипле зорескалками на голову вибраного ворога, завдаючи {1} шкоди арканою протягом {2} с.#causing {1}#over {2} sec", "{1} шкоди арканою протягом {2} с.#{1} Arcane damage over {2} sec", en="Starshards" },
    [19304] = { "Зорескалки", "Сипле зорескалками на голову вибраного ворога, завдаючи {1} шкоди арканою протягом {2} с.#causing {1}#over {2} sec", "{1} шкоди арканою протягом {2} с.#{1} Arcane damage over {2} sec", en="Starshards" },
    [19305] = { "Зорескалки", "Сипле зорескалками на голову вибраного ворога, завдаючи {1} шкоди арканою протягом {2} с.#causing {1}#over {2} sec", "{1} шкоди арканою протягом {2} с.#{1} Arcane damage over {2} sec", en="Starshards" },
    [19306] = { "Контратака", "Удар, який можливо провести лише після парирування атаки опонента. Ця атака завдає {1} шкоди та знерухомлює ціль на {2} с. Контратаку неможливо блокувати, парирувати чи ухилитися від неї.#deals {1} damage#for {2} sec", "Знерухомлено.", en="Counterattack" },
    [19308] = { "Тінестраж", "Жерця оточують тіні. Коли закляття або атака ближнього чи дальнього бою влучає у заклинача, нападнику буде завдано {1} шкоди від тіні. Ця шкода не спричиняє загрози та може бути завдана нападникам лише раз на кілька секунд. Ефект має {2} заряди та триває {3} хв.#struck for {1}#{2} charges#Lasts {3} min", "Завдасть {1} шкоди від тіні нападнику при отриманні удару. Ця шкода не спричиняє загрози. {2} заряди.#Causes {1}#{2} charges", en="Shadowguard" },
    [19309] = { "Тінестраж", "Жерця оточують тіні. Коли закляття або атака ближнього чи дальнього бою влучає у заклинача, нападнику буде завдано {1} шкоди від тіні. Ця шкода не спричиняє загрози та може бути завдана нападникам лише раз на кілька секунд. Ефект має {2} заряди та триває {3} хв.#struck for {1}#{2} charges#Lasts {3} min", "Завдасть {1} шкоди від тіні нападнику при отриманні удару. Ця шкода не спричиняє загрози. {2} заряди.#Causes {1}#{2} charges", en="Shadowguard" },
    [19310] = { "Тінестраж", "Жерця оточують тіні. Коли закляття або атака ближнього чи дальнього бою влучає у заклинача, нападнику буде завдано {1} шкоди від тіні. Ця шкода не спричиняє загрози та може бути завдана нападникам лише раз на кілька секунд. Ефект має {2} заряди та триває {3} хв.#struck for {1}#{2} charges#Lasts {3} min", "Завдасть {1} шкоди від тіні нападнику при отриманні удару. Ця шкода не спричиняє загрози. {2} заряди.#Causes {1}#{2} charges", en="Shadowguard" },
    [19311] = { "Тінестраж", "Жерця оточують тіні. Коли закляття або атака ближнього чи дальнього бою влучає у заклинача, нападнику буде завдано {1} шкоди від тіні. Ця шкода не спричиняє загрози та може бути завдана нападникам лише раз на кілька секунд. Ефект має {2} заряди та триває {3} хв.#struck for {1}#{2} charges#Lasts {3} min", "Завдасть {1} шкоди від тіні нападнику при отриманні удару. Ця шкода не спричиняє загрози. {2} заряди.#Causes {1}#{2} charges", en="Shadowguard" },
    [19312] = { "Тінестраж", "Жерця оточують тіні. Коли закляття або атака ближнього чи дальнього бою влучає у заклинача, нападнику буде завдано {1} шкоди від тіні. Ця шкода не спричиняє загрози та може бути завдана нападникам лише раз на кілька секунд. Ефект має {2} заряди та триває {3} хв.#struck for {1}#{2} charges#Lasts {3} min", "Завдасть {1} шкоди від тіні нападнику при отриманні удару. Ця шкода не спричиняє загрози. {2} заряди.#Causes {1}#{2} charges", en="Shadowguard" },
    [19364] = { "Гуркіт землі", "Тупотить по землі, приголомшуючи навколишніх ворогів на {1} с.#for {1} sec", "Приголомшено.", en="Ground Stomp" },
    [19365] = { "Древній жах", "Зменшує швидкість вимови заклять навколишніх ворогів на {1}% та збільшує інтервал між їхніми атаками на {2}% протягом {3} хв.#casting speed by {1}%#attacks by {2}% for {3} min", "Швидкість вимови заклять зменшено на {1}%.\nІнтервал між атаками збільшено на {2}%.#reduced by {1}%#increased by {2}%", en="Ancient Dread" },
    [19366] = { "Обпалення", "Зменшує опір вогню навколишніх ворогів на {1} протягом {2} хв.#by {1} for {2} min", "Опір вогню зменшено на {1}.#by {1}", en="Cauterizing Flames" },
    [19367] = { "Задуха", "Зменшує максимальний запас здоров'я ворога на {1}% протягом {2} хв.#by {1}% for {2} min", "Максимальний запас здоров'я зменшено на {1}%.#by {1}%", en="Withering Heat" },
    [19369] = { "Древній відчай", "Дезорієнтує навколишніх ворогів, змушуючи їх зупинити атаку та блукати протягом {1} с.#for {1} sec", "Дезорієнтовано.", en="Ancient Despair" },
    [19370] = { "Інстинкт вбивці", "Збільшує ймовірність завдати критичного удару всіма видами атак на {1}%.#by {1}%", en="Killer Instinct" },
    [19372] = { "Древня істерія", "Зменшує дух навколишніх ворогів на {1}% та зменшує їх інтелект на {2}% протягом {3} хв.#Spirit by {1}%#Intellect by {2}% for {3} min", "Дух зменшено на {1}%.\nІнтелект зменшено на {2}%.#Spirit reduced by {1}%#Intellect reduced by {2}%", en="Ancient Hysteria" },
    [19391] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [19393] = { "Опік душі", "Завдає ворогу {1} шкоди від вогню протягом {2} с, унеможливлює вимову заклять та зменшує фізичну шкоду на {3}%.#Inflicts {1} Fire#over {2} sec#deals by {3}%", "{1} шкоди від вогню протягом {2} с.\nЗавдану фізичну шкоду зменшено на {3}%.\nЗнемовлено.#{1} Fire#over {2} sec#by {3}%", en="Soul Burn" },
    [19396] = { "Спалення", nil, "Отриману вогняну шкоду збільшено на {1}.#by {1}", en="Incinerate" },
    [19397] = { "Спалення", nil, "Отриману вогняну шкоду збільшено на {1}.#by {1}", en="Incinerate" },
    [19407] = { "Покращений запаморочливий постріл", "Надає вашому \"Запаморочливому пострілу\" {1}% ймовірності приголомшити ціль на {2} с.#{1}% chance#for {2} sec", en="Improved Concussive Shot" },
    [19408] = { "Паніка", "Викликає у навколишніх ворогів паніку, змушуючи їх втікати зі страху протягом {1} с.#for {1} sec", "Втікає зі страху.", en="Panic" },
    [19409] = { "Кістяна броня", "З ймовірністю {1}% при отриманні удару в бою ви оточите себе кістяним захистом, що збільшує броню на {2} протягом {3} секунд.#a {1}% chance#armor by {2} for {3} sec", en="Bone Armor" },
    [19410] = { "Покращений запаморочливий постріл", nil, "Приголомшено.", en="Improved Concussive Shot" },
    [19416] = { "Ефективність", "Зменшує витрати мани на ваші \"Постріли\"[, \"Удари\"#Strikes] та \"Жала\" на {1}%.#by {1}%", en="Efficiency" },
    [19421] = { "Покращена мітка мисливця", "Збільшує бонус до сили атаки дальнього бою вашої \"Мітки мисливця\" на {1}%.#by {1}%", en="Improved Hunter's Mark" },
    [19428] = { "Розпалення", nil, "{1} шкоди вогнем протягом {2} с.#{1} Fire#over {2} sec", en="Conflagration" },
    [19434] = { "Прицільний постріл", "Прицільний постріл зі збільшеною на {1} шкодою дальнього бою.#by {1}", en="Aimed Shot" },
    [19438] = { "Жертва", "Приносить в жертву пустотника, при цьому захищаючи його володаря щитом, який поглинає {1} шкоди протягом {2} с. Поки щит тримається, отримання шкоди не спричиняє затримки вимови заклять.#absorb {1} damage for {2} sec", "Поглинає всю шкоду.", en="Sacrifice" },
    [19440] = { "Жертва", "Приносить в жертву пустотника, при цьому захищаючи його володаря щитом, який поглинає {1} шкоди протягом {2} с. Поки щит тримається, отримання шкоди не спричиняє затримки вимови заклять.#absorb {1} damage for {2} sec", "Поглинає всю шкоду.", en="Sacrifice" },
    [19441] = { "Жертва", "Приносить в жертву пустотника, при цьому захищаючи його володаря щитом, який поглинає {1} шкоди протягом {2} с. Поки щит тримається, отримання шкоди не спричиняє затримки вимови заклять.#absorb {1} damage for {2} sec", "Поглинає всю шкоду.", en="Sacrifice" },
    [19442] = { "Жертва", "Приносить в жертву пустотника, при цьому захищаючи його володаря щитом, який поглинає {1} шкоди протягом {2} с. Поки щит тримається, отримання шкоди не спричиняє затримки вимови заклять.#absorb {1} damage for {2} sec", "Поглинає всю шкоду.", en="Sacrifice" },
    [19443] = { "Жертва", "Приносить в жертву пустотника, при цьому захищаючи його володаря щитом, який поглинає {1} шкоди протягом {2} с. Поки щит тримається, отримання шкоди не спричиняє затримки вимови заклять.#absorb {1} damage for {2} sec", "Поглинає всю шкоду.", en="Sacrifice" },
    [19448] = { "Отрута", "Завдає ворогу шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison" },
    [19450] = { "Плювок магми", nil, "{1} шкоди вогнем кожні {2} с.#{1} Fire#every {2} sec", en="Magma Spit" },
    [19451] = { "Оскаженіння", nil, "Швидкість атаки збільшено на {1}%.#by {1}%", en="Frenzy" },
    [19454] = { "Покращений арканічний постріл", "Зменшує час відновлення \"Арканічного пострілу\" на {1} с.#Shot by {1} sec", en="Improved Arcane Shot" },
    [19461] = { "Шквал", "Збільшує шкоду ваших здібностей \"Багатозарядний постріл\" та \"Обстріл\" на {1}%.#by {1}%", en="Barrage" },
    [19463] = { "Плювок їдкої кислоти", "Завдає ворогу шкоди від природи і зменшує його броню протягом {1} с.#for {1} sec", "Броню зменшено.", en="Corrosive Acid Spit" },
    [19464] = { "Покращене жало змії", "Збільшує шкоду вашої здібності \"Жало змії\" на {1}%.#by {1}%", en="Improved Serpent Sting" },
    [19469] = { "Отруєння розуму", "Бере під контроль ворога до {1} рівня та завдає шкоди від природи кожні {2} с протягом {3} с.#level {1} and#every {2} sec#for {3} sec", "Причаровано.\nЗавдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison Mind" },
    [19478] = { "Заражена кров", "Заражає кров скверногончої на {1} хв. Коли скверногончу вдаряють атакою ближнього бою, нападник втратить {2} сили атаки ближнього бою на {3} с. Накопичується до {4} разів на одній цілі.#blood for {1} min#{2} melee attack power for {3} sec#{4} times", "Відбирає {1} сили атаки ближнього бою при отриманні удару. Накопичується до {2} разів.#Drains {1}#{2} times", en="Tainted Blood" },
    [19479] = { "Ефект зараженої крові", nil, "Силу атаки ближнього бою зменшено на {1}.#by {1}", en="Tainted Blood Effect" },
    [19480] = { "Параноя", "Підсилює здатність виявлення непомітності всіх учасників групи в межах {1} м від скверногончої.#within {1} y", "Здатність виявлення непомітності підсилено.", en="Paranoia" },
    [19485] = { "Смертельні постріли", "Збільшує додаткову шкоду від критичних ударів зброєю дальнього бою[ та здібностями ближнього бою#and melee ability] на {1}%.#damage bonus by {1}%", en="Mortal Shots" },
    [19496] = { "Магмові кайдани", "Зменшує швидкість руху навколишніх ворогів на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Magma Shackles" },
    [19498] = { "Яструбине око", "Збільшує дальність вашої зброї дальнього бою на {1} м.#by {1} y", en="Hawk Eye" },
    [19503] = { "Дезорієнтуючий постріл", "Постріл з короткої дистанції, що завдає {1}% шкоди від зброї та дезорієнтує ціль на {2} с. Будь-яка шкода скасує ефект. Припиняє вашу атаку при використанні.#deals {1}%#for {2} sec", "Дезорієнтовано.", en="Scatter Shot" },
    [19505] = { "Пожирання магії", "Розвіює {1} негативний магічний ефект з дружньої цілі або {2} сприятливий магічний ефект з ворожої цілі. Пожирання ефекту зцілює скверногончій {3} здоров'я.#{1} harmful#{2} beneficial#healed for {3}", en="Devour Magic" },
    [19506] = { "Аура влучного пострілу", "Збільшує силу атаки[ дальнього бою#the ranged attack power of party] учасників групи в межах {1} м на {2}[, а силу атаки дальнього бою мисливця додатково на {1}#ranged attack power by an additional {1}]. Триває {3} хв.#within {1} yards by {2}#Lasts {3} min", "Силу атаки[ дальнього бою#Ranged Attack Power increased by {1}] збільшено на {1}[, а силу атаки дальнього бою мисливця додатково на {1}#Ranged Attack Power increased by an additional {1}].#increased by {1}", en="Trueshot Aura" },
    [19507] = { "Спеціалізація на зброї дальнього бою", "Збільшує шкоду зброї дальнього бою на {1}%.#by {1}%", en="Ranged Weapon Specialization" },
    [19549] = { "Покращений аспект мавпи", "Збільшує бонус до ймовірності ухилення від аспекту мавпи на {1}%.#by {1}%", en="Improved Aspect of the Monkey" },
    [19557] = { "Покращені очі звіра", "Збільшує тривалість дії вашої здібності \"Очі звіра\" на {1} с.#by {1} sec", en="Improved Eyes of the Beast" },
    [19558] = { "Покращені очі звіра", "Збільшує тривалість дії вашої здібності \"Очі звіра\" на {1} с.#by {1} sec", en="Improved Eyes of the Beast" },
    [19559] = { "Орієнтування на місцевості", "Збільшує бонус до швидкості руху від \"Аспекту гепарда\" та \"Аспекту зграї\" на {1}%.#by {1}%", en="Pathfinding" },
    [19566] = { "Сільничка", "Дозволяє досвідченому шкірнику перетворити глибокоскельну сіль на очищену глибокоскельну сіль. Прилад опромінює користувача суб'ядерними мікроопроменями і не може використовуватися частіше, ніж раз на кілька днів.", en="Salt Shaker" },
    [19572] = { "Покращене зцілення вихованця", "\"Зцілення вихованця\" з ймовірністю {1}% знімає {2} ефект прокляття, хвороби, магії або отрути на кожному такті зцілення.#a {1}% chance#cleansing {2}", en="Improved Mend Pet" },
    [19574] = { "Звіриний гнів", "Роздратовує вашого вихованця, що збільшує його шкоду на {1}% протягом {2} с. Розлючений звір не відчуває ні жалю, ні страху, і зупинити його може лише смерть.#causing {1}#for {2} sec", "Несамовитість.", en="Bestial Wrath" },
    [19577] = { "Залякування", "Наказати вашому вихованцю залякати ціль із наступною успішною атакою ближнього бою, спричиняючи високий рівень загрози та приголомшуючи її на {1} с.#for {1} sec", "Лячний.", en="Intimidation" },
    [19578] = { "Духовний зв'язок", "Поки ваш вихованець активний, ви обоє відновлюєте {1}% здоров'я кожні {2} с.#{1}% of total health every {2} sec", en="Spirit Bond" },
    [19583] = { "Тренування витримки", "Збільшує здоров'я ваших вихованців на {1}%.#by {1}%", en="Endurance Training" },
    [19590] = { "Звіряча дисципліна", "Прискорює відновлення концентрації ваших вихованців на {1}%.#by {1}%", en="Bestial Discipline" },
    [19595] = { "Відбивання тіні та криги", "Відбиває закляття тіні та криги в заклиначів", "Відбиває закляття тіні та криги в заклиначів", en="Shadow and Frost Reflect" },
    [19596] = { "Звіряча стрімкість", "Перебуваючи просто неба ваші вихованці рухаються на {1}% швидше.#by {1}%", en="Bestial Swiftness" },
    [19598] = { "Лютість", "Збільшує ймовірність критичного удару ваших вихованців на {1}%.#by {1}%", en="Ferocity" },
    [19609] = { "Товста шкура", "Збільшує показник броні ваших вихованців на {1}%.#by {1}%", en="Thick Hide" },
    [19616] = { "Вивільнена лють", "Збільшує шкоду ваших вихованців на {1}%.#by {1}%", en="Unleashed Fury" },
    [19621] = { "Оскаженіння", "Ваш вихованець з ймовірністю {1}% збільшить швидкість атаки на {2}% протягом {3} с після завдання критичного удару.#{1}% chance#{2}% attack speed#for {3} sec", en="Frenzy" },
    [19630] = { "Конус вогню", "Завдає від {1} до {2} шкоди вогнем ворогам у конусі перед заклиначем.#Inflicts {1} to {2} Fire", en="Cone of Fire" },
    [19631] = { "Розплавлення броні", "Зменшує броню навколишніх ворогів на {1} протягом {2} хв.#by {1} for {2} min", "Броню зменшено на {1}.#by {1}", en="Melt Armor" },
    [19632] = { "Розсічення", "Завдає звичайної шкоди плюс {1} ворогу та його союзникам неподалік, вражаючи до {2} цілей.#plus {1} to#up to {2} target", en="Cleave" },
    [19634] = { "Відновлення мани", "Відновлює {1} мани кожні {2} с протягом {3} секунд.#Restores {1} mana every {2} sec for {3} sec", "Відновлює {1} мани кожні {2} с.#Restores {1} mana every {2} sec", en="Mana Rejuvenation" },
    [19635] = { "Розпалення полум'я", ref=19366, en="Incite Flames" },
    [19638] = { "Призматичний камінь", "Збільшує всі види опору на {1} протягом {2} с.#resistances by {1} for {2} sec", en="Prismstone" },
    [19641] = { "Пірокластичний обстріл", "Завдає {1} шкоди від вогню ворогам в конусі перед заклиначем, приголомшуючи їх на {2} с.#Inflicts {1} Fire#for {2} sec", "Приголомшено.\n{1} шкоди від вогню протягом {2} с.#{1} Fire#over {2} sec", en="Pyroclast Barrage" },
    [19642] = { "Розсічення", "Завдає звичайної шкоди плюс {1} ворогу та його союзникам неподалік, вражаючи до {2} цілей.#plus {1} to#up to {2} target", en="Cleave" },
    [19643] = { "Смертельний удар", "Завдає {1}% шкоди від зброї та ранить ціль, зменшуючи ефективність будь-якого зцілення на {2}% протягом {3} с.#Inflicts {1}% weapon#healing by {2}% for {3} sec", "Ефективність зцілення зменшено на {1}%.#reduced by {1}%", en="Mortal Strike" },
    [19646] = { "Срібний ключ-відмичка", "Дозволяє відкривати прості замки. Одноразовий.", en="Silver Skeleton Key" },
    [19647] = { "Заборона чар", "Знемовлює ціль на {1} с. Якщо ціль була в процесі вимови закляття, перериває та унеможливлює вимову заклять тієї ж школи протягом {2} с.#enemy for {1} sec#cast for {2} sec", en="Spell Lock" },
    [19649] = { "Золотий ключ-відмичка", "Дозволяє відкривати звичайні замки. Одноразовий.", en="Golden Skeleton Key" },
    [19651] = { "Ясносрібний ключ-відмичка", "Дозволяє відкривати непрості замки. Одноразовий.", en="Truesilver Skeleton Key" },
    [19652] = { "Ефект зараженої крові", nil, "Силу атаки ближнього бою зменшено на {1}.#by {1}", en="Tainted Blood Effect" },
    [19653] = { "Ефект зараженої крові", nil, "Силу атаки ближнього бою зменшено на {1}.#by {1}", en="Tainted Blood Effect" },
    [19654] = { "Ефект зараженої крові", nil, "Силу атаки ближнього бою зменшено на {1}.#by {1}", en="Tainted Blood Effect" },
    [19655] = { "Заражена кров", "Заражає кров скверногончої на {1} хв. Коли скверногончу вдаряють атакою ближнього бою, нападник втратить {2} сили атаки ближнього бою на {3} с. Накопичується до {4} разів на одній цілі.#blood for {1} min#{2} melee attack power for {3} sec#{4} times", "Відбирає {1} сили атаки ближнього бою при отриманні удару. Накопичується до {2} разів.#Drains {1}#{2} times", en="Tainted Blood" },
    [19656] = { "Заражена кров", "Заражає кров скверногончої на {1} хв. Коли скверногончу вдаряють атакою ближнього бою, нападник втратить {2} сили атаки ближнього бою на {3} с. Накопичується до {4} разів на одній цілі.#blood for {1} min#{2} melee attack power for {3} sec#{4} times", "Відбирає {1} сили атаки ближнього бою при отриманні удару. Накопичується до {2} разів.#Drains {1}#{2} times", en="Tainted Blood" },
    [19658] = { "Ефект пожирання магії", en="Devour Magic Effect" },
    [19659] = { "Спалення мани", "Спалює навколишнім ворогам {1} мани кожні {2} с протягом {3} хв. Кожна одиниця спаленої також завдає шкоди цілі.#Burns {1} mana#every {2} sec#for {3} min", "Спалює {1} мани кожні {2} с.#{1} mana#every {2} sec", en="Ignite Mana" },
    [19660] = { "Заражена кров", "Заражає кров скверногончої на {1} хв. Коли скверногончу вдаряють атакою ближнього бою, нападник втратить {2} сили атаки ближнього бою на {3} с. Накопичується до {4} разів на одній цілі.#blood for {1} min#{2} melee attack power for {3} sec#{4} times", "Відбирає {1} сили атаки ближнього бою при отриманні удару. Накопичується до {2} разів.#Drains {1}#{2} times", en="Tainted Blood" },
    [19669] = { "Арканітовий ключ-відмичка", "Дозволяє відкривати складні замки. Одноразовий.", en="Arcanite Skeleton Key" },
    [19690] = { "Ілюзія Багряного Походу", "Використовуйте, щоб замаскуватися під члена Багряного Походу.", "Замасковано під члена Багряного Походу.", en="Scarlet Illusion" },
    [19702] = { "Неминуча загибель", "Завдає {1} шкоди від тіні навколишнім ворогам через {2} с.#Inflicts {1} Shadow#after {2} sec", "{1} шкоди від тіні через {2} с.#{1} Shadow#after {2} sec", en="Impending Doom" },
    [19703] = { "Прокляття Люцифрона", "Проклинає навколишніх ворогів, збільшуючи витрати ресурсів на закляття та здібності на {1}% протягом {2} хв. Збільшення витрати ресурсів впливає на всі закляття та здібності, незалежно від того, витрачають вони ману, лють чи енергію.#by {1}% for {2} min", "Витрати ресурсів на закляття та здіюності збільшено на {1}%.#by {1}%", en="Lucifron's Curse" },
    [19705] = { "Ситість", nil, "Витривалість та дух збільшено на {1}.#by {1}", en="Well Fed" },
    [19706] = { "Ситість", nil, "Витривалість та дух збільшено на {1}.#by {1}", en="Well Fed" },
    [19708] = { "Ситість", nil, "Витривалість та дух збільшено на {1}.#by {1}", en="Well Fed" },
    [19709] = { "Ситість", nil, "Витривалість та дух збільшено на {1}.#by {1}", en="Well Fed" },
    [19710] = { "Ситість", nil, "Витривалість та дух збільшено на {1}.#by {1}", en="Well Fed" },
    [19711] = { "Ситість", nil, "Витривалість та дух збільшено на {1}.#by {1}", en="Well Fed" },
    [19713] = { "Прокляття Шаззраха", "Збільшує отриману магічну шкоду навколишніми ворогами на {1}% протягом {2} хв.#by {1}% for {2} min", "Отриману магічну шкоду збільшено на {1}%.#by {1}%", en="Shazzrah's Curse" },
    [19716] = { "Прокляття Геєнаса", "Зменшує ефективність зцілення навколишніх ворогів на {1}% протягом {2} хв.#by {1}% for {2} min", "Ефективність зцілення зменшено на {1}%.#reduced by {1}%", en="Gehennas' Curse" },
    [19717] = { "Вогняний дощ", "Викликає вогняний дощ, що обпалює ворогів у зоні ураження, завдаючи від {1} до {2} шкоди вогнем кожні {3} с[ протягом {1} с#for {1} sec].#for {1} to {2} Fire#every {3} sec", "Отримання від {1} до {2} шкоди від вогню кожні {3} с.#{1} to {2} Fire#every {3} sec", en="Rain of Fire" },
    [19731] = { "Пожирання магії", "Розвіює {1} негативний магічний ефект з дружньої цілі або {2} сприятливий магічний ефект з ворожої цілі. Пожирання ефекту зцілює скверногончій {3} здоров'я.#{1} harmful#{2} beneficial#healed for {3}", en="Devour Magic" },
    [19734] = { "Пожирання магії", "Розвіює {1} негативний магічний ефект з дружньої цілі або {2} сприятливий магічний ефект з ворожої цілі. Пожирання ефекту зцілює скверногончій {3} здоров'я.#{1} harmful#{2} beneficial#healed for {3}", en="Devour Magic" },
    [19736] = { "Пожирання магії", "Розвіює {1} негативний магічний ефект з дружньої цілі або {2} сприятливий магічний ефект з ворожої цілі. Пожирання ефекту зцілює скверногончій {3} здоров'я.#{1} harmful#{2} beneficial#healed for {3}", en="Devour Magic" },
    [19740] = { "Благословення могутності", "Благословляє дружню ціль, збільшуючи силу атаки ближнього бою на {1} протягом {2} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#by {1} for {2} min", "Збільшує силу атаки ближнього бою на {1}.#by {1}", en="Blessing of Might" },
    [19742] = { "Благословення мудрості", "Благословляє дружню ціль, відновлюючи їй {1} мани кожні {2} с протягом {3} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#{1} mana every {2} seconds for {3} min", "Відновлює {1} мани кожні {2} с.#{1} mana every {2} sec", en="Blessing of Wisdom" },
    [19746] = { "Аура зосередженості", "Надає учасникам групи в межах {2} м {1}% ймовірності уникнути затримки вимови заклять, спричиненої шкодою. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#{1}% chance#within {2}", "Надає {1}% ймовірності уникнути затримки вимови заклять спричиненої шкодою.#{1}% chance", en="Concentration Aura" },
    [19750] = { "Зблиск світла", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Flash of Light" },
    [19752] = { "Божественне втручання", "Паладин приносить себе в жертву, щоб захистити обраного учасника групи. Вороги припинять атакувати захищеного гравця, який також буде невразливим до всіх негативних ефектів та атак, але не зможе нічого робити протягом {1} хв.#for {1} min", "Цілковита невразливість, але не може рухатися.", en="Divine Intervention" },
    [19753] = { "Божественне втручання", nil, "Цілковита невразливість, але не може рухатися.", en="Divine Intervention" },
    [19755] = { "Злякіготь", ref=13524, en="Frightalon" },
    [19769] = { "Торієва граната", ref=4064, en="Thorium Grenade" },
    [19771] = { "Рваний укус", "Завдає {1} фізичної шкоди ворогу протягом {2} с.#Inflicts {1} Physical#over {2} sec", "Завдає {1} шкоди протягом {2} с.#{1} damage#over {2} sec", en="Serrated Bite" },
    [19772] = { "Виклик механічної жаби", "Клацніть правою кнопкою миші, щоб викликати і відпустити механічну жабу.", en="Summon Lifelike Toad" },
    [19776] = { "Слово тіні: Біль", "Вимовляє слово темряви, що завдає ворогу шкоди тінню кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від тіні кожні {1} с.#every {1} sec", en="Shadow Word: Pain" },
    [19778] = { "Деморалізуючий клич", "Зменшує силу атаки ближнього та дальнього бою ворогів поблизу на {1} протягом {2} с.#enemies by {1} for {2} sec", "Силу атаки ближнього та дальнього бою зменшено на {1}.#by {1}", en="Demoralizing Shout" },
    [19780] = { "Рука Раґнароса", "Завдає від {1} до {2} шкоди навколишнім ворогам, відкидає їх та приголомшує на {3} с.#Inflicts {1} to {2} Fire#for {3} sec", "Приголомшено.", en="Hand of Ragnaros" },
    [19784] = { "Бомба з темного заліза", ref=4064, en="Dark Iron Bomb" },
    [19801] = { "Заспокійливий постріл", "Спроба зняти {1} ефект навіженості з ворожої істоти.#remove {1}", en="Tranquilizing Shot" },
    [19804] = { "Арканітове драконеня", "Активувати арканітове драконеня, що битиметься за вас протягом {1} хв. Перш ніж його можна буде використати знову, йому потрібно відновитись протягом години.#fight for you for {1} min", en="Arcanite Dragonling" },
    [19812] = { "Оскаженіння", nil, "Швидкість атаки збільшено на {1}%.#by {1}%", en="Frenzy" },
    [19816] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [19820] = { "Нівечення", "Завдає {1} шкоди ворогу кожні {2} с та зменшує швидкість його руху на {3}% протягом {4} с.#Inflicts {1} damage#every {2} sec#by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.\nЗавдає {2} фізичної шкоди кожні {3} с.#reduced by {1}%#{2} Physical#every {3} sec", en="Mangle" },
    [19821] = { "Арканічна бомба", "Спалює від {1} до {2} мани цілям в радіусі вибуху та завдає шкоди в обсязі {3}% від спаленої мани. Також знемовлює жертв вибуху на {4} с.#Drains {1} to {2} mana#does {3}% of the mana#blast for {4} sec", "Знемовлено.", en="Arcane Bomb" },
    [19832] = { "Одержимість", nil, "Одержимість.", en="Possess" },
    [19834] = { "Благословення могутності", "Благословляє дружню ціль, збільшуючи силу атаки ближнього бою на {1} протягом {2} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#by {1} for {2} min", "Збільшує силу атаки ближнього бою на {1}.#by {1}", en="Blessing of Might" },
    [19835] = { "Благословення могутності", "Благословляє дружню ціль, збільшуючи силу атаки ближнього бою на {1} протягом {2} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#by {1} for {2} min", "Збільшує силу атаки ближнього бою на {1}.#by {1}", en="Blessing of Might" },
