    [19853] = { "Благословення мудрості", "Благословляє дружню ціль, відновлюючи їй {1} мани кожні {2} с протягом {3} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#{1} mana every {2} seconds for {3} min", "Відновлює {1} мани кожні {2} с.#{1} mana every {2} sec", en="Blessing of Wisdom" },
    [19854] = { "Благословення мудрості", "Благословляє дружню ціль, відновлюючи їй {1} мани кожні {2} с протягом {3} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#{1} mana every {2} seconds for {3} min", "Відновлює {1} мани кожні {2} с.#{1} mana every {2} sec", en="Blessing of Wisdom" },
