    [20811] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [20812] = { "Каліцтво", "Збільшує інтервал між атаками ворога на {1}%, зменшує його швидкість руху на {2}% та силу на {3}%. Триває {4} с.#attacks by {1}%#movement by {2}%#Strength by {3}%#Lasts {4} sec", "Швидкість руху зменшено на {1}%.\nІнтервал між атаками збільшено на {2}%.\nСилу зменшено на {3}%.#speed reduced by {1}%#increased by {2}%#Strength reduced by {3}%", en="Cripple" },
    [20815] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [20819] = { "Крижана стріла", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frostbolt" },
    [20822] = { "Крижана стріла", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frostbolt" },
    [20823] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [20826] = { "Жертовний вогонь", "Обпалює ворога, завдаючи шкоди вогнем кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Immolate" },
    [20828] = { "Конус холоду", "Завдає шкоди від криги ворогам у конусі перед заклиначем та зменшує їх швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Cone of Cold" },
    [20847] = { "Левовий ріг Штормовію", "З ймовірністю {1}% при отриманні удару в бою ви збільшите броню всіх учасників групи на {2} протягом {3} секунд.#a {1}% chance#armor by {2} for {3} sec", en="The Lion Horn of Stormwind" },
    [20869] = { "Крижаний вибух", "Завдає цілі [{1}#for {1} Frost][від {1} до {2}#for {1} to {2} Frost] шкоди від криги.", en="Frost Blast" },
    [20875] = { "Ром Ромсі", "Збільшує витривалість на {1} протягом {2} хв та люто п'янить!#Stamina by {1} for {2} min", "Витривалість збільшено на {1}.#by {1}", en="Rumsey Rum" },
    [20882] = { "Поневолення демона", "Поневолює обраного демона до {1} рівня, примушуючи його підкоритися вам. Протягом дії поневолення інтервал між атаками демона збільшується на {2}%, а його вимова заклять сповільнюється на {3}%. Триває до {4} хв.#up to level {1}#increased by {2}%#slowed by {3}%#Lasts up to {4} min", "Поневолено.", en="Subjugate Demon" },
    [20883] = { "Арканічний спалах", "Завдає цілі {1} шкоди від аркани.#for {1} Arcane", en="Arcane Blast" },
    [20885] = { "Живість", "Відновлює {1} здоров'я кожні {2} с.#Restores {1} health per {2} sec", "Відновлює {1} здоров'я кожні {2} с.#Restores {1} health per {2} sec", en="Vitality" },
    [20886] = { "Шкода від шипів +{1}#Dmg +{1}", "При отриманні удару в бою завдає {1} арканічної шкоди нападнику.#inflicts {1} Arcane", en="Thorns Dmg +3" },
    [20900] = { "Прицільний постріл", "Прицільний постріл зі збільшеною на {1} шкодою дальнього бою.#by {1}", en="Aimed Shot" },
    [20901] = { "Прицільний постріл", "Прицільний постріл зі збільшеною на {1} шкодою дальнього бою.#by {1}", en="Aimed Shot" },
    [20902] = { "Прицільний постріл", "Прицільний постріл зі збільшеною на {1} шкодою дальнього бою.#by {1}", en="Aimed Shot" },
    [20903] = { "Прицільний постріл", "Прицільний постріл зі збільшеною на {1} шкодою дальнього бою.#by {1}", en="Aimed Shot" },
    [20904] = { "Прицільний постріл", "Прицільний постріл зі збільшеною на {1} шкодою дальнього бою.#by {1}", en="Aimed Shot" },
    [20905] = { "Аура влучного пострілу", "Збільшує силу атаки[ дальнього бою#the ranged attack power of party] учасників групи в межах {1} м на {2}[, а силу атаки дальнього бою мисливця додатково на {1}#ranged attack power by an additional {1}]. Триває {3} хв.#within {1} yards by {2}#Lasts {3} min", "Силу атаки[ дальнього бою#Ranged Attack Power increased by {1}] збільшено на {1}[, а силу атаки дальнього бою мисливця додатково на {1}#Ranged Attack Power increased by an additional {1}].#increased by {1}", en="Trueshot Aura" },
    [20906] = { "Аура влучного пострілу", "Збільшує силу атаки[ дальнього бою#the ranged attack power of party] учасників групи в межах {1} м на {2}[, а силу атаки дальнього бою мисливця додатково на {1}#ranged attack power by an additional {1}]. Триває {3} хв.#within {1} yards by {2}#Lasts {3} min", "Силу атаки[ дальнього бою#Ranged Attack Power increased by {1}] збільшено на {1}[, а силу атаки дальнього бою мисливця додатково на {1}#Ranged Attack Power increased by an additional {1}].#increased by {1}", en="Trueshot Aura" },
    [20909] = { "Контратака", "Удар, який можливо провести лише після парирування атаки опонента. Ця атака завдає {1} шкоди та знерухомлює ціль на {2} с. Контратаку неможливо блокувати, парирувати чи ухилитися від неї.#deals {1} damage#for {2} sec", "Знерухомлено.", en="Counterattack" },
    [20910] = { "Контратака", "Удар, який можливо провести лише після парирування атаки опонента. Ця атака завдає {1} шкоди та знерухомлює ціль на {2} с. Контратаку неможливо блокувати, парирувати чи ухилитися від неї.#deals {1} damage#for {2} sec", "Знерухомлено.", en="Counterattack" },
    [20915] = { "Печатка наказу", "Надає паладинові ймовірність завдати додаткової шкоди святістю в обсязі {1}% від звичайної шкоди зброєю. Лише одна печатка може бути задіяна на паладинові одночасно. Триває {2} с.\n\nВивільнення енергії цієї печатки засудить ворога, миттєво завдаючи від {3} до {4} шкоди святістю або від {5} до {6}, якщо ціль приголомшена або недієздатна.#equal to {1}#Lasts {2} sec#causing {3} to {4} Holy damage, {5} to {6}", "Атаки ближнього бою можуть завдати додаткової шкоди святістю.", en="Seal of Command" },
    [20918] = { "Печатка наказу", "Надає паладинові ймовірність завдати додаткової шкоди святістю в обсязі {1}% від звичайної шкоди зброєю. Лише одна печатка може бути задіяна на паладинові одночасно. Триває {2} с.\n\nВивільнення енергії цієї печатки засудить ворога, миттєво завдаючи від {3} до {4} шкоди святістю або від {5} до {6}, якщо ціль приголомшена або недієздатна.#equal to {1}#Lasts {2} sec#causing {3} to {4} Holy damage, {5} to {6}", "Атаки ближнього бою можуть завдати додаткової шкоди святістю.", en="Seal of Command" },
    [20919] = { "Печатка наказу", "Надає паладинові ймовірність завдати додаткової шкоди святістю в обсязі {1}% від звичайної шкоди зброєю. Лише одна печатка може бути задіяна на паладинові одночасно. Триває {2} с.\n\nВивільнення енергії цієї печатки засудить ворога, миттєво завдаючи від {3} до {4} шкоди святістю або від {5} до {6}, якщо ціль приголомшена або недієздатна.#equal to {1}#Lasts {2} sec#causing {3} to {4} Holy damage, {5} to {6}", "Атаки ближнього бою можуть завдати додаткової шкоди святістю.", en="Seal of Command" },
    [20920] = { "Печатка наказу", "Надає паладинові ймовірність завдати додаткової шкоди святістю в обсязі {1}% від звичайної шкоди зброєю. Лише одна печатка може бути задіяна на паладинові одночасно. Триває {2} с.\n\nВивільнення енергії цієї печатки засудить ворога, миттєво завдаючи від {3} до {4} шкоди святістю або від {5} до {6}, якщо ціль приголомшена або недієздатна.#equal to {1}#Lasts {2} sec#causing {3} to {4} Holy damage, {5} to {6}", "Атаки ближнього бою можуть завдати додаткової шкоди святістю.", en="Seal of Command" },
    [20922] = { "Освячення", "Освячує землю під паладином, завдаючи {1} шкоди святістю протягом {2} с усім ворогам в зоні дії.#doing {1} Holy damage over {2} sec", "{1} шкоди щосекунди.#{1} damage", en="Consecration" },
    [20923] = { "Освячення", "Освячує землю під паладином, завдаючи {1} шкоди святістю протягом {2} с усім ворогам в зоні дії.#doing {1} Holy damage over {2} sec", "{1} шкоди щосекунди.#{1} damage", en="Consecration" },
    [20924] = { "Освячення", "Освячує землю під паладином, завдаючи {1} шкоди святістю протягом {2} с усім ворогам в зоні дії.#doing {1} Holy damage over {2} sec", "{1} шкоди щосекунди.#{1} damage", en="Consecration" },
    [20925] = { "Священний щит", "Збільшує ймовірність блокування на {1}% протягом {2} с та завдає {3} шкоди святістю з кожною заблокованою атакою протягом дії закляття. Шкода від \"Священного щита\" спричиняє {4}% додаткової загрози. Кожне блокування витрачає один заряд. {5} заряди.[\n\nАктивація \"Священного щита\" також збільшує шкоду заклять на {1} за кожну одиницю вашої навички захисту понад {2}. Триває {3} секунд.#grants you {1} Spell Power for each point of your defense skill beyond {2}. Lasts {3} sec]#block by {1}% for {2} sec#deals {3} Holy damage for each#causes {4}% additional threat#{5} charges", "Ймовірність блокування збільшено на {1}%. Завдає {2} шкоди святістю нападникові при блокуванні. Шкода від \"Священного щита\" спричиняє {3}% додаткової загрози.[ Зарядів: {1}#{1} charges].#chance increased by {1}%#{2} Holy damage dealt#causes {3}% additional threat", en="Holy Shield" },
    [20927] = { "Священний щит", "Збільшує ймовірність блокування на {1}% протягом {2} с та завдає {3} шкоди святістю з кожною заблокованою атакою протягом дії закляття. Шкода від \"Священного щита\" спричиняє {4}% додаткової загрози. Кожне блокування витрачає один заряд. {5} заряди.[\n\nАктивація \"Священного щита\" також збільшує шкоду заклять на {1} за кожну одиницю вашої навички захисту понад {2}. Триває {3} секунд.#grants you {1} Spell Power for each point of your defense skill beyond {2}. Lasts {3} sec]#block by {1}% for {2} sec#deals {3} Holy damage for each#causes {4}% additional threat#{5} charges", "Ймовірність блокування збільшено на {1}%. Завдає {2} шкоди святістю нападникові при блокуванні. Шкода від \"Священного щита\" спричиняє {3}% додаткової загрози.[ Зарядів: {1}#{1} charges].#chance increased by {1}%#{2} Holy damage dealt#causes {3}% additional threat", en="Holy Shield" },
    [20928] = { "Священний щит", "Збільшує ймовірність блокування на {1}% протягом {2} с та завдає {3} шкоди святістю з кожною заблокованою атакою протягом дії закляття. Шкода від \"Священного щита\" спричиняє {4}% додаткової загрози. Кожне блокування витрачає один заряд. {5} заряди.[\n\nАктивація \"Священного щита\" також збільшує шкоду заклять на {1} за кожну одиницю вашої навички захисту понад {2}. Триває {3} секунд.#grants you {1} Spell Power for each point of your defense skill beyond {2}. Lasts {3} sec]#block by {1}% for {2} sec#deals {3} Holy damage for each#causes {4}% additional threat#{5} charges", "Ймовірність блокування збільшено на {1}%. Завдає {2} шкоди святістю нападникові при блокуванні. Шкода від \"Священного щита\" спричиняє {3}% додаткової загрози.[ Зарядів: {1}#{1} charges].#chance increased by {1}%#{2} Holy damage dealt#causes {3}% additional threat", en="Holy Shield" },
    [20929] = { "Священний шок", "Вражає ціль священною енергією, завдаючи від {1} до {2} шкоди святістю ворогові або зцілюючи від {3} до {4} здоров'я союзникові.#{1} to {2} Holy damage#{3} to {4} healing", en="Holy Shock" },
    [20930] = { "Священний шок", "Вражає ціль священною енергією, завдаючи від {1} до {2} шкоди святістю ворогові або зцілюючи від {3} до {4} здоров'я союзникові.#{1} to {2} Holy damage#{3} to {4} healing", en="Holy Shock" },
    [20959] = { "Збільшення відновлення мани", "Відновлює {1} мани кожні {2} с.#Restores {1} mana per {2} sec", en="Increased Mana Regen" },
