    [22539] = { "Тіньове полум'я", "Завдає від {1} до {2} шкоди ворогам у конусі перед заклиначем.#Inflicts {1} to {2}", en="Shadow Flame" },
    [22558] = { "Сила червоного роду", en="Brood Power: Red" },
    [22559] = { "Сила синього роду", en="Brood Power: Blue" },
    [22561] = { "Сила зеленого роду", en="Brood Power: Green" },
    [22563] = { "Поверенння", "Повертає вас в притулок форту Морозних Вовків.", en="Recall" },
    [22564] = { "Поверенння", "Повертає вас в притулок Дун-Балдара.", en="Recall" },
    [22566] = { "Пристріт", "Перетворює навколишніх ворогів на жаб, позбавляючи їх можливості атакувати та застосовувати заклинання протягом {1} с.#for {1} sec", "Зурочено.", en="Hex" },
    [22568] = { "Безжалісний укус", "Завершальний рух, що завдає шкоди в залежності від довжини комбінації та перетворює кожну одиницю енергії на додаткові {1} шкоди. Шкода збільшується від сили атаки.\n  1 прийом: {2}-{3} шкоди\n  2 прийоми: {4}-{5} шкоди\n  3 прийоми: {6}-{7} шкоди\n  4 прийоми: {8}-{9} шкоди\n  5 прийомів: {10}-{11} шкоди#{1} additional#1 point  : {2}-{3}#2 points: {4}-{5}#3 points: {6}-{7}#4 points: {8}-{9}#5 points: {10}-{11}", en="Ferocious Bite" },
    [22582] = { "Крижаний шок", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frost Shock" },
    [22592] = { "Збиття з ніг", "Збиває ворога з ніг, приголомшуючи його на {1} с.#for {1} sec", "Приголомшено.", en="Knockdown" },
    [22593] = { "Вогняний покрив Світанку", "Накласти на наплічники чари, що збільшують опір вогню на {1}.#Permanently adds {1} fire resistance", en="Flame Mantle of the Dawn" },
    [22594] = { "Крижаний покрив Світанку", "Накласти на наплічники чари, що збільшують опір кризі на {1}.#Permanently adds {1} frost resistance", en="Frost Mantle of the Dawn" },
    [22596] = { "Тіньовий покрив Світанку", "Накласти на наплічники чари, що збільшують опір тіні на {1}.#Permanently adds {1} shadow resistance", en="Shadow Mantle of the Dawn" },
    [22597] = { "Природній покрив Світанку", "Накласти на наплічники чари, що збільшують опір природі на {1}.#Permanently adds {1} nature resistance", en="Nature Mantle of the Dawn" },
    [22598] = { "Арканічний покрив Світанку", "Накласти на наплічники чари, що збільшують опір аркані на {1}.#Permanently adds {1} arcane resistance", en="Arcane Mantle of the Dawn" },
    [22599] = { "Хроматичний покрив Світанку", "Накласти на наплічники чари, що збільшують опір всім школам магії на {1}.#Permanently adds {1} resistance to all magic", en="Chromatic Mantle of the Dawn" },
    [22639] = { "Удар Ешхандара", "Сповільнює рух цілі на {1}% та завдає {2} шкоди від кровотечі протягом {3} с.#movement by {1}% and#bleed for {2} damage over {3} sec", "Швидкість руху зменшено на {1}%. {2} шкоди від кровотечі кожні {3} с.#slowed by {1}%#for {2} damage every {3} sec", en="Eskhandar's Rake" },
    [22640] = { "Лють Ешхандара", ref=13494, en="Eskhandar's Rage" },
    [22641] = { "Безрозсудний ривок", "Здійснити у ворога ривок, що робить його недієздатним на {1} секунд. Також збиває вас з ніг, приголомшуючи на короткий час. Будь-яка шкода повертає ціль до тями.#for {1} sec", en="Reckless Charge" },
    [22642] = { "Сила бронзового роду", en="Brood Power: Bronze" },
    [22643] = { "Залп крижаних стріл", ref=12737, en="Frostbolt Volley" },
    [22645] = { "Крижаний спалах", "Вражає ворогів неподалік кригою, знерухомлюючи їх на {1} с.#immobilizing them for up to {1} sec", "Знерухомлено", en="Frost Nova" },
