    [23509] = { "Ревун Морозних Вовків", "Викликає та відпускає верхового ревуна Морозних Вовків. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Frostwolf Howler" },
