    [23684] = { "Аура синього дракона", "З шансом {1}% при успішному вимовленні закляття ви продовжите відновлювати ману зі швидкістю {2}% від звичайної під час вимовляння заклять протягом {3} с.#{1}% chance#allow {2}% of your Mana#casting for {3} sec", "Ваша мана відновлюється зі швидкістю {1}% від звичайної під час вимовляння заклять.#{1}% of your", en="Aura of the Blue Dragon" },
    [23686] = { "Удар блискавки", "Шанс вразити ціль ближнього бою блискавкою, що завдає [{1}#lightning for {1} Nature][від {1} до {2}#lightning for {1} to {2} Nature] шкоди від природи.", en="Lightning Strike" },
