    [23698] = { "Джерельна вода Альтерака", ref=18140, en="Alterac Spring Water" },
    [23701] = { "Підсвітня Крутоверть", "Надає власнику {1}% шанс воскреснути з {2}% здоров'я та мани.#wearer a {1}% chance#with {2}% health", en="Twisting Nether" },
    [23719] = { "Неприборкана лють", ref=17152, en="Untamed Fury" },
    [23720] = { "Благословення Чорної книги", "Підсилює вашого прислужника, збільшуючи його шкоду на {1}% та збільшуючи його броню на {2}% протягом {3} с. Ефект діє лише на біса, сукуба, інкуба, пустотника та скверногончу.#pet damage by {1}%#pet armor by {2}% for {3} sec", "Шкоду збільшено на {1}%.\nБроню збільшено на {2}%.#dealt is increased by {1}%#Armor is increased by {2}%", en="Blessing of the Black Book" },
    [23721] = { "Вливання аркани", "Наповнює вас енергією аркани, внаслідок чого наступне застосування \"Арканічного пострілу\" протягом {1} с підриває ціль. Акранічний вибух завдає [{1}#deal {1} damage][від {1} до {2}#deal {1} to {2} damage] шкоди ворогам поруч з ціллю.#within {1} sec", "Наступний \"Арканічний постріл\" спричинить акранічний вибух.", en="Arcane Infused" },
    [23723] = { "Прискорення думок", "Прискорює думки, збільшуючи швидкість вимови заклять на {1}% протягом {2} с.#casting speed by {1}% for {2} sec", "Швидкість вимови заклять збільшено на {1}%.#by {1}%", en="Mind Quickening" },
    [23724] = { "Руна метаморфози", "Зменшує витрати мани на зміну подоби на {1}% протягом {2} с.#forms by {1}% for {2} sec", "Витрати мани на зміну подоби зменшено на {1}%.#by {1}%", en="Metamorphosis Rune" },
    [23725] = { "Дар життя", "Зцілює вам {1}% від максимального запасу здоров'я та збільшує максимальний запас здоров'я на {2}% протягом {3} с.#yourself for {1}% of#health by {2}% for {3} sec", "Максимальний запас здоров'я збільшено на {1}%.#by {1}%", en="Gift of Life" },
    [23726] = { "Отруйний тотем", "Збільшує ймовірність спрацювання отрут на {1}% протягом {2} с.#target by {1}% for {2} sec", "Ймовірність спрацювання отрут збільшено на {1}%.#by {1}%", en="Venomous Totem" },
    [23727] = { "Шанс влучити заклинаннями {1}#Increased Spell Hit Chance {1}", "Збільшує шанс завдання удару заклинаннями на {1}%.#chance to hit with spells by {1}%", en="Increased Spell Hit Chance 1" },
    [23733] = { "Сліпуче світло", "Наповнює паладина енергією світла, збільшуючи швидкість атак ближнього бою на {1}% та збільшуючи швидкість вимови заклять на {2}% протягом {3} с.#attack speed by {1}%#casting speed by {2}% for {3} sec", "Швидкість атаки збільшено на {1}%.\nШвидкість вимови заклять збільшено на {2}%.#Attack speed increased by {1}%#Casting speed increased by {2}%", en="Blinding Light" },
    [23734] = { "Природний баланс", "Єднає шамана з природою, збільшуючи шкоду заклять на {1}%, збільшуючи ефективність зцілення на {2}% та збільшуючи витрати мани на закляття на {3}% протягом {4} с.#spell damage by {1}%#heal effects by {2}%#cost of spells by {3}% for {4} sec", "Шкоду заклять збільшено на {1}%.\nЕфективність зцілення збільшено на {2}%.\nВитрати мани збільшено на {3}%.#damage increased by {1}%#effects increased by {2}%#cost increased by {3}%", en="Nature Aligned" },
