    [23767] = { "Темне пророцтво Вщуна - броня", nil, "Збільшує броню на {1}%.#by {1}%", en="Sayge's Dark Fortune of Armor" },
    [23768] = { "Темне пророцтво Вщуна - шкода", nil, "Збільшує шкоду на 10%.", en="Sayge's Dark Fortune of Damage" },
    [23769] = { "Темне пророцтво Вщуна - опір", nil, "Збільшує всі опори магії на 25.", en="Sayge's Dark Fortune of Resistance" },
    [23780] = { "Егіда збереження", "Збільшує броню на {1} та зцілює {2} здоров'я щоразу, коли ви отримуєте шкоду в ближньому чи дальньому бою протягом {3} с.#armor by {1}#and heals {2} damage#for {3} sec", "Броню збільшено на {1}.\nЗцілює {2} здоров'я при отриманні шкоди в ближньому чи дальньому бою.#by {1}#Heals {2} damage", en="Aegis of Preservation" },
    [23784] = { "Майстер-демонолог", en="Master Demonologist" },
    [23785] = { "Майстер-демонолог", "Надає чорнокнижникові та його викликаному демонові певний ефект, поки цей демон активний.\n\nБіс - зменшує загрозу на {1}%.\n\nПустотник - зменшує отриману фізичну шкоду на {2}%.\n\nСукуб/інкуб - збільшує всю завдану шкоду на {3}%.\n\nСкверногонча - збільшує всі опори на {4} за кожен рівень.#threat caused by {1}%#taken by {2}%#damage caused by {3}%#resistances by {4} per", en="Master Demonologist" },
    [23786] = { "Потужна протиотрута", ref=7932, en="Powerful Anti-Venom" },
    [23795] = { "Збільшення відновлення мани", "Відновлює {1} мани кожні {2} с.#Restores {1} mana per {2} sec", en="Increased Mana Regen" },
    [23830] = { "Майстер-демонолог", en="Master Demonologist" },
    [23831] = { "Майстер-демонолог", en="Master Demonologist" },
    [23832] = { "Майстер-демонолог", en="Master Demonologist" },
    [23860] = { "Священний вогонь", "Ворога охоплює полум'я, що обпалює його та завдає додаткової шкоди від вогню кожні {1} с протягом {2} с.#every {1} sec#over {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Holy Fire" },
    [23861] = { "Отруйна хмара", "Завдає {1} шкоди від природи навколишнім ворогам кожні {2} с протягом {3} с.#Inflicts {1} Nature#every {2} sec#for {3} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Poison Cloud" },
    [23862] = { "Плювок отрути", "Плює у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Venom Spit" },
    [23865] = { "Змія-паразит", nil, "Завдає {1} шкоди кожні {2} с.#Deals {1} damage every {2} sec", en="Parasitic Serpent" },
    [23881] = { "Кровожерливість", "Миттєва атака цілі, що завдає шкоди в обсязі {1}% від вашої сили атаки. Крім цього, наступні {2} успішних атак ближнього бою відновлять {3} здоров'я. Ефект триває {4} с.#{1}% of your attack power#next {2} successful#restore {3} health#lasts {4} sec", en="Bloodthirst" },
    [23892] = { "Кровожерливість", "Миттєва атака цілі, що завдає шкоди в обсязі {1}% від вашої сили атаки. Крім цього, наступні {2} успішних атак ближнього бою відновлять {3} здоров'я. Ефект триває {4} с.#{1}% of your attack power#next {2} successful#restore {3} health#lasts {4} sec", en="Bloodthirst" },
    [23893] = { "Кровожерливість", "Миттєва атака цілі, що завдає шкоди в обсязі {1}% від вашої сили атаки. Крім цього, наступні {2} успішних атак ближнього бою відновлять {3} здоров'я. Ефект триває {4} с.#{1}% of your attack power#next {2} successful#restore {3} health#lasts {4} sec", en="Bloodthirst" },
    [23894] = { "Кровожерливість", "Миттєва атака цілі, що завдає шкоди в обсязі {1}% від вашої сили атаки. Крім цього, наступні {2} успішних атак ближнього бою відновлять {3} здоров'я. Ефект триває {4} с.#{1}% of your attack power#next {2} successful#restore {3} health#lasts {4} sec", en="Bloodthirst" },
    [23918] = { "Звуковий сплеск", "Завдає навколишнім ворогам від {1} до {2} шкоди та знемовлює їх на {3} с.#plus {1} to {2} on#for {3} sec", "Не може вимовляти закляття.", en="Sonic Burst" },
    [23919] = { "Наліт", "Завдає звичайної шкоди плюс {1} ворогам в конусі перед заклиначем, приголомшуючи їх на {2} с.#plus {1} to#for {2} sec", "Приголомшено.", en="Swoop" },
    [23920] = { "Відбиття заклинань", "Підняти щит, щоб відбити наступне закляття, вимовлене проти вас. Триває {1} с.#Lasts {1} sec", "Відбиває наступне направлене на вас закляття.", en="Spell Reflection" },
    [23922] = { "Трощення щитом", "Трощить ціль щитом, завдаючи від {1} до {2} шкоди, збільшеної від показника блоку щитом, та з ймовірністю {3}% розвіює 1 магічний ефект на цілі. Також спричиняє великий рівень загрози.[\n\nУраження цілі \"Трощенням щитом\" також збільшує вашу силу атаки на {1} за кожну одиницю вашої навички захисту понад {2}. Триває {3} секунд.#grants you {1} Attack Power for each point of your defense skill beyond {2}. Lasts {3} sec]#causing {1} to {2} damage#a {3}% chance", en="Shield Slam" },
    [23923] = { "Трощення щитом", "Трощить ціль щитом, завдаючи від {1} до {2} шкоди, збільшеної від показника блоку щитом, та з ймовірністю {3}% розвіює 1 магічний ефект на цілі. Також спричиняє великий рівень загрози.[\n\nУраження цілі \"Трощенням щитом\" також збільшує вашу силу атаки на {1} за кожну одиницю вашої навички захисту понад {2}. Триває {3} секунд.#grants you {1} Attack Power for each point of your defense skill beyond {2}. Lasts {3} sec]#causing {1} to {2} damage#a {3}% chance", en="Shield Slam" },
    [23924] = { "Трощення щитом", "Трощить ціль щитом, завдаючи від {1} до {2} шкоди, збільшеної від показника блоку щитом, та з ймовірністю {3}% розвіює 1 магічний ефект на цілі. Також спричиняє великий рівень загрози.[\n\nУраження цілі \"Трощенням щитом\" також збільшує вашу силу атаки на {1} за кожну одиницю вашої навички захисту понад {2}. Триває {3} секунд.#grants you {1} Attack Power for each point of your defense skill beyond {2}. Lasts {3} sec]#causing {1} to {2} damage#a {3}% chance", en="Shield Slam" },
    [23925] = { "Трощення щитом", "Трощить ціль щитом, завдаючи від {1} до {2} шкоди, збільшеної від показника блоку щитом, та з ймовірністю {3}% розвіює 1 магічний ефект на цілі. Також спричиняє великий рівень загрози.[\n\nУраження цілі \"Трощенням щитом\" також збільшує вашу силу атаки на {1} за кожну одиницю вашої навички захисту понад {2}. Триває {3} секунд.#grants you {1} Attack Power for each point of your defense skill beyond {2}. Lasts {3} sec]#causing {1} to {2} damage#a {3}% chance", en="Shield Slam" },
    [23930] = { "Печатка Світанку", "Збільшує силу атаки на {1} в бою з невмерлими. Також дозволяє отримувати камені Скари для Сріблястого Світанку.#+{1} Attack Power when", en="Seal of the Dawn" },
    [23931] = { "Громовий удар", "Завдає від {1} до {2} шкоди від природи навколишнім ворогам, збільшуючи інтервал між атаками на {3}% та зменшуючи швидкість руху на {4}% протягом {5} с.#Inflicts {1} to {2} Nature#attacks by {3}%#movement by {4}% for {5} sec", "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Thunderclap" },
    [23947] = { "Слово сили: Стійкість", "Сила наповнює ціль, збільшуючи її витривалість на {1} протягом {2} хв.#by {1} for {2} min", "Збільшує витривалість на {1}.#by {1}", en="Power Word: Fortitude" },
    [23948] = { "Слово сили: Стійкість", "Сила наповнює ціль, збільшуючи її витривалість на {1} протягом {2} хв.#by {1} for {2} min", "Збільшує витривалість на {1}.#by {1}", en="Power Word: Fortitude" },
    [23952] = { "Слово тіні: Біль", "Вимовляє слово темряви, що завдає ворогу шкоди тінню кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від тіні кожні {1} с.#every {1} sec", en="Shadow Word: Pain" },
    [23953] = { "Муки розуму", "Завдає ворогу шкоди від тіні та зменшує його швидкість руху протягом {1} с.#for {1} sec", "Завдає шкоди від тіні протягом {1} с.\nШвидкість руху зменшено.#over {1} sec", en="Mind Flay" },
    [23958] = { "Виснаження розуму", nil, "Не може використовувати сферу домінування.", en="Mind Exhaustion" },
