    [24610] = { "Зламана котушка Пеґла", "Збільшує ймовірність завдання удару закляттями на {1}% протягом {2} с.#spells by {1}% for {2} sec", "Ймовірність завдання удару закляттями збільшено на {1}%.#by {1}%", en="Pagle's Broken Reel" },
    [24611] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [24614] = { "Поглинання тіней", "Заклинач періодично завдає {1} шкоди ворогам в зоні ураження та зменшує їх швидкість руху на {1}%. Триває {2} с.#to {1}%#Lasts {2} sec", "Періодично завдає шкоди та сповільнює ворогів в зоні ураження.", en="Consuming Shadows" },
    [24615] = { "Поглинання тіней", nil, "Швидкість руху зменшено на {1}%.#by {1}%", en="Consuming Shadows" },
    [24618] = { "Висмоктування життя", "Висмоктує {1} здоров'я з ворога протягом {2} с, передаючи його заклиначу.#Drains {1} health#over {2} sec", "Висмоктування {1} здоров'я протягом {2} с.#{1} health#over {2} sec", en="Drain Life" },
    [24619] = { "Висмоктування душі", nil, "Спалення {1} мани кожні {2} с.\nНе може вимовляти закляття.#{1} mana#every {2} sec", en="Soul Tap" },
    [24629] = { "Природна броня", "Броню збільшено на {1}.#by {1}", en="Natural Armor" },
