    [24640] = { "Отрута скорпіда", "Завдає {1} шкоди від природи протягом {2} с. Ефект накопичується до {3} разів на одній цілі.#{1} Nature damage over {2} sec#{3} times", "{1} шкоди від природи кожні {2} с.#{1} Nature damage every {2} sec", en="Scorpid Poison" },
    [24648] = { "Опутуюче коріння", "Обплутує ворога корінням, завдаючи шкоди від природи кожні {1} с та знерухомлюючи його на {2} с.#every {1} sec#up to {2} sec", "Знерухомлено.\nЗавдає від {1} до {2} шкоди від природи кожні {3} с.#{1} to {2} Nature#every {3} sec", en="Entangling Roots" },
    [24658] = { "Нестабільна сила", "Збільшує шкоду заклять на {1}, а зцілення — на {2} протягом {3} с. Щоразу, коли ви вимовляєте закляття, цей бонус зменшується на {4} для шкоди та {5} для зцілення.#damage by up to {1} and your healing by up to {2} for {3} sec#by {4} spell damage and {5} healing", en="Unstable Power" },
    [24659] = { "Нестабільна сила", nil, "Шкоду заклять збільшено на {1}.\nЗцілення заклять збільшено на {2}.#damage increased by up to {1}#Healing increased by up to {2}", en="Unstable Power" },
    [24661] = { "Невгамовна сила", "Збільшує шкоду в ближньому та дальньому бою на {1} протягом {2} с. Щоразу, коли ви влучаєте в ціль, цей бонус зменшується на {3}.#damage by {1} for {2} sec#reduced by {3}", en="Restless Strength" },
    [24664] = { "Сон", "Змушує ворогів неподалік спати протягом {1} с. Будь-яка шкода розбудить ціль.#up to {1} sec", "Спить.", en="Sleep" },
    [24671] = { "Стрімкий копняк", "Завдає від {1} до {2} шкоди ворогу та приголомшує його на {3} с.#Inflicts {1} to {2} damage#for {3} sec", "Приголомшено.", en="Snap Kick" },
    [24673] = { "Прокляття крові", "Збільшує отриману ворогом фізичну шкоду на {1} протягом {2} хв.#by {1} for {2} min", "Отриману фізичну шкоду збільшено на {1}.#by {1}", en="Curse of Blood" },
