    [25821] = { "Ривок", "Ривок у ворога, що завдає звичайної шкоди плюс {1} та приголомшує ціль на {2} с.#plus {1} and#for {2} sec", en="Charge" },
    [25839] = { "Масове зцілення", nil, "Зцілює від {1} до {2} здоров'я кожні {3} с.#between {1} and {2} every {3} sec", en="Mass Healing" },
