    [26052] = { "Отруйна стріла", "Стріляє у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с.#every {1} sec", "Завдає від {1} до {2} шкоди від природи кожні {3} с.#Deals {1} to {2} nature#every {3} sec", en="Poison Bolt" },
    [26053] = { "Їдка отрута", nil, "Отримує {1} шкоди від природи кожні {2} с.\nНе може вимовляти закляття.#Deals {1} nature#every {2} sec", en="Noxious Poison" },
