    [26463] = { "Ртутний щит", "Збільшує опір закляттям на {1} протягом {2} хв. Кожен отриманий удар від закляття зменшує бонус опору на {3}.#spell resistances by {1} for {2} min#bonus is reduced by {3} resistance", en="Mercurial Shield" },
