    [26556] = { "Чума", nil, "Завдає шкоди від природи кожні {1} с.\nПеріодично завдає шкоди від природи навколишнім учасникам групи.#every {1} sec", en="Plague" },
    [26573] = { "Освячення", "Освячує землю під паладином, завдаючи {1} шкоди святістю протягом {2} с усім ворогам в зоні дії.#doing {1} Holy damage over {2} sec", "{1} шкоди щосекунди.#{1} damage", en="Consecration" },
    [26580] = { "Страх", "Вселяє страх у ворога, змушуючи його тікати зі страху протягом {1} с. Одночасно лише одна ціль може бути наляканою.#for up to {1} sec", "Втікає зі страху.", en="Fear" },
    [26590] = { "Виклик отруйної хмари", "Завдає {1} шкоди від природи навколишнім ворогам кожні {2} с протягом {3} хв.#Inflicts {1} Nature#every {2} sec#for {3} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Summon Poison Cloud" },
    [26601] = { "Отруйна стріла", "Стріляє у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison Bolt" },
