    [26613] = { "Вибиття з рівноваги", "Завдає {1}% шкоди від зброї та вибиває ціль з рівноваги, зменшуючи її навичку захисту на {2} протягом {3} с.#Inflicts {1}%#by {2} for {3} sec", "Навичку рівноваги зменшено на {1}.#by {1}", en="Unbalancing Strike" },
