    [27039] = { "Збільшення здоров'я вихованця +{1}%#Pet Health +{1}%", "Збільшує запас здоров'я вашого вихованця на {1}%.#your pet's maximum health by {1}%", en="Increased Pet Health +3%" },
    [27042] = { "Збільшення крит шансу вихованця +{1}%#Pet Crit +{1}%", "Збільшує ймовірність критичного удару вашого вихованця на {1}%.#your pet's critical strike chance by {1}%", "Ймовірність критичного удару збільшено.", en="Increased Pet Crit +2%" },
    [27043] = { "Збільшення крит шансу вихованця +{1}%#Pet Crit +{1}%", "Збільшує ймовірність критичного удару вашого вихованця на {1}%.#your pet's critical strike chance by {1}%", en="Increased Pet Crit +2%" },
    [27177] = { "Осквернення", nil, "Вас оскверняють...", en="Defile" },
    [27205] = { "Збільшення шкоди вихованця +{1}%#Pet Damage +{1}%", "Збільшує шкоду вашого вихованця на {1}%.#pet's damage by {1}%", "Збільшує шкоду вашого вихованця на {1}%.#damage by {1}%", en="Increased Pet Damage +3%" },
    [27206] = { "Збільшення шкоди вихованця +{1}%#Pet Damage +{1}%", "Збільшує шкоду вашого вихованця на {1}%.#by your pet by {1}%", en="Increased Pet Damage +3%" },
    [27208] = { "Збільшення броні вихованця +{1}%#Pet Armor +{1}%", "Збільшує броню вашого вихованця на {1}%.#your pet's armor by {1}%", "Броню збільшено.", en="Increased Pet Armor +10%" },
    [27225] = { "Збільшення броні вихованця +{1}%#Pet Armor +{1}%", "Збільшує броню вашого вихованця на {1}%.#your pet's armor by {1}%", en="Increased Pet Armor +10%" },
    [27420] = { "Ектоплазматичний дистилятор", "Ектоплазматичний дистилятор дозволяє збирати ектоплазму з безтілесної нежиті.", "Ектоплазматичний дистилятор дозволяє збирати ектоплазму з безтілесної нежиті.", en="Ectoplasmic Distiller" },
    [27433] = { "Ектоплазматичний дистилятор", "Розмістити ектоплазматичний дистилятор на землі, що дозволить збирати ектоплазму. Працює на гоблінському ракетному паливі.", en="Ectoplasmic Distiller" },
    [27499] = { "Гнів лицаря", "Збільшує шкоду і зцілення від магічних заклинань і ефектів на {1}.#magical spells and effects by up to {1}", "Магічну шкоду та зцілення збільшено на {1}.#increased by {1}", en="Crusader's Wrath" },
    [27518] = { "Зменшення шкоди від заклять", "Зменшує отриману шкоду від заклять на {1}.#reduced by {1}", en="Spell Damage Reduction" },
    [27551] = { "Деморалізуючий рев", "Зменшує силу атаки ближнього бою навколишніх ворогів на {1} протягом {2} с.#enemies by {1} for {2} sec", "Силу атаки ближнього бою зменшено на {1}.#by {1}", en="Demoralizing Roar" },
    [27556] = { "Розрив", "Рве ціль, завдаючи від {1} до {2} шкоди та додатково {3} шкоди протягом {4} с.#for {1} to {2} damage#additional {3} damage over {4} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rake" },
    [27559] = { "Знемовлення", "Знемовлює ворога, запобігаючи вимові заклять на {1} с.#spells for {1} sec", "Не може вимовляти закляття.", en="Silence" },
    [27565] = { "Вигнання", "Виганяє ворога до іншого виміру, перешкоджаючи всім його діям, але при цьому робить його невразливим протягом {1} с. Одночасно лише одна ціль може бути вигнаною.#for up to {1} sec", "Невразливість до всіх атак та заклять, але неможливо виконувати будь-які дії.", en="Banish" },
    [27580] = { "Смертельний удар", "Жорстокий удар, що завдає шкоди від зброї плюс {1} і ранить ціль, зменшуючи ефективність будь-якого зцілення на {2}% протягом {3} с.#damage plus {1}#healing by {2}% for {3} sec", "Ефективність зцілення зменшено на {1}%.#reduced by {1}%", en="Mortal Strike" },
    [27584] = { "Нівечення", "Калічить ворога, завдаючи {1} шкоди та зменшуючи швидкість руху на {2}% протягом {3} с.#causing {1} damage#movement by {2}% for {3} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Hamstring" },
    [27603] = { "Гоблінська гармата-дракон", "Завдає [{1}#Deals {1} fire][від {1} до {2}#Deals {1} to {2} fire] шкоди вогнем протягом {1} с всім ворогам в конусі перед інженером. Це якщо вона не вибухне...#damage for {1} sec to all", "Завдає [{1}#Dealing {1} fire][від {1} до {2}#Dealing {1} to {2} fire] шкоди вогнем кожні {1} с.#every {1} sec", en="Goblin Dragon Gun" },
    [27616] = { "Міжвимірний шукач привидів", "Дозволяє носію бачити привидів нещодавно померлих.", "Дозволяє носію бачити привидів нещодавно померлих.", en="Extra-Dimensional Ghost Revealer" },
    [27617] = { "Зникнення", "Дозволяє пройдисвіту зникнути з поля зору ворогів, увійшовши в стан покращеної непомітності на {1} с. Також знімає всі ефекти обмеження руху.#for {1} sec", "Покращена непомітність.", en="Vanish" },
    [27634] = { "Запаморочливий постріл", "Паморочить ціль, зменшуючи її швидкість руху на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Concussive Shot" },
    [27635] = { "Блискавковий щит", "Кидає в ціль блискавку, що завдає {1} шкоди від природи.#for {1} Nature", en="Lightning Shield" },
    [27638] = { "Розрив", "Рве ціль, завдаючи від {1} до {2} шкоди та додатково {3} шкоди протягом {4} с.#for {1} to {2} damage#additional {3} damage over {4} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rake" },
    [27641] = { "Страх", "Вселяє страх у ворога, змушуючи його тікати зі страху протягом {1} с. Одночасно лише одна ціль може бути наляканою.#for {1} sec", "Втікає зі страху.", en="Fear" },
    [27648] = { "Громолють", nil, "Швидкість атаки зменшено на {1}%.#by {1}%", en="Thunderfury" },
    [27652] = { "Еліксир опору", "Збільшує опір всім видам магії на {1} протягом {2} хв.#resistances by {1} for {2} min", "Опір магії збільшено на {1}.#by {1}", en="Elixir of Resistance" },
    [27653] = { "Еліксир ухилення", "Збільшує шанс ухилення на {1}% протягом {2} хв.#dodge by {1}% for {2} min", "Ймовірність ухилення збільшено на {1}%.#by {1}%", en="Elixir of Dodging" },
    [27656] = { "Полум'яний батіг", "Шанс окутати ціль ближнього бою полум'ям, завдаючи [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем.", en="Flame Lash" },
    [27675] = { "Хроматичне насичення", "Збільшує шкоду заклять на {1}, а силу зцілення - на {2} протягом {3} с.#damage by up to {1} and#healing by up to {2} for {3} sec", "Шкоду заклять збільшено на {1}.\nСилу зцілення збільшено на {2}.#damage increased by up to {1}#Healing increased by up to {2}", en="Chromatic Infusion" },
    [27681] = { "Молитва духу", "Сила наповнює учасників групи цілі, збільшуючи їхній дух на {1} протягом {2} год.#by {1} for {2} h", "Збільшує дух на {1}.#by {1}", en="Prayer of Spirit" },
    [27683] = { "Молитва захисту від тіні", "Сила наповнює учасників групи цілі, збільшуючи їхній опір тіні на {1} протягом {2} хв.#by {1} for {2} min", "Збільшує опір тіні на {1}.#by {1}", en="Prayer of Shadow Protection" },
    [27685] = { "Ривок", "Ривок у ворога, що знерухомлює його на {1} с і додає {2} сили атаки ближнього бою до наступної атаки кнура.#for {1} sec#adds {2} melee", en="Charge" },
    [27720] = { "Молочна насолода", "Збільшує навичку захисту на {1} протягом {2} год.#Defense by {1} for {2} hour", "Навичку захисту збільшено на {1}.#by {1}", en="Buttermilk Delight" },
    [27721] = { "Дуже ягідний крем", "Збільшує шкоду заклять на {1} протягом {2} год.#spells by up to {1} for {2} hour", "Шкоду заклять збільшено на {1}.#to {1}", en="Very Berry Cream" },
    [27722] = { "Солодкий сюрприз", "Збільшує зцілення заклять на {1} протягом {2} год.#spells by up to {1} for {2} hour", "Зцілення заклять збільшено на {1}.#to {1}", en="Sweet Surprise" },
    [27723] = { "Темна жага", "Збільшує ймовірність завдання удару на {1}% протягом {2} год.#hit by {1}% for {2} hour", "Ймовірність завдання удару збільшено на {1}%.#by {1}%", en="Dark Desire" },
    [27737] = { "Місячний вогонь", "Обпалює ворога, завдаючи шкоди арканою та додатково шкоди протягом {1} с.#over {1} sec", "Отримання шкоди від аркани кожні {1} с.#every {1} sec", en="Moonfire" },
    [27743] = { "Збільшення навички рушниць", "Збільшує навичку володіння рушницями на {1}.#Guns +{1}", en="Increased Gun" },
    [27744] = { "Збільшення навички володіння арбалетами", "Збільшує навичку володіння арбалетами на {1}.#Crossbows +{1}", en="Increased Crossbow" },
    [27746] = { "Азотне прискорення", "10 мани щосекунди. Збільшує швидкість руху на 50%.", "Швидкість руху збільшено на 50%.", en="Nitrous Boost" },
    [27753] = { "Заморожувальна пастка", "Встановити крижану пастку, яка заморозить першого ворога при наближенні та унеможливить всі його дії впродовж {1} с. Будь-яка шкода розіб'є лід. Пастка існуватиме {2} хв. Пастки можна встановлювати лише поза боєм. Одночасно може бути активною лише одна пастка.#action for up to {1} sec#exist for {2} min", en="Freezing Trap" },
    [27759] = { "Генератор щита", "Захищає вас щитом мани, який може поглинути до {1} шкоди. За кожну одиницю отриманої шкоди витрачається дві одиниці мани.#up to {1} damage", en="Shield Generator" },
    [27760] = { "Поліморфія", "Перетворює ворога на вівцю, змушуючи його блукати до {1} с. Вівця не здатна атакувати та вимовляти закляття, але дуже швидко відновлює здоров'я. Будь-яка шкода поверне ціль до нормального стану. Одночасно лише одна ціль може бути під ефектом \"Поліморфії\". Діє лише на звірів, драконів, велетнів, гуманоїдів і звіряток.#up to {1} sec", "Не може атакувати та вимовляти закляття.\nШвидкість регенерації здоров'я збільшено.", en="Polymorph" },
    [27762] = { "Рукопис", en="Libram" },
    [27763] = { "Тотем", en="Totem" },
    [27764] = { "Фетиш", en="Fetish" },
    [27775] = { "Шалений шторм", "Збільшує шкоду і зцілення від магічних заклинань і ефектів на {1}.#magical spells and effects by up to {1}", "Магічну шкоду та зцілення збільшено на {1}.#increased by {1}", en="The Furious Storm" },
    [27780] = { "Викривлений страх", "При отриманні удару в бою ви можете налякати нападника, змушуючи його втікати протягом 2 секунд.", en="Corrupted Fear" },
    [27789] = { "Досяжність святості", "Збільшує дальність дії ваших заклять \"Кара\" та \"Священний вогонь\", а також радіус дії ваших заклять \"Молитва зцілення\" та \"Священний спалах\" на {1}%.#by {1}%", en="Holy Reach" },
    [27794] = { "Розсічення", "Завдає звичайної шкоди плюс {1} ворогу та його союзникам неподалік, вражаючи до {2} цілей.#plus {1} to#up to {2} target", en="Cleave" },
    [27799] = { "Священний спалах", "Створює вибух священного світла навколо заклинача, завдаючи від {1} до {2} шкоди святістю ворожим цілям в радіусі {3} м і зцілюючи від {5} до {6} здоров'я учасникам групи в межах {4} м. Ці ефекти не спричиняють загрози.#causing {1} to {2} Holy#targets within {3} y#members within {4} yards for {5} to {6}", en="Holy Nova" },
    [27800] = { "Священний спалах", "Створює вибух священного світла навколо заклинача, завдаючи від {1} до {2} шкоди святістю ворожим цілям в радіусі {3} м і зцілюючи від {5} до {6} здоров'я учасникам групи в межах {4} м. Ці ефекти не спричиняють загрози.#causing {1} to {2} Holy#targets within {3} y#members within {4} yards for {5} to {6}", en="Holy Nova" },
    [27801] = { "Священний спалах", "Створює вибух священного світла навколо заклинача, завдаючи від {1} до {2} шкоди святістю ворожим цілям в радіусі {3} м і зцілюючи від {5} до {6} здоров'я учасникам групи в межах {4} м. Ці ефекти не спричиняють загрози.#causing {1} to {2} Holy#targets within {3} y#members within {4} yards for {5} to {6}", en="Holy Nova" },
    [27806] = { "Плювок отрути", "Плює у ворога отрутою, завдаючи шкоди від природи.", en="Venom Spit" },
    [27811] = { "Благословенне відновлення", "Після отримання критичного удару в ближньому чи дальньому бою ви зцілюєтесь на {1}% від отриманої шкоди протягом {2} с .#heal {1}%#over {2} sec", en="Blessed Recovery" },
    [27813] = { "Благословенне відновлення", "Зцілює ціль протягом {1} с.#over {1} sec", "Зцілює {1}% від нещодавно отриманого критичного удару протягом {2} с.#Heals {1}% of#over {2} sec", en="Blessed Recovery" },
    [27827] = { "Дух спокути", nil, "Ваша могутність незбагеннна.", en="Spirit of Redemption" },
    [27828] = { "Зосереджена вимова", "При застосуванні ви не зазнаєте затримки вимови заклять при отриманні шкоди. Діє {1} секунд.#Lasts {1} sec", "Не зазнає затримки вимови заклять при отриманні шкоди та має збільшену на {1}% ймовірність протистояти ефектам переривання.#by {1}%", en="Focused Casting" },
    [27839] = { "Покращені вампірські обійми", "Збільшує долю зцілення вашого закляття \"Вампірські обійми\" від шкоди ще на {1}%.#additional {1}%", en="Improved Vampiric Embrace" },
    [27841] = { "Божественний дух", "Свята сила наповнює ціль, збільшуючи її дух на {1} протягом {2} хв.#by {1} for {2} min", "Збільшує дух на {1}.#by {1}", en="Divine Spirit" },
    [27846] = { "Прискорена вимова Цілющого дотику", "Зменшує час вимови закляття \"Цілющий дотик\" на {1} с.#spell by {1} sec", en="Faster Healing Touch Cast" },
    [27851] = { "Зменшення витрат на Дряпання та Роздирання", "Зменшує витрати енергії на здібності \"Дряпання\" та \"Роздирання\" на {1}.#Rake by {1}", en="Reduced Claw and Rake Cost" },
    [27855] = { "Посилення малої хвилі зцілення", "Збільшує зцілення від \"Малої хвилі зцілення\" на {1}.#Lesser Healing Wave by up to {1}", en="Increased Lesser Healing Wave" },
    [27859] = { "Збільшення шкоди шоків", "Збільшує шкоду \"Земного шоку\", \"Вогняного шоку\" та \"Крижаного шоку\" на {1}.#and Frost Shock by up to {1}", en="Increased Shock Damage" },
    [27861] = { "Ультиматум барона", "Ваше вторгнення помічено бароном Рівендером. Його в'язню жити лишилося недовго.", "Ваше вторгнення помічено бароном Рівендером. Його в'язню жити лишилося недовго.", en="The Baron's Ultimatum" },
    [27863] = { "Ультиматум барона", "Ваше вторгнення помічено бароном Рівендером. Його в'язню жити лишилося недовго.", "Ваше вторгнення помічено бароном Рівендером. Його в'язню жити лишилося недовго.", en="The Baron's Ultimatum" },
    [27864] = { "Ультиматум барона", "Ваше вторгнення помічено бароном Рівендером. Його в'язню жити лишилося недовго.", "Ваше вторгнення помічено бароном Рівендером. Його в'язню жити лишилося недовго.", en="The Baron's Ultimatum" },
    [27865] = { "Ультиматум барона", "Ваше вторгнення помічено бароном Рівендером. Його в'язню жити лишилося недовго.", "Ваше вторгнення помічено бароном Рівендером. Його в'язню жити лишилося недовго.", en="The Baron's Ultimatum" },
    [27867] = { "Заморозка", "При отриманні удару в бою ви можете приморозити нападника на {1} с.#attacker in place for {1} sec", en="Freeze" },
    [27869] = { "Темна руна", ref=16666, en="Dark Rune" },
    [27870] = { "Колодязь світла", "Створює священний колодязь світла біля жерця. Учасники вашої групи чи рейду можуть випити з нього щоб відновити {1} здоров'я протягом {2} с. Будь-яка отримана шкода знімає цей ефект. Колодязь існує {3} хв або до {4} застосувань.#restore {1} health over {2} sec#lasts for {3} min or {4} charges", en="Lightwell" },
    [27871] = { "Колодязь світла", "Створює священний колодязь світла біля жерця. Учасники вашої групи чи рейду можуть випити з нього щоб відновити {1} здоров'я протягом {2} с. Будь-яка отримана шкода знімає цей ефект. Колодязь існує {3} хв або до {4} застосувань.#restore {1} health over {2} sec#lasts for {3} min or {4} charges", en="Lightwell" },
    [27873] = { "Відновлення колодязя світла", nil, "Відновлює {1} здоров'я кожні {2} с.#{1} health every {2} sec", en="Lightwell Renew" },
    [27874] = { "Відновлення колодязя світла", nil, "Відновлює {1} здоров'я кожні {2} с.#{1} health every {2} sec", en="Lightwell Renew" },
    [27900] = { "Охорона від чар", "Зменшує всю отриману шкоду від заклять на {1}%.#by {1}%", en="Spell Warding" },
    [27990] = { "Страх", "Вселяє страх у ворога, змушуючи його тікати зі страху протягом {1} с. Одночасно лише одна ціль може бути наляканою.#for {1} sec", "Втікає зі страху.", en="Fear" },
    [27991] = { "Розкол броні", "Розколює броню ворога, зменшуючи її на {1} за кожен ефект \"Розколу броні\". Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено.", en="Sunder Armor" },
    [27994] = { "Висмоктування життя", "Висмоктує {1} здоров'я з ворога протягом {2} с, передаючи його заклиначу.#Drains {1} health#over {2} sec", "Висмоктування {1} здоров'я протягом {2} с.#{1} health#over {2} sec", en="Drain Life" },
    [28006] = { "Арканічний покрив", en="Arcane Cloaking" },
    [28125] = { "Бойовий тупіт", "Відкидає навколишніх ворогів.", en="War Stomp" },
    [28131] = { "Несамовитість", "Збільшує швидкість атаки заклинача на {1}% та збільшує фізичну шкоду на {2} протягом {3} хв.#speed by {1}%#deals by {2} for {3} min", "Фізичну шкоду збільшено на {1}.\nШвидкість атаки збільшено на {2}%.#dealt is increased by {1}#speed increased by {2}%", en="Enrage" },
    [28142] = { "Сила Вартівника", "Збільшує ймовірність завдання критичного удару закляттями для всіх учасників групи в межах {1} м на {2}%.#members within {1} yards by {2}%", "Збільшує ймовірність завдання критичного удару закляттями на {1}%.#by {1}%", en="Power of the Guardian" },
    [28143] = { "Сила Вартівника", "Збільшує шкоду і зцілення магічних заклинань і ефектів для всіх учасників групи в межах {1} м на {2}.#members within {1} yards by up to {2}", "Шкоду і зцілення магічних заклинань і ефектів збільшено на {1}.#by up to {1}", en="Power of the Guardian" },
    [28144] = { "Сила Вартівника", "Збільшує зцілення від магічних заклинань і ефектів для всіх учасників групи в межах {1} м на {2}.#members within {1} yards by up to {2}", "Зцілення від магічних заклинань і ефектів збільшено на {1}.#by up to {1}", en="Power of the Guardian" },
    [28145] = { "Сила Вартівника", "Відновлює {1} мани кожні {2} с всім учасникам групи в межах {3} м.#Restores {1} mana per {2} seconds#within {3} yards", "Відновлює {1} мани кожні {2} с.#Restores {1} mana per {2} sec", en="Power of the Guardian" },
    [28148] = { "Портал: Каражан", "Створює портал, що телепортує учасників групи до Каражану при використанні.", en="Portal: Karazhan" },
    [28150] = { "Копія збільшення зцілення {1}#Increase Healing {1}", ref=7675, en="Copy of Increase Healing 187" },
    [28155] = { "Шкода/зцілення Атієша жерця", "Збільшує шкоду заклять на {1}, а зцілення - на {2}.#damage by up to {1} and#healing by up to {2}", "Шкоду заклять збільшено на {1}.\nЗцілення збільшено на {2}.#damage increased by {1}#Healing increased by {2}", en="Atiesh Priest Damage/Healing" },
    [28161] = { "Захист джунглів", "Додати на поножі або головний убір чари, що збільшують опір природі на {1}. Не поєднується з іншими чарами на предметі.#adds {1} nature resistance", en="Savage Guard" },
    [28163] = { "Крижаний захист", "Додати на поножі або головний убір чари, що збільшують опір кризі на {1}. Не поєднується з іншими чарами на предметі.#adds {1} frost resist", en="Ice Guard" },
    [28165] = { "Тіньовий захист", "Додати на поножі або головний убір чари, що збільшують опір тіні на {1}. Не поєднується з іншими чарами на предметі.#adds {1} shadow resistance", en="Shadow Guard" },
    [28200] = { "Вознесіння", "Протягом {2} с наступні {1} бойових чи цілющих заклинань збільшать вашу шкоду від заклинань на {3}, а зцілення - на {4}. Ефект накопичується до {5} разів, а його дія закінчується після {6} заклинань або через {7} с.#next {1} damage or#within {2} sec#up to {3} damage and up to {4} healing#stacking up to {5} times#Expires after {6} damage or healing spells or {7} sec", "Наступні {1} бойових чи цілющих заклинань збільшать шкоду та зцілення від заклинань.#Next {1} damage", en="Ascendance" },
    [28204] = { "Вознесіння", nil, "Шкоду заклять збільшено на {1}.\nСилу зцілення збільшено на {2}.#damage increased by up to {1}#Healing increased by up to {2}", en="Ascendance" },
    [28270] = { "Поліморфія: Корова", "Перетворює ворога на корову, змушуючи його блукати до {1} с. Корова не здатна атакувати або вимовляти закляття, але дуже швидко відновлює здоров'я. Будь-яка шкода поверне ціль до нормального стану. Одночасно лише одна ціль може бути під ефектом \"Поліморфії\". Діє лише на звірів, гуманоїдів і звіряток.#up to {1} sec", "Не може атакувати та вимовляти закляття. Прискорене відновлення здоров'я.", en="Polymorph: Cow" },
    [28271] = { "Поліморфія", "Перетворює ворога на черепаху, змушуючи його блукати до {1} с. Черепаха не здатна атакувати або вимовляти закляття, але дуже швидко відновлює здоров'я. Будь-яка шкода поверне ціль до нормального стану. Одночасно лише одна ціль може бути під ефектом \"Поліморфії\". Діє лише на звірів, гуманоїдів і звіряток.#up to {1} sec", "Не може атакувати та вимовляти закляття. Прискорене відновлення здоров'я.", en="Polymorph" },
    [28272] = { "Поліморфія", "Перетворює ворога на свиню, змушуючи його блукати до {1} с. Свиня не здатна атакувати або вимовляти закляття, але дуже швидко відновлює здоров'я. Будь-яка шкода поверне ціль до нормального стану. Одночасно лише одна ціль може бути під ефектом \"Поліморфії\". Діє лише на звірів, гуманоїдів і звіряток.#up to {1} sec", "Не може атакувати та вимовляти закляття. Прискорене відновлення здоров'я.", en="Polymorph" },
    [28282] = { "Спопелитель", "Підкоряє власника волі Спопелителя.", "Підкоряє власника волі Спопелителя.", en="Ashbringer" },
    [28310] = { "Муки розуму", "Завдає ворогу шкоди від тіні та зменшує його швидкість руху протягом {1} с.#for {1} sec", "Завдає шкоди від тіні протягом {1} с.\nШвидкість руху зменшено.#over {1} sec", en="Mind Flay" },
