    [28334] = { "Вихор", "Атакує навколишніх ворогів сталевим вихром протягом {1} с, завдаючи звичайної шкоди плюс {2}.#lasts {1} sec#plus {2}", "Атакує навколишніх ворогів, завдаючи звичайної шкоди плюс {1}.#plus {1}", en="Whirlwind" },
    [28347] = { "Просторова воронка", "Збільшує силу атаки ближнього та дальнього бою на {1}.#attack power by {1}", "Збільшує силу атаки ближнього та дальнього бою на {1}. Власник отримує шкоду в обсязі {2}% від максимального запасу здоров'я щосекунди, якщо не є злою міжпросторовою сутністю#attack power by {1}#takes {2}%", en="Dimensional Siphon" },
    [28371] = { "Оскаженіння", nil, "Швидкість атаки збільшено на {1}%.\nШкоду збільшено на {2}%.#speed increased by {1}%#Damage increased by {2}%", en="Frenzy" },
