    [28610] = { "Тіньовий оберіг", "Поглинає {1} шкоди від тіні. Триває {2} с.#Absorbs {1}#Lasts {2} sec", "Поглинає шкоду від тіні.", en="Shadow Ward" },
    [28612] = { "Начаклування їжі", "Начаклувати кекси ({1} шт.), щоб забезпечити мага та союзників їжею.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {2} хв.#Conjures {1} muffins#than {2} min", en="Conjure Food" },
    [28616] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
