    [28701] = { "Прискорення", "Збільшує вашу швидкість атаки на {1}% протягом {2} с.#speed by {1}% for {2} sec", "Швидкість атаки збільшено.", en="Haste" },
    [28725] = { "Бойовий тупіт", "Завдає звичайної шкоди плюс {1} навколишнім ворогам, відкидаючи їх та приголомшуючи на {2} с.#plus {1} to#for {2} sec", "Приголомшено.", en="War Stomp" },
    [28747] = { "Несамовитість", "Збільшує швидкість атаки заклинача на {1}% та збільшує фізичну шкоду на {2} протягом {3} хв.#speed by {1}%#deals by {2} for {3} min", "Фізичну шкоду збільшено на {1}.\nШвидкість атаки збільшено на {2}%.#dealt is increased by {1}#speed increased by {2}%", en="Enrage" },
