    [28854] = { "Покращений Місячний вогонь", "Збільшує шкоду \"Місячного вогню\" на {1}.#Moonfire spell by up to {1}", en="Improved Moonfire" },
    [28855] = { "Зменшення витрат на Терзання та Розмах", "Зменшує витрати люті здібностей \"Терзання\" та \"Розмах\" на {1}.#Swipe by {1}", en="Reduced Maul and Swipe Cost" },
    [28857] = { "Збільшення шкоди Блискавки", "Збільшує шкоду \"Ланцюгової блискавки\" та \"Блискавки\" на {1}.#and Lightning Bolt by up to {1}", en="Increased Lightning Damage" },
