    [28888] = { "Копія Вбивці невмерлих {1}#Undead Slayer {1}", ref=12981, en="Copy of Undead Slayer 108" },
    [28891] = { "Освячена зброя", "При застосуванні до зброї збільшує силу атаки на {1} в бою з невмерлими. Триває {2} год.#undead by {1}#Lasts for {2} h", en="Consecrated Weapon" },
    [28898] = { "Благословенна чарівна олія", "При застосуванні до зброї збільшує шкоду заклять на {1} в бою з невмерлими. Триває {2} год.#undead by up to {1}#Lasts for {2} h", en="Blessed Wizard Oil" },
    [28969] = { "Плювок кислоти", "Завдає ворогу шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", ref=744, en="Acid Spit" },
    [28996] = { "Оберіг стихій", "Зменшує отриману шкоду від ефектів вогню, криги та природи на {1}%.#by {1}%", en="Elemental Warding" },
    [29007] = { "Напій", "Відновлює {1} мани протягом {2} с. Потрібно залишатися в сидячому положенні під час пиття.#Restores {1} mana over {2} sec", "Відновлює {1} мани щосекунди.#Restores {1} mana", en="Drink" },
    [29008] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [29029] = { "Шипучий енергетичний напій", "Відновлює {1} здоров'я та {2} мани протягом {3} с. Потрібно залишатися в сидячому положенні під час їжі. Через 10 секунд ви насититесь і будете відновлювати {4} мани кожні 5 секунд протягом {5} хв#Restores {1} health and {2} mana over {3} sec#gain {4} Mana#for {5} min", "Відновлює {1} мани щосекунди.#Restores {1} mana", ref=25690, en="Fizzy Energy Drink" },
    [29041] = { "Смачні літні ласощі", "Такі смачні, що ви будете сяяти.", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Tasty Summer Treat" },
    [29055] = { "Освіжаюче червоне яблуко", ref=24707, en="Refreshing Red Apple" },
    [29059] = { "Скакун-скелет", "Викликає та відпускає скакуна-скелета. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Skeletal Steed" },
    [29062] = { "Око бурі", "Після отримання критичного удару в ближньому чи дальньому бою ви з ймовірністю {1}% отримаєте ефект \"Зосередженої вимови\" на {2} с. \"Зосереджена вимова\" оберігає вас від затримки вимови заклять при отриманні шкоди.#a {1}% chance#for {2} sec", en="Eye of the Storm" },
    [29073] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [29074] = { "Майстер стихій", "Ваші критичні удари закляттями вогню та криги повернуть {1}% від базових витрат мани на них.#refund {1}%", en="Master of Elements" },
    [29082] = { "Опанування зброї", "Збільшує шкоду зброї на {1}%.#by {1}%", en="Weapon Mastery" },
    [29084] = { "Опанування зброї", "Збільшує шкоду зброї на {1}%.#by {1}%", en="Weapon Mastery" },
    [29086] = { "Опанування зброї", "Збільшує шкоду зброї на {1}%.#by {1}%", en="Weapon Mastery" },
    [29087] = { "Опанування зброї", "Збільшує шкоду зброї на {1}%.#by {1}%", en="Weapon Mastery" },
    [29088] = { "Опанування зброї", "Збільшує шкоду зброї на {1}%.#by {1}%", en="Weapon Mastery" },
    [29112] = { "Чемпіон Світанку", "Збільшує силу атаки на {1} в бою з невмерлими та демонами. Також дозволяє отримувати камені Скари для Сріблястого Світанку.#+{1} Attack Power when", en="Champion of the Dawn" },
    [29113] = { "Чемпіон Світанку", "Збільшує шкоду від магічних заклинань і ефектів в бою з невмерлими та демонами на {1}. Також дозволяє отримувати камені Скари для Сріблястого Світанку.#up to {1}", en="Champion of the Dawn" },
    [29124] = { "Поліморфія", nil, "Не може атакувати та вимовляти закляття.\nШвидкість регенерації збільшено.", en="Polymorph" },
    [29131] = { "Кривава лють", nil, "Додає {1} люті щосекунди.#Generating {1}", en="Bloodrage" },
    [29140] = { "Живість", "Збільшує вашу витривалість на {1}%.#by {1}%", en="Vitality" },
    [29150] = { "Електричний розряд", "Шанс викликати електричний розряд, що завдасть [{1}#causing {1} Nature][від {1} до {2}#causing {1} to {2} Nature] шкоди від природи вашій цілі.", en="Electric Discharge" },
    [29151] = { "Електричний розряд", "Електричний розряд, що завдає [{1}#for {1} Nature][від {1} до {2}#for {1} to {2} Nature] шкоди від природи.", en="Electric Discharge" },
    [29155] = { "Висмоктування життя", "Викрадає від {1} до {2} здоров'я у ворожої цілі.#Steals {1} to {2} life", en="Drain Life" },
    [29162] = { "Химерна хватка", "При отриманні удару, ви з ймовірністю {1}% сповільните нападника на {2}% протягом {3} с.#struck has a {1}% chance#speed by {2}% for {3} sec", en="Stygian Grasp" },
    [29164] = { "Химерна хватка", nil, "Швидкість руху зменшено на {1}%.#by {1}%", en="Stygian Grasp" },
    [29166] = { "Осяяння", "Прискорює відновлення мани цілі на {1}% і дозволяє відновлювати ману під час вимови заклять зі швидкістю {2}% від звичайної. Триває {3} с.#by {1}% and allows {2}%#Lasts {3} sec", "Відновлення мани прискорено на {1}% та продовжується під час вимови заклять зі швидкістю {2}% від звичайної.#increased by {1}#{2}% Mana", en="Innervate" },
    [29168] = { "Страх", "Вселяє страх у ворога, змушуючи його тікати зі страху протягом {1} с. Одночасно лише одна ціль може бути наляканою.#for {1} sec", "Втікає зі страху.", en="Fear" },
    [29175] = { "Танець зі стрічками", "Збільшує опір вогню на {1}.#by {1}", "Збільшує опір вогню на {1}.#by {1}", en="Ribbon Dance" },
    [29189] = { "Цілюще благовоління", "Зменшує загрозу від ваших заклять зцілення на {1}%.#by {1}%", en="Healing Grace" },
    [29191] = { "Цілюще благовоління", "Зменшує загрозу від ваших заклять зцілення на {1}%.#by {1}%", en="Healing Grace" },
    [29192] = { "Покращені тотеми зброї", "Збільшує бонус до сили атаки ближнього бою від вашого тотему буревію на {1}%, а шкоду вашого тотема язика полум'я на {2}%.#Windfury Totem by {1}%#Flametongue Totem by {2}%", en="Improved Weapon Totems" },
    [29193] = { "Покращені тотеми зброї", "Збільшує бонус до сили атаки ближнього бою від вашого тотему буревію на {1}%, а шкоду вашого тотема язика полум'я на {2}%.#Windfury Totem by {1}%#Flametongue Totem by {2}%", en="Improved Weapon Totems" },
    [29204] = { "Невідворотна загибель", "Завдає {1} шкоди від тіні навколишнім ворогам через {2} с.#Inflicts {1} Shadow#after {2} sec", "{1} шкоди від тіні через {2} с.#{1} Shadow#after {2} sec", en="Inevitable Doom" },
    [29206] = { "Шлях зцілення", "Закляття \"Хвиля зцілення\" з імовірністю {1}% підсилить повторні ефекти цього закляття на ту саму ціль на {2}% протягом {3} с. Ефект накопичується до {4} разів.#a {1}% chance#by {2}% for {3} sec#up to {4} times", en="Healing Way" },
    [29212] = { "Каліцтво", "Збільшує інтервал між атаками ворога на {1}%, зменшує його швидкість руху на {2}% та силу на {3}%. Триває {4} с.#attacks by {1}%#movement by {2}%#Strength by {3}%#Lasts {4} sec", "Швидкість руху зменшено на {1}%.\nІнтервал між атаками збільшено на {2}%.\nСилу зменшено на {3}%.#speed reduced by {1}%#increased by {2}%#Strength reduced by {3}%", en="Cripple" },
    [29228] = { "Вогняний шок", "Миттєво обпалює ціль вогнем, завдаючи {1} шкоди вогнем одразу та ще {2} шкоди вогнем протягом {3} с.#causing {1}#{2} Fire damage over {3} sec", "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", en="Flame Shock" },
    [29235] = { "Стійкість вогняного фестивалю", "Збільшує витривалість на {1} протягом {2} год.#by {1} for {2} h", "Збільшує витривалість на {1}.#by {1}", en="Fire Festival Fortitude" },
    [29236] = { "Мерехтливий стаут", ref=436, en="Shimmer Stout" },
    [29306] = { "Заражена рана", "Збільшує отриману ворогом фізичну шкоду на {1} протягом {2} хв.#by {1} for {2} min", "Отриману фізичну шкоду збільшено на {1}.#by {1}", en="Infected Wound" },
    [29307] = { "Заражена рана", "Збільшує отриману ворогом фізичну шкоду на {1} протягом {2} хв.#by {1} for {2} min", "Отриману фізичну шкоду збільшено на {1}.#by {1}", en="Infected Wound" },
    [29325] = { "Кислотний залп", "Стріляє згустками кислоти у ворогів, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає від {1} до {2} шкоди від природи кожні {3} с.#{1} to {2} Nature#every {3} sec", en="Acid Volley" },
    [29332] = { "Підсмажена на вогні булочка", "Збільшує ймовірність завдання удару на {1}% протягом {2} год.#hit by {1}% for {2} hour", "Ймовірність завдання удару збільшено на {1}%.#by {1}%", en="Fire-toasted Bun" },
    [29333] = { "Літня ковбаска", "Збільшує шкоду заклять на {1} протягом {2} год.#spells by up to {1} for {2} hour", "Магічну шкоду збільшено на {1}.#up to {1}", en="Midsummer Sausage" },
    [29334] = { "Смажений зефір", "Збільшує зцілення заклять на {1} протягом {2} год.#spells by up to {1} for {2} hour", "Зцілення заклять збільшено на {1}.#to {1}", en="Toasted Smorc" },
    [29335] = { "Бузиновий пиріг", "Збільшує навичку захисту на {1} протягом {2} год.#Defense by {1} for {2} hour", "Навичку захисту збільшено на {1}.#by {1}", en="Elderberry Pie" },
    [29338] = { "Лють вогняного фестивалю", nil, "Збільшує ймовірність завдання критичного удару атаками та закляттями на {1}%.#by {1}%", en="Fire Festival Fury" },
    [29407] = { "Муки розуму", "Завдає ворогу шкоди від тіні та зменшує його швидкість руху протягом {1} с.#for {1} sec", "Завдає шкоди від тіні протягом {1} с.\nШвидкість руху зменшено.#over {1} sec", en="Mind Flay" },
    [29413] = { "Швидкість дальнього бою", "Збільшує швидкість атак дальнього бою на {1}%.#ranged attack speed by {1}%", en="Haste" },
    [29414] = { "Швидкість дальнього бою", "Збільшує швидкість атак дальнього бою на {1}%.#ranged attack speed by {1}%", en="Haste" },
    [29415] = { "Швидкість дальнього бою", "Збільшує швидкість атак дальнього бою на {1}%.#ranged attack speed by {1}%", en="Haste" },
    [29416] = { "Швидкість дальнього бою", "Збільшує швидкість атак дальнього бою на {1}%.#ranged attack speed by {1}%", en="Haste" },
    [29417] = { "Швидкість дальнього бою", "Збільшує швидкість атак дальнього бою на {1}%.#ranged attack speed by {1}%", en="Haste" },
    [29418] = { "Швидкість дальнього бою", "Збільшує швидкість атак дальнього бою на {1}%.#ranged attack speed by {1}%", en="Haste" },
    [29432] = { "Вогняний захист", "Поглинає від {1} до {2} шкоди від вогню. Триває {3} год.#Absorbs {1} to {2}#Lasts {3} h", "Поглинає від {1} до {2} шкоди від вогню.#Absorbs {1} to {2}", en="Fire Protection" },
    [29438] = { "Стихійна точність", "Зменшує ймовірність супротивника протистояти вашим закляттям криги та вогню на {1}%.#spells by {1}%", en="Elemental Precision" },
    [29441] = { "Магічне поглинання", "Збільшує всі ваші види опору на {1}, а всі закляття, яким ви повністю протистояли, відновлюють {2}% від вашого запасу мани.#resistances by {1}#restore {2}", en="Magic Absorption" },
    [29443] = { "Протизакляття", "Протидіє вимові закляття ворогом та унеможливлює вимову будь-яких інших заклять тієї ж школи магії протягом {1} с. Спричиняє високий рівень загрози.#cast for {1} sec", en="Counterspell" },
    [29467] = { "Сила Скари", "Накласти на наплічники чари, що збільшують шкоду і зцілення від магічних заклинань і ефектів на {1}, а також збільшують шанс завдати критичного удару закляттям на {2}%.#up to {1} and#spells by {2}%", en="Power of the Scourge" },
    [29475] = { "Витримка Скари", "Накласти на наплічники чари, що збільшують зцілення від магічних заклинань і ефектів на {1}, а також відновлюють {2} мани кожні {3} с.#up to {1} and#by {2} mana per {3} sec", en="Resilience of the Scourge" },
    [29480] = { "Стійкість Скари", "Накласти на наплічники чари, що збільшують витривалість на {1}, а також збільшують броню на {2}.#Stamina by {1} and#grants {2} armor", en="Fortitude of the Scourge" },
    [29483] = { "Міць Скари", "Накласти на наплічники чари, що збільшують силу атаки на {1}, а також збільшують шанс завдати критичного удару на {2}%.#Power by {1} and#critical strike by {2}%", en="Might of the Scourge" },
    [29484] = { "Викид павутини", nil, "Приголомшено.", en="Web Spray" },
    [29501] = { "Крижана стріла", "Шанс вразити ціль крижаною стрілою, що завдає [{1}#for {1} Frost][від {1} до {2}#for {1} to {2} Frost] шкоди від криги.", en="Frost Arrow" },
    [29506] = { "Панцир бурильника", "Поглинає {1} шкоди. Триває {2} с.#Absorbs {1} damage#Lasts {2} sec", "Поглинає {1} шкоди.#Absorbs {1} damage", en="The Burrower's Shell" },
    [29519] = { "Силітист", nil, "Силітистовий пил оточує й обтяжує вас, обмежуючи швидкість руху.", en="Silithyst" },
    [29520] = { "Відлуння Лордерона", nil, "Збільшує шкоду ближнього і дальнього бою та заклять в бою з невмерлими на {1}%.#by {1}%", en="Echoes of Lordaeron" },
    [29534] = { "Сліди силітисту", nil, "Шкоду ближнього бою та заклинань збільшено на {1}%.#by {1}%", en="Traces of Silithyst" },
    [29544] = { "Жахаючий клич", nil, "Тремтить від страху.", en="Intimidating Shout" },
    [29602] = { "Джом Ґаббар", "Збільшує силу атаки на {1} і ще на {2} кожні {3} с. Триває {4} с.#power by {1} and an additional {2} every {3} sec#Lasts {4} sec", "Сила атаки збільшується на {1} кожні {2} с.#by {1} every {2} sec", en="Jom Gabbar" },
    [29604] = { "Джом Ґаббар", nil, "Силу атаки збільшено на {1}.#by {1}", en="Jom Gabbar" },
    [29624] = { "Палюча стріла", "Шанс вразити ціль палючою стрілою, що завдає [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди від вогню.", en="Searing Arrow" },
    [29625] = { "Вогняне ядро", "Шанс вистрілити в ціль вогняним ядром, що завдає [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди від вогню.", en="Flaming Cannonball" },
    [29626] = { "Тіньова стріла", "Шанс вразити ціль дальнього бою тіньовою стрілою, що завдає [{1}#for {1} Shadow][від {1} до {2}#for {1} to {2} Shadow] шкоди тінню.", en="Shadowbolt" },
    [29633] = { "Вогняний підрив", "Шанс вразити ціль дальнього бою вогняним вибухом, що завдає [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди від вогню.", en="Fire Blast" },
    [29634] = { "Постріл шипами", "Шанс вразити ціль дальнього бою шипами, що завдають [{1}#Shot for {1} Nature][від {1} до {2}#Shot for {1} to {2} Nature] шкоди від природи.", en="Quill Shot" },
    [29635] = { "Граната", "Шанс вразити ціль дальнього бою гранатою, що завдає [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем.", en="Flaming Shell" },
    [29636] = { "Отруйний постріл", "Шанс вразити ціль в дальньому бою отрутою, що завдає [{1}#Shot for {1} Nature][від {1} до {2}#Shot for {1} to {2} Nature] шкоди від природи.", en="Venom Shot" },
    [29637] = { "Жало хранителя", "Шанс вразити ціль дальнього бою жалом хранителя, що завдає [{1}#Sting for {1} Nature][від {1} до {2}#Sting for {1} to {2} Nature] шкоди від природи.", en="Keeper's Sting" },
    [29685] = { "Жахаючий рев", "Змушує навколишніх ворогів втікати зі страху протягом {1} с.#for {1} sec", "Втікає зі страху.", en="Terrifying Roar" },
    [29846] = { "Лють вогняного фестивалю", nil, "Збільшує ймовірність завдання критичного удару атаками та закляттями на {1}%.#by {1}%", en="Fire Festival Fury" },
    [29848] = { "Поліморфія", "Перетворює ворога на вівцю, змушуючи його блукати до {1} с. Вівця не здатна атакувати та вимовляти закляття, але дуже швидко відновлює здоров'я. Будь-яка шкода поверне ціль до нормального стану. Одночасно лише одна ціль може бути під ефектом \"Поліморфії\". Діє лише на звірів, драконів, велетнів, гуманоїдів і звіряток.#up to {1} sec", "Не може атакувати та вимовляти закляття.\nШвидкість регенерації здоров'я збільшено.", en="Polymorph" },
    [29849] = { "Крижаний спалах", "Вражає ворогів неподалік кригою, знерухомлюючи їх на {1} с.#immobilizing them for up to {1} sec", "Знерухомлено", en="Frost Nova" },
    [29851] = { "Вихор", "Атакує навколишніх ворогів сталевим вихром протягом {1} с, завдаючи звичайної шкоди плюс {2}.#lasts {1} sec#plus {2}", "Атакує навколишніх ворогів, завдаючи звичайної шкоди плюс {1}.#plus {1}", en="Whirlwind" },
    [29943] = { "Знемовлення", ref=3589, en="Silence" },
    [30002] = { "Страх", "Вселяє страх у ворога, змушуючи його тікати зі страху протягом {1} с. Одночасно лише одна ціль може бути наляканою.#for up to {1} sec", "Втікає зі страху.", en="Fear" },
    [30020] = { "Перша допомога", "Відновлює {1} здоров'я за {2} с.#Heals {1} damage over {2} sec", "Відновлення {1} здоров'я щосекунди.#Healing {1} damage", en="First Aid" },
    [30088] = { "Менший знак Світанку", "Збільшує витривалість на 1 год.", "Витривалість збільшено на {1}.#by {1}", en="Lesser Mark of the Dawn" },
    [30089] = { "Знак Світанку", ref=30088, en="Mark of the Dawn" },
    [30090] = { "Більший знак Світанку", ref=30088, en="Greater Mark of the Dawn" },
    [30092] = { "Вибухова хвиля", "Вивільняє полум'яну хвилю, яка завдає шкоди вогнем навколишнім ворогам та зменшує їх швидкість руху на {1} с.#speed for {1} sec", "Швидкість руху зменшено.", en="Blast Wave" },
    [30094] = { "Крижаний спалах", "Вражає ворогів неподалік кригою, знерухомлюючи їх на {1} с.#immobilizing them for up to {1} sec", "Знерухомлено", en="Frost Nova" },
    [30095] = { "Конус холоду", "Завдає шкоди від криги ворогам у конусі перед заклиначем та зменшує їх швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Cone of Cold" },
    [30113] = { "Гнилісний укус", "Збільшує отриману ворогом шкоду на {1} протягом {2} с.#by {1} for {2} sec", "Отриману шкоду збільшено на {1}.#by {1}", en="Putrid Bite" },
    [30160] = { "Стихійне спустошення", "Критичні удари ваших бойових заклять збільшують ймовірність завдання критичного удару атаками ближнього бою на {1}% протягом {2} с.#by {1}% for {2} sec", en="Elemental Devastation" },
    [30165] = { "Стихійне спустошення", nil, "Збільшує ймовірність завдати критичного удару атаками ближнього бою на {1}%.#by {1}%", en="Elemental Devastation" },
    [30167] = { "Фіолетовий костюм огра", "Станьте величезним фіолетовим огром на {1} хв!#for {1} min", "Ви двоокий, однорогий, величезний фіолетовий людожер.", en="Purple Ogre Costume" },
    [30174] = { "Верхова черепаха", "Викликає та відпускає верхову черепаху. Може, вона й повільна, зате вам не доведеться йти пішки!", "Повільно, зате впевнено...", en="Riding Turtle" },
    [30225] = { "Знемовлення", ref=3589, en="Silence" },
    [30682] = { "Відлуння Лордерона", nil, "Збільшує шкоду ближнього і дальнього бою та заклять в бою з невмерлими на {1}%.#by {1}%", en="Echoes of Lordaeron" },
    [30683] = { "Відлуння Лордерона", nil, "Збільшує шкоду ближнього і дальнього бою та заклять в бою з невмерлими на {1}%.#by {1}%", en="Echoes of Lordaeron" },
    [30754] = { "Кенарійська прихильність", nil, "Збільшує репутацію з Кенарійським Колом, отриману за вбивство монстрів, на {1}%.#by {1}%", en="Cenarion Favor" },
